const LOGO_B64 = '';

// Editable matches — loaded from localStorage, with default preloaded data
// Migració: esborrar partits hardcoded de versions anteriors
(function(){
  try {
    const raw = localStorage.getItem('matches_v1');
    if(raw) {
      const data = JSON.parse(raw);
      const OLD = ['MOLLERUSSA','CALAFELL','MANLLEU','OLOT','CERDANYOLA','MARTINELIA','SANT CUGAT','CADI','OXIGEN'];
      const hasOld = Array.isArray(data) && data.some(function(m){
        return /^m[1-9]$/.test(m.id) || OLD.some(function(t){
          return (m.home||'').toUpperCase().indexOf(t)>=0 || (m.away||'').toUpperCase().indexOf(t)>=0;
        });
      });
      if(hasOld) { localStorage.removeItem('matches_v1'); console.log('[JOmaxPath] Partits antics eliminats'); }
    }
  } catch(e) {}
})();
let customMatches = JSON.parse(localStorage.getItem('matches_v1') || '[]');
let matchFormCasa = true;
function saveMatchesLS() { localStorage.setItem('matches_v1', JSON.stringify(customMatches)); }
function toggleMatchForm(editId) {
  const form = document.getElementById('match-form');
  const isOpen = form.style.display !== 'none';
  if(isOpen && !editId) { form.style.display='none'; return; }
  form.style.display = 'block';
  document.getElementById('mf-edit-id').value = editId || '';
  if(editId) {
    const m = customMatches.find(x=>x.id===editId);
    if(!m) return;
    document.getElementById('mf-date').value = m.date;
    document.getElementById('mf-time').value = m.time;
    document.getElementById('mf-home').value = m.home;
    document.getElementById('mf-away').value = m.away;
    document.getElementById('mf-jornada').value = m.jornada;
    document.getElementById('mf-result').value = m.result||'';
    matchFormCasa = m.casa;
  } else {
    document.getElementById('mf-date').value='';
    document.getElementById('mf-time').value='12:00';
    document.getElementById('mf-home').value='';
    document.getElementById('mf-away').value='';
    document.getElementById('mf-jornada').value='';
    document.getElementById('mf-result').value='';
    matchFormCasa = true;
  }
  setMatchCasa(matchFormCasa);
  document.getElementById('mf-date').focus();
}
function setMatchCasa(val) {
  matchFormCasa = val;
  document.getElementById('mf-casa-btn').style.cssText = val
    ? 'padding:6px 14px;border-radius:20px;font-size:11px;font-weight:700;background:rgba(16,185,129,0.2);border:1px solid rgba(16,185,129,0.4);color:#6ee7b7;cursor:pointer;'
    : 'padding:6px 14px;border-radius:20px;font-size:11px;font-weight:700;background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.1);color:var(--muted);cursor:pointer;';
  document.getElementById('mf-fora-btn').style.cssText = !val
    ? 'padding:6px 14px;border-radius:20px;font-size:11px;font-weight:700;background:rgba(239,68,68,0.2);border:1px solid rgba(239,68,68,0.4);color:#fca5a5;cursor:pointer;'
    : 'padding:6px 14px;border-radius:20px;font-size:11px;font-weight:700;background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.1);color:var(--muted);cursor:pointer;';
}
function saveMatch() {
  const date = document.getElementById('mf-date').value;
  const time = document.getElementById('mf-time').value || '00:00';
  const home = document.getElementById('mf-home').value.trim();
  const away = document.getElementById('mf-away').value.trim();
  const jornada = parseInt(document.getElementById('mf-jornada').value)||0;
  const result = document.getElementById('mf-result').value.trim();
  if(!date||!home||!away) { alert('Omple la data, equip local i visitant.'); return; }
  const editId = document.getElementById('mf-edit-id').value;
  if(editId) {
    const idx = customMatches.findIndex(x=>x.id===editId);
    if(idx>=0) customMatches[idx] = {id:editId,date,time,jornada,home,away,casa:matchFormCasa,result};
  } else {
    customMatches.push({id:'m'+Date.now(),date,time,jornada,home,away,casa:matchFormCasa,result});
  }
  customMatches.sort((a,b)=>a.date.localeCompare(b.date));
  saveMatchesLS();
  document.getElementById('match-form').style.display='none';
  renderMatches();
}
function deleteMatch(id) {
  if(!confirm('Eliminar aquest partit?')) return;
  customMatches = customMatches.filter(x=>x.id!==id);
  saveMatchesLS();
  renderMatches();
}

