function defaultSchedule() {
  const names = ['Dilluns','Dimarts','Dimecres','Dijous','Divendres','Dissabte','Diumenge'];
  const result = {};
  names.forEach((n,i) => { result[i] = {name:n, sleep:'23:00', blocks:[]}; });
  return result;
}

