document.addEventListener('DOMContentLoaded', () => {
  if(localStorage.getItem('premium_status')==='1'||localStorage.getItem('dev_mode')==='1') applyPremiumUI(true);
  setTimeout(()=>applyLanguage(currentLang), 200);

  const now = new Date();
  calYear = now.getFullYear(); calMonth = now.getMonth();

  // Set logo everywhere
  setLogos();
  // Build theme swatches
  buildThemeSwatches();
  // Apply saved theme
  const savedTheme = localStorage.getItem('theme_v1') || 'noir';
  applyTheme(savedTheme);
  // Apply saved view
  const savedView = 'pages';
  applyViewMode(savedView);
  // Restore layout mode (Ample / Compacta)
  const savedLayout = localStorage.getItem('layout_mode') || 'compacta';
  applyLayoutMode(savedLayout);
  // Render all sections
  renderProfile();
  renderGoal();
  renderMoto();
  renderProgress();
  renderStreak();
  renderWeekDates();
  renderWeekGrid();
  renderLegend();
  renderStats();
  renderExams();
  renderNextUp();
  renderCalendar();
  renderMatches();
  renderVictories();
  renderAllDayEvents();
  // AI
  initAI();
  // Ara indicator
  setInterval(updateAraIndicator, 60000);
  updateAraIndicator();
  // Observer for AI FAB
  setupAIFabObserver();
  // Render all sticky notes
  renderAllNotes();
  // Enter key for exam form
  document.getElementById('exam-name')?.addEventListener('keydown',e=>{ if(e.key==='Enter') addExam(); });
  // New features
  renderDailyQuote();
  renderTodayDashboard();
  renderHabits();
  setInterval(renderTodayDashboard, 60000); // update every min
  updatePomoDisplay();
  pomoCurrent = pomoFocusMins * 60;
  updatePomoRatioLabel(pomoFocusMins, pomoBreakMins);
  renderPomoGame();
  // Notification permission request (for pomodoro)
  if('Notification' in window && Notification.permission==='default') {
    setTimeout(()=>Notification.requestPermission(), 3000);
  }
  // QC Enter key
  document.getElementById('qc-input')?.addEventListener('keydown', e=>{ if(e.key==='Enter') saveQuickCapture(); });
  // Escape key
  document.addEventListener('keydown', e => { if(e.key==='Escape'){ closeMonthModal(); closeDayModal(); closeConfig(); } });
  // Pre-populate matches in monthEvents
  prepopulateMatches();
});

function setLogos() {
  const src = 'data:image/jpeg;base64,' + LOGO_B64;
  ['julians-logo-header','julians-logo-sm','julians-fab-img','julians-bnav-logo','julians-page-icon'].forEach(id => {
    const el = document.getElementById(id);
    if(el) el.src = src;
  });
}

