function buildThemeSwatches() {
  const grid = document.getElementById('ndw-themes-grid');
  THEMES.forEach(t => {
    const wrap = document.createElement('div');
    wrap.innerHTML = `<div class="ndw-swatch" id="sw-${t.id}" style="background:${t.bg};border-color:${t.accent}" onclick="applyTheme('${t.id}')"><div style="width:100%;height:4px;background:${t.accent};border-radius:3px;margin-top:auto;margin-bottom:2px;position:absolute;bottom:4px;left:4px;right:4px;width:calc(100%-8px);"></div></div><div class="ndw-swatch-lbl">${t.label}</div>`;
    grid.appendChild(wrap);
  });
}
function applyTheme(id) {
  document.body.className = document.body.className.replace(/theme-\S+/g,'').trim();
  if(id !== 'noir') document.body.classList.add('theme-'+id);
  localStorage.setItem('theme_v1', id);
  document.querySelectorAll('.ndw-swatch').forEach(s => s.classList.remove('active'));
  const sw = document.getElementById('sw-'+id);
  if(sw) sw.classList.add('active');
}
function toggleDrawer() {
  const d = document.getElementById('nav-drawer');
  const o = document.getElementById('nav-overlay');
  const h = document.getElementById('nav-hamburger');
  const clk = document.getElementById('nav-clock');
  const isOpening = !d.classList.contains('open');
  d.classList.toggle('open'); o.classList.toggle('open'); h.classList.toggle('open');
  if(clk) clk.style.opacity = isOpening ? '0' : '1';
  if(clk) clk.style.pointerEvents = isOpening ? 'none' : 'auto';
}
function navTo(page) {
  // Always navigate — pages mode is permanent
  document.querySelectorAll('.app-page').forEach(p => p.classList.remove('page-active'));
  const target = document.getElementById('page-'+page);
  if(target) target.classList.add('page-active');
  // Amagar FABs a la pàgina Julians per no tapar el botó d'enviar
  document.body.classList.toggle('on-julians', page === 'julians');
  document.querySelectorAll('.bnav-item').forEach((b,i) => {
    b.classList.toggle('active', ['home','horari','tasques','julians','calendari','focus'][i] === page);
  });
  document.querySelectorAll('#nav-drawer .ndw-item').forEach((item,i) => {
    item.classList.toggle('active', ['home','horari','tasques','julians','calendari','focus'][i] === page);
  });
  if (page === 'julians') {
    // No fem scroll a dalt — volem quedar-nos al final del xat
    setTimeout(() => scrollToBottom(false), 50);
    setTimeout(() => scrollToBottom(false), 200);
    setTimeout(() => scrollToBottom(false), 500);
  } else {
    window.scrollTo({top:0,behavior:'smooth'});
  }
  const drawer = document.getElementById('nav-drawer');
  if(drawer && drawer.classList.contains('open')) toggleDrawer();
}
function setViewMode(mode) {
  localStorage.setItem('view_mode', mode);
  applyViewMode(mode);
  toggleDrawer();
}
function applyViewMode(mode) {
  // Always use pages mode
  document.body.classList.add('view-pages');
  localStorage.setItem('view_mode', 'pages');
  const active = document.querySelector('.app-page.page-active');
  if(!active) navTo('home');
}

// ── Layout Mode: Ample / Compacta ─────────────────────
function setLayoutMode(mode) {
  localStorage.setItem('layout_mode', mode);
  applyLayoutMode(mode);
  toggleDrawer();
}
function applyLayoutMode(mode) {
  document.body.classList.toggle('layout-ample',    mode === 'ample');
  document.body.classList.toggle('layout-compacta', mode === 'compacta');
  const btnAmple    = document.getElementById('ndw-layout-ample');
  const btnCompacta = document.getElementById('ndw-layout-compacta');
  if (btnAmple)    btnAmple.classList.toggle('active', mode === 'ample');
  if (btnCompacta) btnCompacta.classList.toggle('active', mode === 'compacta');

  // Helper: força estil inline (guanya als !important dels <style> del HTML)
  function amp(el, prop, val) { if(el) el.style.setProperty(prop, val, 'important'); }
  function rst(el, prop)      { if(el) el.style.removeProperty(prop); }
  function ampAll(sel, prop, val) { document.querySelectorAll(sel).forEach(e => amp(e, prop, val)); }
  function rstAll(sel, prop)      { document.querySelectorAll(sel).forEach(e => rst(e, prop)); }
  function ampCols(sel1, sel2, prop, val) { ampAll(sel1, prop, val); ampAll(sel2, prop, val); }
  function rstCols(sel1, sel2, prop)      { rstAll(sel1, prop); rstAll(sel2, prop); }

  if (mode === 'ample') {
    // ── "Ara mateix": 3 quadrats en fila ──
    amp(document.getElementById('today-grid'), 'grid-template-columns', '1fr 1fr 1fr');

    // ── Home: una columna (una secció per fila) ──
    ampAll('.home-two-col', 'grid-template-columns', '1fr');
    ampAll('.home-two-col', 'display', 'grid');
    ampCols('.home-col-left', '.home-col-right', 'width', '100%');

    // ── Focus: una columna ──
    ampAll('.focus-two-col', 'grid-template-columns', '1fr');
    ampAll('.focus-two-col', 'display', 'grid');
    ampCols('.focus-col-left', '.focus-col-right', 'width', '100%');
    ampCols('.focus-col-left', '.focus-col-right', 'max-width', '100%');
    ampCols('.focus-col-left', '.focus-col-right', 'flex', 'none');

    // ── Calendari: una columna (calendari gran, partits a sota) ──
    ampAll('.cal-two-col', 'grid-template-columns', '1fr');
    ampAll('.cal-two-col', 'display', 'grid');

    // ── Horari: Dl-Dv (5 col) dalt, Ds-Dg baix amples ──
    const weekGrid = document.getElementById('week-grid');
    if (weekGrid) {
      amp(weekGrid, 'grid-template-columns', 'repeat(5, 1fr)');
      amp(weekGrid, 'gap', '12px');
      weekGrid.querySelectorAll('.day-card').forEach((c, i) => {
        if (i === 5) c.style.setProperty('grid-column', '1 / 3', 'important');
        else if (i === 6) c.style.setProperty('grid-column', '3 / 6', 'important');
        else c.style.removeProperty('grid-column');
      });
    }

  } else {
    // ── Restaura tot ──
    rst(document.getElementById('today-grid'), 'grid-template-columns');

    ['grid-template-columns','display'].forEach(p => {
      rstAll('.home-two-col', p);
      rstAll('.focus-two-col', p);
      rstAll('.cal-two-col', p);
    });
    ['width','max-width','flex'].forEach(p => {
      rstCols('.home-col-left', '.home-col-right', p);
      rstCols('.focus-col-left', '.focus-col-right', p);
    });

    const weekGrid = document.getElementById('week-grid');
    if (weekGrid) {
      rst(weekGrid, 'grid-template-columns');
      rst(weekGrid, 'gap');
      weekGrid.querySelectorAll('.day-card').forEach(c => c.style.removeProperty('grid-column'));
    }
  }
}

