const TIMED_COLORS = {
  'tec-purple': {bar:'#7C5CBF', label:{ca:'Deep Work / Prog',es:'Deep Work',en:'Deep Work'}},
  'tec-blue':   {bar:'#3B6EA5', label:{ca:'Reunió / Classe',es:'Reunión',en:'Meeting'}},
  'tec-green':  {bar:'#2E7D52', label:{ca:'Esport / Gimnàs',es:'Deporte',en:'Sport'}},
  'tec-orange': {bar:'#B5622A', label:{ca:'Menjars / Pauses',es:'Comidas',en:'Meals'}},
  'tec-red':    {bar:'#A03030', label:{ca:'Urgent / Examen',es:'Urgente',en:'Urgent'}},
  'tec-pink':   {bar:'#9B3070', label:{ca:'Personal',es:'Personal',en:'Personal'}},
  'tec-teal':   {bar:'#1E7068', label:{ca:'Salut / Benestar',es:'Salud',en:'Health'}},
};

let timedEditId = null;
let timedEditDateKey = null;
let timedSelColor = 'tec-purple';

function persistTimedEvents() {
  localStorage.setItem('timed_events_v1', JSON.stringify(timedEvents));
}

function openTimedModal(dateKey, defaultStart) {
  timedEditId = null; timedEditDateKey = dateKey;
  const dayLabel = {ca:'Nou event horari',es:'Nuevo evento horario',en:'New timed event'}[currentLang];
  document.getElementById('timed-modal-title').textContent = '⏱ ' + dayLabel;
  document.getElementById('tm-title').value = '';
  document.getElementById('tm-start').value = defaultStart || '09:00';
  document.getElementById('tm-end').value   = defaultStart ? addHour(defaultStart) : '10:00';
  document.getElementById('timed-del-btn').style.display = 'none';
  timedSelColor = 'tec-purple'; updateTimedColors();
  document.getElementById('timed-modal-overlay').classList.add('open');
  setTimeout(()=>document.getElementById('tm-title').focus(), 80);
}

function openTimedEdit(id) {
  const ev = timedEvents.find(e=>e.id===id); if(!ev) return;
  timedEditId = id; timedEditDateKey = ev.date;
  document.getElementById('timed-modal-title').textContent = '⏱ Editar event';
  document.getElementById('tm-title').value = ev.title;
  document.getElementById('tm-start').value = ev.start;
  document.getElementById('tm-end').value   = ev.end;
  document.getElementById('timed-del-btn').style.display = 'block';
  timedSelColor = ev.color || 'tec-purple'; updateTimedColors();
  document.getElementById('timed-modal-overlay').classList.add('open');
}

function closeTimedModal() {
  document.getElementById('timed-modal-overlay').classList.remove('open');
  timedEditId = null;
}

function saveTimedEvent() {
  const title = document.getElementById('tm-title').value.trim();
  if(!title) { document.getElementById('tm-title').focus(); return; }
  const start = document.getElementById('tm-start').value;
  const end   = document.getElementById('tm-end').value;
  if(start >= end) { alert({ca:'L\'hora fi ha de ser posterior a l\'inici.',es:'La hora fin debe ser después del inicio.',en:'End time must be after start.'}[currentLang]); return; }
  if(timedEditId) {
    const idx = timedEvents.findIndex(e=>e.id===timedEditId);
    if(idx!==-1) timedEvents[idx] = {...timedEvents[idx], title, start, end, color:timedSelColor};
  } else {
    timedEvents.push({id:'te'+Date.now(), title, date:timedEditDateKey, start, end, color:timedSelColor});
  }
  persistTimedEvents();
  closeTimedModal();
  renderTimedEventsForDate(timedEditDateKey);
}

function deleteTimedEvent() {
  if(!timedEditId) return;
  timedEvents = timedEvents.filter(e=>e.id!==timedEditId);
  persistTimedEvents();
  closeTimedModal();
  renderTimedEventsForDate(timedEditDateKey);
}

function pickTimedColor(btn) {
  timedSelColor = btn.dataset.c; updateTimedColors();
}

function updateTimedColors() {
  document.querySelectorAll('.tcbtn').forEach(b=>b.classList.toggle('sel', b.dataset.c===timedSelColor));
}

function addHour(time) {
  const [h,m] = time.split(':').map(Number);
  return `${String(Math.min(h+1,23)).padStart(2,'0')}:${String(m).padStart(2,'0')}`;
}

function renderTimedEventsSection(dateKey, containerEl) {
  const evs = timedEvents.filter(e=>e.date===dateKey).sort((a,b)=>a.start.localeCompare(b.start));
  
  const existing = containerEl.querySelector('.timed-events-section');
  if(existing) existing.remove();
  
  const section = document.createElement('div');
  section.className = 'timed-events-section';
  const addLbl = {ca:'+ Afegir',es:'+ Añadir',en:'+ Add'}[currentLang];
  const titleLbl = {ca:'Events horaris',es:'Eventos horarios',en:'Timed events'}[currentLang];
  
  section.innerHTML = `
    <div class="timed-events-label">
      <span>${titleLbl}</span>
      <button onclick="openTimedModal('${dateKey}')">⏱ ${addLbl}</button>
    </div>
    <div class="timed-ev-list" id="tev-${dateKey.replace(/-/g,'')}">
      ${evs.map(ev=>`
        <div class="timed-ev-item ${ev.color||'tec-purple'}${ev.color==='tec-red'?' exam-timed-ev':''}" onclick="openTimedEdit('${ev.id}')">
          <div class="timed-ev-color-bar"></div>
          <div class="timed-ev-body">
            <div class="timed-ev-title">${ev.title}</div>
            <div class="timed-ev-time">${ev.start} — ${ev.end}</div>
          </div>
          <button class="timed-ev-del" onclick="event.stopPropagation();quickDeleteTimedEvent('${ev.id}','${dateKey}')">×</button>
        </div>
      `).join('')}
    </div>
  `;
  containerEl.appendChild(section);
}

function renderTimedEventsForDate(dateKey) {
  // Find which day card has this date
  for(let i=0;i<7;i++){
    if(getDateForCard(i)===dateKey){
      const body = document.getElementById('day-body-'+i);
      if(body) renderTimedEventsSection(dateKey, body);
      break;
    }
  }
}

function quickDeleteTimedEvent(id, dateKey) {
  timedEvents = timedEvents.filter(e=>e.id!==id);
  persistTimedEvents();
  renderTimedEventsForDate(dateKey);
}

function renderAllTimedEvents() {
  for(let i=0;i<7;i++){
    const dateKey = getDateForCard(i);
    const body = document.getElementById('day-body-'+i);
    if(body) renderTimedEventsSection(dateKey, body);
  }
}

function renderWeekGrid() {
  const grid = document.getElementById('week-grid'); if(!grid) return;
  grid.innerHTML='';
  const today = toLocalDateKey(new Date());
  const dayNames=['Dilluns','Dimarts','Dimecres','Dijous','Divendres','Dissabte','Diumenge'];
  for(let i=0;i<7;i++){
    const sched = daySchedule[i] || {name:dayNames[i],sleep:'23:00',blocks:[]};
    const dateKey = getDateForCard(i);
    const dateParts = dateKey.split('-');
    const dateLabel = `${parseInt(dateParts[2])} ${['gen','feb','mar','abr','mai','jun','jul','ago','set','oct','nov','des'][parseInt(dateParts[1])-1]}`;
    const isToday = dateKey===today;
    const isWeekend = i>=5;
    const card = document.createElement('div');
    const cardEvs = monthEvents[dateKey] || [];
    const cardHasExam = cardEvs.some(ev => ev.type === 'exam');
    const cardHasWork = !cardHasExam && cardEvs.some(ev => ev.type === 'treball');
    card.className = 'day-card'+(isWeekend?' weekend':'')+(isToday?' today-card':'')+(cardHasExam?' exam-day':'')+(cardHasWork?' work-day':'');
    card.id = 'day-card-'+i;
    // Badge
    const badge = dayBadges[i] || '';
    const customHtml = `<span class="day-custom-badge" id="badge-${i}" onclick="editBadge(${i},event)">${badge}</span>`;
    const dateHtml = `<span class="day-date-badge${isToday?' today':''}">${dateLabel}</span>`;
    // Blocks
    const now = new Date();
    const nowMins = now.getHours()*60+now.getMinutes();
    let blocksHtml = (sched.blocks||[]).map(b=>{
      const col = getBlockTypeColor(b.t);
      const isProg = b.t==='prog';
      const isAra = isToday && b.time && isCurrentBlock(b.time, nowMins);
      return `<div class="block block-${b.t||'rest'}${isAra?' block-ara':''}">
        <div class="block-time">${b.time||''}</div>
        <div class="block-content">
          <div class="block-label">${b.label||''}${isProg?'<span class="prog-badge">PROG</span>':''}</div>
          ${b.note?`<div class="block-note">${b.note}</div>`:''}
        </div>
      </div>`;
    }).join('');
    // Day events (combined dayEvents + monthEvents)
    const eventsHtml = renderDayEventsHtml(i, dateKey);
    card.innerHTML = `
      <div class="day-header">
        <div><span class="day-name" onclick="editDayName(${i},event)" title="Clic per editar">${sched.name||dayNames[i]}</span>${dateHtml}${customHtml}</div>
        <span class="day-sleep">🌙 ${sched.sleep||'23:00'}</span>
      </div>
      <div class="day-body" id="day-body-${i}">
        ${blocksHtml}
        <div class="day-events" id="day-events-${i}">${eventsHtml}</div>
      </div>`;
    grid.appendChild(card);
  }
  renderAllDayBadges();
  updateAraIndicator();
  renderAllTimedEvents();
  // Re-aplica el mode de layout (els cards acaben de ser recreats)
  const lm = localStorage.getItem('layout_mode') || 'compacta';
  if (lm === 'ample') {
    grid.style.setProperty('grid-template-columns', 'repeat(5, 1fr)', 'important');
    grid.style.setProperty('gap', '12px', 'important');
    const cards = grid.querySelectorAll('.day-card');
    cards.forEach((c, i) => {
      if (i === 5) c.style.setProperty('grid-column', '1 / 3', 'important');
      else if (i === 6) c.style.setProperty('grid-column', '3 / 6', 'important');
      else c.style.removeProperty('grid-column');
    });
  }
}

function editDayName(dayIdx, e) {
  e.stopPropagation();
  const dayNames=['Dilluns','Dimarts','Dimecres','Dijous','Divendres','Dissabte','Diumenge'];
  const current = daySchedule[dayIdx]?.name || dayNames[dayIdx];
  const newName = prompt("Edita l'etiqueta del dia:", current);
  if(newName === null) return; // cancel
  if(!daySchedule[dayIdx]) daySchedule[dayIdx] = {name:dayNames[dayIdx], sleep:'23:00', blocks:[]};
  daySchedule[dayIdx].name = newName.trim() || dayNames[dayIdx];
  localStorage.setItem('schedule_v2', JSON.stringify(daySchedule));
  renderWeekGrid();
}

function isCurrentBlock(timeStr, nowMins) {
  if(!timeStr) return false;
  const parts = timeStr.split('-');
  if(parts.length<2) return false;
  const [startH,startM] = parts[0].split(':').map(Number);
  const [endH,endM] = parts[1].split(':').map(Number);
  return nowMins >= startH*60+(startM||0) && nowMins <= endH*60+(endM||0);
}

function renderDayEventsHtml(dayIdx, dateKey) {
  const all = [];
  // From dayEvents
  (dayEvents[dayIdx]||[]).forEach(ev => { all.push({...ev, src:'day', idx:dayIdx}); });
  // From monthEvents for this date
  (monthEvents[dateKey]||[]).forEach(ev => { all.push({...ev, src:'month'}); });
  // Sort by time
  all.sort((a,b) => { const ta=a.time||'99:99', tb=b.time||'99:99'; return ta.localeCompare(tb); });
  return all.map(ev => {
    const typeClassMap = {exam:'exam-event',treball:'treball-event',tasca:'tasca-event',personal:'personal-event',deures:'deures-event'};
    const extraClass = typeClassMap[ev.type] ? ' '+typeClassMap[ev.type] : '';
    return `
    <div class="day-event-item${extraClass}">
      <span class="ev-icon">${getEvIcon(ev)}</span>
      <span class="ev-text">${ev.text||ev.desc||''}</span>
      ${ev.time?`<span class="ev-time">${ev.time}</span>`:''}
      <span class="ev-del" onclick="deleteDayEventItem(this,'${ev.src}',${ev.src==='day'?ev.idx:"'"+dateKey+"'"},'${ev.id||''}')">×</span>
    </div>`;
  }).join('');
}

function getEvIcon(ev) {
  const t = ev.type||'';
  if(t==='exam'||t==='📝 Examen') return '📝';
  if(t==='deures'||t==='📚 Escolar') return '📚';
  if(t==='treball') return '📄';
  if(t==='tasca') return '🗂️';
  if(t==='personal') return '🙋';
  if(t==='partit'||t==='🏒 Esport') return '🏒';
  if(t==='💻 Programació') return '💻';
  if(t==='🤖 Robotech') return '🤖';
  if(t==='📦 Entrega') return '📦';
  const icon = t.split(' ')[0];
  return /\p{Emoji}/u.test(icon) ? icon : '📌';
}

function deleteDayEventItem(el, src, keyOrIdx, id) {
  if(src==='day'){
    const idx = parseInt(keyOrIdx);
    if(!dayEvents[idx]) return;
    if(id) dayEvents[idx] = dayEvents[idx].filter(e=>e.id!==id);
    else dayEvents[idx].splice(0,1);
    localStorage.setItem('day_events_v2',JSON.stringify(dayEvents));
  } else {
    const dateKey = keyOrIdx;
    if(!monthEvents[dateKey]) return;
    monthEvents[dateKey] = monthEvents[dateKey].filter(e=>e.id!==id);
    if(!monthEvents[dateKey].length) delete monthEvents[dateKey];
    localStorage.setItem('month_events_v2',JSON.stringify(monthEvents));
    renderCalendar();
  }
  refreshAllDayCards();
}

function refreshAllDayCards() {
  for(let i=0;i<7;i++){
    const dateKey = getDateForCard(i);
    const cont = document.getElementById('day-events-'+i);
    if(cont) cont.innerHTML = renderDayEventsHtml(i, dateKey);
  }
}

function renderAllDayEvents() { refreshAllDayCards(); }

function updateAraIndicator() {
  const now = new Date();
  const nowMins = now.getHours()*60+now.getMinutes();
  const today = toLocalDateKey(now);
  for(let i=0;i<7;i++){
    const dateKey = getDateForCard(i);
    const body = document.getElementById('day-body-'+i);
    if(!body) continue;
    body.querySelectorAll('.block').forEach(b => b.classList.remove('block-ara'));
    if(dateKey===today){
      const sched = daySchedule[i]||{blocks:[]};
      body.querySelectorAll('.block').forEach((b,idx)=>{
        const bl = sched.blocks[idx];
        if(bl && bl.time && isCurrentBlock(bl.time,nowMins)) b.classList.add('block-ara');
      });
    }
  }
}

