//  EXAMS / TASKS
// ══════════════════════════════════════════════════════
function toggleExamForm() {
  const f=document.getElementById('exam-form');
  f.classList.toggle('open');
  if(f.classList.contains('open')) setTimeout(()=>document.getElementById('exam-name').focus(),50);
}

function deleteExam(id) {
  const exam = examList.find(e=>e.id===id);
  examList=examList.filter(e=>e.id!==id);
  localStorage.setItem('exams_v3',JSON.stringify(examList));
  // Remove from monthEvents
  if(exam && exam.date) {
    const evId = 'exam_'+exam.id;
    if(monthEvents[exam.date]) {
      monthEvents[exam.date] = monthEvents[exam.date].filter(ev=>ev.id!==evId);
      if(!monthEvents[exam.date].length) delete monthEvents[exam.date];
      localStorage.setItem('month_events_v2',JSON.stringify(monthEvents));
    }
  }
  renderExams(); renderNextUp(); renderCalendar(); refreshAllDayCards();
}
function toggleExamDone(id) {
  const e=examList.find(e=>e.id===id);
  if(e){ e.done=!e.done; localStorage.setItem('exams_v3',JSON.stringify(examList)); renderExams(); renderNextUp(); }
}

function saveExamEdit(id) {
  const ex=examList.find(e=>e.id===id); if(!ex) return;
  const oldDate = ex.date;
  ex.name=document.getElementById('ei-name-'+id).value.trim()||ex.name;
  ex.date=document.getElementById('ei-date-'+id).value;
  ex.type=document.getElementById('ei-type-'+id).value;
  localStorage.setItem('exams_v3',JSON.stringify(examList));
  // Update monthEvents
  const evId='exam_'+id;
  if(oldDate && monthEvents[oldDate]) {
    monthEvents[oldDate]=monthEvents[oldDate].filter(ev=>ev.id!==evId);
    if(!monthEvents[oldDate].length) delete monthEvents[oldDate];
  }
  if(ex.date) {
    if(!monthEvents[ex.date]) monthEvents[ex.date]=[];
    if(!monthEvents[ex.date].find(ev=>ev.id===evId)) {
      const editIcon = {deures:'📚',treball:'📄',tasca:'🗂️',personal:'🙋'}[ex.type]||'📝';
      monthEvents[ex.date].push({id:evId,text:editIcon+' '+ex.name,time:'',type:ex.type||'tasca'});
    }
  }
  localStorage.setItem('month_events_v2',JSON.stringify(monthEvents));
  renderExams(); renderNextUp(); renderCalendar(); refreshAllDayCards();
}

// ══════════════════════════════════════════════════════
//  NEXT UP
// ══════════════════════════════════════════════════════
function renderNextUp() {
  const today=new Date(); today.setHours(0,0,0,0);
  const pending=examList.filter(e=>!e.done&&e.date).sort((a,b)=>a.date.localeCompare(b.date));
  const bar=document.getElementById('next-up-bar');
  if(!pending.length){bar.style.display='none';return;}
  const next=pending[0];
  const d=new Date(next.date+'T00:00:00'); const diff=Math.ceil((d-today)/86400000);
  const L = {
    ca:{past:'Passat!',today:'Per avui!',tomorrow:'Per demà',inN:'En {n} dies',cd_past:'PASSAT',cd_today:'AVUI',cd_tomorrow:'DEMÀ'},
    es:{past:'¡Pasado!',today:'¡Para hoy!',tomorrow:'Para mañana',inN:'En {n} días',cd_past:'PASADO',cd_today:'HOY',cd_tomorrow:'MAÑANA'},
    en:{past:'Past!',today:'Due today!',tomorrow:'Due tomorrow',inN:'In {n} days',cd_past:'PAST',cd_today:'TODAY',cd_tomorrow:'TOMORROW'}
  }[currentLang]||{};
  let when='', cd='';
  if(diff<0){when=L.past;cd=L.cd_past;}
  else if(diff===0){when=L.today;cd=L.cd_today;}
  else if(diff===1){when=L.tomorrow;cd=L.cd_tomorrow;}
  else{when=L.inN.replace('{n}',diff);cd=`${diff}d`;}
  document.getElementById('next-up-text').textContent=next.name;
  document.getElementById('next-up-when').textContent=when;
  document.getElementById('next-up-cd').textContent=cd;
  const bar2 = document.getElementById('next-up-bar');
  if(diff <= 1) bar2.style.animation = 'urgentPulse 2s ease-in-out infinite';
  else bar2.style.animation = '';
  bar.style.display='flex';
}

