function prepopulateMatches() {
  customMatches.forEach(m=>{
    const ev={id:'match_'+m.date+'_'+m.jornada,text:'🏒 '+(m.jornada?'J'+m.jornada+': ':'')+(m.casa?m.home+' vs '+m.away:m.away+' (fora)'),time:m.time,type:'partit'};
    if(!monthEvents[m.date]) monthEvents[m.date]=[];
    if(!monthEvents[m.date].find(e=>e.id===ev.id)) monthEvents[m.date].push(ev);
  });
  localStorage.setItem('month_events_v2',JSON.stringify(monthEvents));
}
function renderCalendar() {
  const grid=document.getElementById('cal-grid'); if(!grid) return;
  const monthNames=getMonthNames();
  document.getElementById('cal-month-title').textContent=monthNames[calMonth]+' '+calYear;
  grid.innerHTML='';
  const today=toLocalDateKey(new Date());
  const firstDay=new Date(calYear,calMonth,1);
  const dow=firstDay.getDay(); // 0=Sun
  const startOffset=dow===0?6:dow-1;
  const daysInMonth=new Date(calYear,calMonth+1,0).getDate();
  for(let i=0;i<startOffset;i++){ const c=document.createElement('div');c.className='cal-cell empty';grid.appendChild(c); }
  const moreLabel={ca:'més',es:'más',en:'more'}[currentLang]||'more';
  for(let d=1;d<=daysInMonth;d++){
    const dk=`${calYear}-${String(calMonth+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    const isToday=dk===today;
    const dow2=new Date(calYear,calMonth,d).getDay();
    const isWE=dow2===0||dow2===6;
    const evs=monthEvents[dk]||[];
    const cell=document.createElement('div');
    const hasExam = evs.some(ev => ev.type === 'exam');
    cell.className='cal-cell'+(isToday?' today':'')+(isWE?' weekend-day':'')+(evs.length?' has-events':'')+(hasExam?' has-exam':'');
    const typeIconsMap = {exam:'📝 ',deures:'📚 ',treball:'📄 ',tasca:'🗂️ ',personal:'🙋 ',partit:'🏒 '};
    const dotsHtml=evs.slice(0,3).map(ev=>`<div class="cal-event-dot type-${ev.type}">${typeIconsMap[ev.type]||''}${ev.text?.substring(0,16)||''}</div>`).join('');
    const moreHtml=evs.length>3?`<div class="cal-more">+${evs.length-3} ${moreLabel}</div>`:'';
    cell.innerHTML=`<div class="cal-day-num">${d}</div>${dotsHtml}${moreHtml}`;
    cell.onclick=()=>openMonthModal(dk,d);
    grid.appendChild(cell);
  }
}
function changeCalMonth(d){ calMonth+=d; if(calMonth<0){calMonth=11;calYear--;} if(calMonth>11){calMonth=0;calYear++;} renderCalendar(); }
function openMonthModal(dateKey,day) {
  activeCalDate=dateKey;
  const monthNames=getMonthNames();
  const dayLabel={ca:'Dia',es:'Día',en:'Day'}[currentLang]||'Day';
  document.getElementById('mm-title').textContent=`${dayLabel} ${day}`;
  document.getElementById('mm-sub').textContent=monthNames[calMonth]+' '+calYear;
  document.getElementById('mm-text').value='';
  document.getElementById('mm-time').value='';
  renderMonthEventList();
  document.getElementById('month-modal-overlay').classList.add('open');
  setTimeout(()=>document.getElementById('mm-text').focus(),100);
}
function closeMonthModal(){ document.getElementById('month-modal-overlay').classList.remove('open'); activeCalDate=null; }
function renderMonthEventList() {
  const list=document.getElementById('mm-list');
  const evs=(monthEvents[activeCalDate]||[]).sort((a,b)=>(a.time||'99:99').localeCompare(b.time||'99:99'));
  list.innerHTML=evs.map(ev=>`<div class="month-event-row">
    <span class="mev-icon">${getEvIcon(ev)}</span>
    <span class="mev-text">${ev.text||''}</span>
    ${ev.time?`<span class="mev-time">${ev.time}</span>`:''}
    <span class="mev-del" onclick="deleteMonthEvent('${ev.id||''}')">×</span>
  </div>`).join('') || '<div style="color:var(--muted);font-size:12px;padding:8px 0;">Cap event</div>';
}
function saveMonthEvent() {
  const text=document.getElementById('mm-text').value.trim();
  if(!text||!activeCalDate) return;
  const ev={id:Date.now()+'',text,time:document.getElementById('mm-time').value,type:document.getElementById('mm-type').value};
  if(!monthEvents[activeCalDate]) monthEvents[activeCalDate]=[];
  monthEvents[activeCalDate].push(ev);
  localStorage.setItem('month_events_v2',JSON.stringify(monthEvents));
  document.getElementById('mm-text').value='';
  renderMonthEventList(); renderCalendar(); refreshAllDayCards(); navigateToDate(activeCalDate);
}
function deleteMonthEvent(id) {
  if(!activeCalDate) return;
  monthEvents[activeCalDate]=(monthEvents[activeCalDate]||[]).filter(e=>e.id!==id);
  if(!monthEvents[activeCalDate].length) delete monthEvents[activeCalDate];
  localStorage.setItem('month_events_v2',JSON.stringify(monthEvents));
  renderMonthEventList(); renderCalendar(); refreshAllDayCards();
}
function navigateToDate(dateKey) {
  const target=new Date(dateKey+'T12:00:00');
  const ws=getWeekStart(weekOffset);
  const we=new Date(ws); we.setDate(ws.getDate()+6);
  if(target>=ws&&target<=we) return;
  const now=new Date(); now.setHours(12,0,0,0);
  const nowMon=new Date(now); const dow=now.getDay(); nowMon.setDate(now.getDate()+(dow===0?-6:1-dow));
  const diff=Math.round((target-nowMon)/(7*86400000));
  weekOffset=diff;
  renderWeekDates(); renderWeekGrid();
}

// ══════════════════════════════════════════════════════
//  MATCHES
// ══════════════════════════════════════════════════════
function renderMatches() {
  const today=new Date(); today.setHours(0,0,0,0);
  const list=document.getElementById('matches-list');
  if(!list) return;
  const monthN = {
    ca:['gen','feb','mar','abr','mai','jun','jul','ago','set','oct','nov','des'],
    es:['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'],
    en:['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec']
  }[currentLang]||['gen','feb','mar','abr','mai','jun','jul','ago','set','oct','nov','des'];
  const noMatches = {ca:'Cap partit afegit. Prem + AFEGIR PARTIT per començar.',es:'No hay partidos. Pulsa + AÑADIR PARTIDO para empezar.',en:'No matches added. Press + ADD MATCH to start.'}[currentLang];
  const labelCasa = {ca:'CASA',es:'CASA',en:'HOME'}[currentLang];
  const labelFora = {ca:'FORA',es:'FUERA',en:'AWAY'}[currentLang];
  const labelAvui = {ca:'AVUI!',es:'¡HOY!',en:'TODAY!'}[currentLang];
  const labelDema = {ca:'DEMÀ',es:'MAÑANA',en:'TOMORROW'}[currentLang];
  const labelPascat = {ca:'Passat',es:'Pasado',en:'Past'}[currentLang];
  const labelIn = {ca:'En',es:'En',en:'In'}[currentLang];
  const labelDays = {ca:'d',es:'d',en:'d'}[currentLang];
  const labelJornada = {ca:'Jornada',es:'Jornada',en:'Round'}[currentLang];
  let nextFound=false;
  if(!customMatches.length){list.innerHTML=`<div style="text-align:center;color:var(--muted);font-size:13px;padding:30px;">${noMatches}</div>`;return;}
  list.innerHTML=customMatches.map(m=>{
    const d=new Date(m.date+'T00:00:00'); const diff=Math.ceil((d-today)/86400000);
    let cd='', cdClass='';
    if(diff<0){cd=labelPascat;cdClass='passat';}
    else if(diff===0){cd=labelAvui;cdClass='avui';}
    else if(diff===1){cd=labelDema;cdClass='propera';}
    else if(diff<=7&&!nextFound){cd=`${labelIn} ${diff}${labelDays}`;cdClass='propera';nextFound=true;}
    else{cd=`${labelIn} ${diff}${labelDays}`;cdClass='';}
    const dp=m.date.split('-');
    const dateStr=`${parseInt(dp[2])} ${monthN[parseInt(dp[1])-1]}`;
    const resultHtml = m.result ? `<div style="font-family:'Space Mono',monospace;font-size:12px;font-weight:700;color:#6ee7b7;margin-top:3px;">⚽ ${m.result}</div>` : '';
    return `<div class="match-item" style="${diff<0?'opacity:0.5':''}">
      <div class="match-date">${dateStr}<br><span style="color:var(--accent2)">${m.time}</span></div>
      <div class="match-info">
        ${m.jornada?`<div class="match-name">${labelJornada} ${m.jornada}</div>`:''}
        <div class="match-teams">${m.home}<br><span style="color:var(--muted)">vs</span> ${m.away}</div>
        ${resultHtml}
      </div>
      <span class="match-tag ${m.casa?'casa':'fora'}">${m.casa?labelCasa:labelFora}</span>
      <span class="match-countdown ${cdClass}">${cd}</span>
      <div style="display:flex;flex-direction:column;gap:4px;margin-left:6px;flex-shrink:0;">
        <button onclick="toggleMatchForm('${m.id}')" title="Editar" style="background:rgba(124,58,237,0.12);border:1px solid rgba(124,58,237,0.2);color:var(--accent2);width:26px;height:26px;border-radius:6px;cursor:pointer;font-size:12px;">✎</button>
        <button onclick="deleteMatch('${m.id}')" title="Eliminar" style="background:rgba(239,68,68,0.08);border:1px solid rgba(239,68,68,0.2);color:#fca5a5;width:26px;height:26px;border-radius:6px;cursor:pointer;font-size:12px;">×</button>
      </div>
    </div>`;
  }).join('');
}

