function getVicKey(offset=0) {
  const d=new Date(); d.setHours(12,0,0,0);
  const dow=d.getDay(); d.setDate(d.getDate()+(dow===0?-6:1-dow)+offset*7);
  return toLocalDateKey(d);
}
function renderVictories() {
  const key=getVicKey(victoriesWeekOffset);
  const data=victoriesData[key]||['','',''];
  ['v1','v2','v3'].forEach((id,i)=>{ document.getElementById(id).value=data[i]||''; });
  const L={
    ca:{cur:'Setmana actual',prev:'Setmana passada',next:'Setmana que ve',nWeeks:'Fa {n} setmanes'},
    es:{cur:'Semana actual',prev:'Semana pasada',next:'Semana que viene',nWeeks:'Hace {n} semanas'},
    en:{cur:'Current week',prev:'Last week',next:'Next week',nWeeks:'{n} weeks ago'}
  }[currentLang]||{};
  const label=victoriesWeekOffset===0?L.cur:victoriesWeekOffset===-1?L.prev:victoriesWeekOffset===1?L.next:L.nWeeks.replace('{n}',Math.abs(victoriesWeekOffset));
  document.getElementById('victories-week-label').textContent=label;
}
function changeVictoriesWeek(d){ victoriesWeekOffset+=d; renderVictories(); }
function saveVictories() {
  const key=getVicKey(victoriesWeekOffset);
  victoriesData[key]=[document.getElementById('v1').value,document.getElementById('v2').value,document.getElementById('v3').value];
  localStorage.setItem('victories_v2',JSON.stringify(victoriesData));
  const msg=document.getElementById('victories-saved'); msg.style.display='block';
  setTimeout(()=>msg.style.display='none',2000);
}

// ══════════════════════════════════════════════════════
//  STICKY NOTES
// ══════════════════════════════════════════════════════
function toggleNotePicker() { document.getElementById('note-picker').classList.toggle('open'); }
function createNote(color) {
  document.getElementById('note-picker').classList.remove('open');
  const id='note_'+Date.now();
  const rot=(Math.random()*6-3).toFixed(1)+'deg';
  const x=Math.random()*(window.innerWidth-230)+10;
  const y=Math.random()*(window.innerHeight-180)+window.scrollY+80;
  const note={id,color,text:'',x,y,rot,w:210,h:130};
  stickyNotes.push(note);
  localStorage.setItem('sticky_notes_v2',JSON.stringify(stickyNotes));
  renderNote(note);
}
function renderNote(n) {
  const overlay=document.getElementById('notes-overlay');
  const el=document.createElement('div');
  el.className=`sticky color-${n.color}`;
  el.id=n.id;
  el.style=`left:${n.x}px;top:${n.y}px;--rot:${n.rot};width:${n.w}px;min-height:${n.h}px;`;
  el.innerHTML=`<div class="sticky-header"><span class="sticky-drag-hint">···</span><button class="sticky-close" onclick="deleteNote('${n.id}')">×</button></div><textarea class="sticky-textarea" placeholder="Escriu aquí...">${n.text||''}</textarea><div class="sticky-footer">📌</div>`;
  overlay.appendChild(el);
  // Drag
  const header=el.querySelector('.sticky-header');
  let dx,dy,dragging=false;
  header.onmousedown=e=>{
    dragging=true;dx=e.clientX-el.offsetLeft;dy=e.clientY-el.offsetTop;el.classList.add('dragging');e.preventDefault();
  };
  document.addEventListener('mousemove',e=>{if(!dragging)return;el.style.left=(e.clientX-dx)+'px';el.style.top=(e.clientY-dy)+'px';});
  document.addEventListener('mouseup',e=>{if(!dragging)return;dragging=false;el.classList.remove('dragging');saveNotePos(n.id,el);});
  // Touch drag
  header.ontouchstart=e=>{const t=e.touches[0];dx=t.clientX-el.offsetLeft;dy=t.clientY-el.offsetTop;};
  el.ontouchmove=e=>{e.preventDefault();const t=e.touches[0];el.style.left=(t.clientX-dx)+'px';el.style.top=(t.clientY-dy)+'px';};
  el.ontouchend=()=>saveNotePos(n.id,el);
  // Text save
  el.querySelector('.sticky-textarea').oninput=()=>saveNoteText(n.id,el.querySelector('.sticky-textarea').value);
  // Resize observer
  const ro=new ResizeObserver(()=>saveNotePos(n.id,el));
  ro.observe(el);
}
function saveNotePos(id,el) {
  const n=stickyNotes.find(n=>n.id===id); if(!n) return;
  n.x=el.offsetLeft;n.y=el.offsetTop;n.w=el.offsetWidth;n.h=el.offsetHeight;
  localStorage.setItem('sticky_notes_v2',JSON.stringify(stickyNotes));
}
function saveNoteText(id,text) {
  const n=stickyNotes.find(n=>n.id===id); if(!n) return;
  n.text=text; localStorage.setItem('sticky_notes_v2',JSON.stringify(stickyNotes));
}
function deleteNote(id) {
  stickyNotes=stickyNotes.filter(n=>n.id!==id);
  localStorage.setItem('sticky_notes_v2',JSON.stringify(stickyNotes));
  document.getElementById(id)?.remove();
}
function renderAllNotes() { stickyNotes.forEach(renderNote); }

