//  AI FAB OBSERVER
// ══════════════════════════════════════════════════════
function setupAIFabObserver() {
  const fab=document.getElementById('ai-fab');
  const section=document.getElementById('ai-section');
  if(!section) return;
  const obs=new IntersectionObserver(entries=>{
    entries.forEach(e=>{ fab.style.display=e.isIntersecting?'none':'flex'; });
  },{threshold:0.1});
  obs.observe(section);
}

