// Scroll suau fins al final del xat (com fa Claude)
function scrollToBottom(animate=true) {
  const box = document.getElementById('ai-messages');
  if (!box) return;
  if (animate) {
    box.scrollTo({ top: box.scrollHeight, behavior: 'smooth' });
  } else {
    // Instantani — múltiples intents per quan el DOM acaba de pintar
    box.scrollTop = box.scrollHeight;
    requestAnimationFrame(() => { box.scrollTop = box.scrollHeight; });
    setTimeout(() => { box.scrollTop = box.scrollHeight; }, 100);
    setTimeout(() => { box.scrollTop = box.scrollHeight; }, 300);
  }
}

function renderAIMessages() {
  const box = document.getElementById('ai-messages'); if(!box) return;
  const chips = document.getElementById('ai-chips');
  const chat = aiChats[aiCurrentChatId];
  if(!chat||!chat.messages.length){
    box.innerHTML='<div class="ai-msg-empty">Hola! Soc <strong>Julians</strong>, el teu assistent personal de <strong>JOmaxPath</strong>. 🧠<br><br>Et puc ajudar a:<br><br><em>«Afegeix deep work avui de 17 a 19»</em><br><em>«Genera la meva setmana òptima»</em><br><em>«Afegeix examen de mates dijous»</em><br><br>Gestiono tasques, calendari, horari i molt més!</div>';
    if(chips) { chips.style.display='flex'; chips.style.opacity='1'; }
    return;
  }
  // Hide chips once chat has messages
  if(chips) { chips.style.opacity='0'; chips.style.maxHeight='0'; chips.style.padding='0'; chips.style.overflow='hidden'; }
  box.innerHTML = chat.messages.map(m=>`<div class="ai-msg ${m.role}">${m.role==='assistant'?formatAIText(m.text):escapeHtml(m.text)}</div>`).join('');
  // Scroll instantani en carregar (sense animació), però suau si és un missatge nou
  scrollToBottom(false);
}

function escapeHtml(t) { return t.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

function formatAIText(text) {
  return text
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>')
    .replace(/\*(.+?)\*/g,'<em>$1</em>')
    .replace(/^### (.+)$/gm,'<h4 style="color:var(--accent2);margin:8px 0 4px;font-size:13px;">$1</h4>')
    .replace(/^## (.+)$/gm,'<h3 style="color:var(--accent2);margin:10px 0 5px;font-size:14px;">$1</h3>')
    .replace(/^# (.+)$/gm,'<h2 style="color:var(--accent2);margin:10px 0 6px;font-size:15px;">$1</h2>')
    .replace(/^[-•–] (.+)$/gm,'<li style="margin:2px 0;padding-left:4px;">$1</li>')
    .replace(/(<li[^>]*>.*?<\/li>\n?)+/gs,m=>`<ul style="padding-left:16px;margin:6px 0;">${m}</ul>`)
    .replace(/\n\n/g,'</p><p style="margin:6px 0;">')
    .replace(/\n/g,'<br>');
}

