function getEstudiSystemPrompt(submode, docContent) {
  const base = `Ets Julians, l'assistent d'estudi personal de l'Julià Domingo (17 anys, estudiant). Parles SEMPRE en català. Ets com un professor particular expert en tècniques d'aprenentatge científicament provades: Spaced Repetition, Active Recall, Tècnica Feynman, mètode 2357 i interleaving.`;

  if(submode === 'pla') {
    return base + `

MODE PLA D'ESTUDI — La teva tasca:
1. Si l'usuari NO ha indicat la data de l'examen → pregunta-la de forma amigable i breu.
2. Si tens la data → calcula els dies que falten i genera un PLA D'ESTUDI complet basat en:
   - MÈTODE 2357 (Spaced Repetition): Sessió 1 (dia 0) → revisió dia 2 → dia 3 → dia 5 → dia 7 → dia abans examen
   - Divide el contingut en BLOCS TEMÀTICS manejables (15-30 min per bloc)
   - Intercala temes (Interleaving) per evitar fatiga cognitiva
   - Reserva els últims 2 dies per REPASSOS i PRÀCTICA
   
FORMAT DEL PLA (usa aquest format exacte):
📅 **PLA D'ESTUDI — [X] dies fins l'examen**

**DIA 1 — [data] · Primera exposició**
• 📖 [Bloc 1 — tema] (20 min) — Lectura activa + notes pròpies
• 📖 [Bloc 2 — tema] (20 min)
• ✍️ Repàs ràpid sense mirar apunts (10 min)

[continua per cada dia...]

**CONSELLS PER AQUEST PLA:**
[2-3 consells específics per al contingut]

Al final SEMPRE ofereix:
💡 "Vols que et generi un **resum** per a la sessió d'avui? O prefereix passar directament a **preguntes de pràctica**?"`;
  }

  if(submode === 'resum') {
    return base + `

MODE RESUM — La teva tasca és crear un resum que faciliti la comprensió i memorització:

ESTRUCTURA DEL RESUM (OBLIGATÒRIA):
1. **🎯 IDEA CENTRAL** (1-2 frases: de què tracta tot plegat)
2. **🗺️ MAPA CONCEPTUAL** (llista jeràrquica dels conceptes principals → subconcptes)
3. **📌 CONCEPTES CLAU** (per a cada concepte important):
   - **Nom**: explicació simple com si fos a un nen de 12 anys (Tècnica Feynman)
   - **Exemple**: analogia o exemple de la vida real
   - **Per recordar**: truc mnemotècnic si és útil
4. **🔗 CONNEXIONS** (com es relacionen els conceptes entre ells)
5. **⚡ RESUM ULTRA-CURT** (5 frases màxim que capturen el 80% del contingut)

REGLES:
- Usa llenguatge senzill, com si expliquessis a un amic
- Afegeix emojis per ajudar la memòria visual
- Destaca en **negreta** els termes que podrien sortir a l'examen
- Si hi ha dates/números importants, posa'ls en una llista separada

Al final ofereix: "Vols que passem a **pràctica** per consolidar el que hem après?"`;
  }

  if(submode === 'practica') {
    return base + `

MODE PRÀCTICA — La teva tasca és consolidar el coneixement amb Active Recall:

Si l'usuari NO ha especificat quin tipus vol → pregunta:
"Quin tipus de pràctica prefereixes avui?
1️⃣ **Preguntes obertes** — respon amb les teves paraules
2️⃣ **Test tipus examen** — preguntes amb opcions (A/B/C/D)  
3️⃣ **Flashcards** — pregunta i respon
4️⃣ **Tècnica Feynman** — explica'm el concepte com si jo no en sabés res
5️⃣ **Examen complet** — simulo un examen real amb nota final"

Quan l'usuari tria i respon:
- Valora la resposta de forma constructiva
- Si s'equivoca: NO donis la resposta directament, dona una PISTA primer
- Apunta mentalment els errors per reforçar-los
- Adapta la dificultat al nivell de l'usuari
- Cada 3-4 preguntes: mini-resum del que va bé i el que cal reforçar

FORMAT PREGUNTES:
❓ **Pregunta [N]:** [text]
(Pren el temps que necessitis per respondre)

QUAN L'USUARI RESPON → valora i continua. Al final dóna una puntuació i recomana si cal tornar al resum o al pla.`;
  }

  return base;
}

async function sendAIEstudi(userMsg, docContent) {
  const chat = aiChats[aiCurrentChatId];
  const box = document.getElementById('ai-messages');
  const typingEl = document.createElement('div');
  typingEl.className = 'ai-msg thinking';

  const submodeIcons = { pla:'📅', resum:'🗒️', practica:'🧪' };
  typingEl.innerHTML = `<div class="ai-typing"><span></span><span></span><span></span></div><span style="font-size:10px;opacity:0.5;display:block;margin-top:4px;">${submodeIcons[estudiSubmode]||'📚'} Mode Estudi — ${estudiSubmode}...</span>`;
  box.appendChild(typingEl);
  scrollToBottom();
  document.getElementById('ai-chat-send').disabled = true;

  try {
    const systemPrompt = getEstudiSystemPrompt(estudiSubmode, docContent);

    // Historial filtrat i limitat
    const historyMsgs = chat.messages.slice(-10)
      .filter(m => m.text && String(m.text).trim().length > 0)
      .map(m => {
        let cnt = String(m.text);
        if(cnt.length > 1200) cnt = cnt.substring(0, 1200) + '...[retallat]';
        return { role: m.role === 'user' ? 'user' : 'assistant', content: cnt };
      });

    // Construir el missatge de l'usuari
    // Detectar comandes ràpides de canvi de submode
    if(userMsg) {
      const cmd = userMsg.toLowerCase().trim();
      if(cmd.includes('fes el resum') || cmd === 'resum') {
        setEstudiSubmode('resum');
        userContent = 'Fes el resum de la teoria que hem tractat.';
      } else if(cmd.includes('pràctica') || cmd === 'practica' || cmd.includes('practicar')) {
        setEstudiSubmode('practica');
        userContent = 'Volem practicar. Pregunta\'m sobre el contingut que hem tractat.';
      } else if(cmd.includes('fes el pla') || cmd.includes('pla d') || cmd === 'pla') {
        setEstudiSubmode('pla');
        userContent = 'Crea el pla d\'estudi per al contingut que hem tractat.';
      }
    }

    let userContent = userMsg || '';
    if(docContent) {
      const maxDoc = 10000;
      const docTrimmed = docContent.length > maxDoc
        ? docContent.substring(0, maxDoc) + '\n[... document retallat ...]'
        : docContent;
      userContent = (userMsg ? userMsg + '\n\n' : '') +
        '--- TEORIA/CONTINGUT A ESTUDIAR ---\n' + docTrimmed;
    }

    if(!userContent) {
      // No hi ha res — donar benvinguda al submode
      const welcomes = {
        pla: 'Hola! Estic llest per crear el teu pla d\'estudi personalitzat 📅\n\nPer começar, necessito saber:\n1. **Quina matèria o tema** has d\'estudiar?\n2. **Quan tens l\'examen?** (data exacta si en saps)\n\nTambé pots adjuntar el PDF de la teoria o enganxar-la directament aquí 👇',
        resum: 'Perfecte! Mode Resum activat 🗒️\n\nAdjunta el PDF de la teoria o enganxa el text aquí i et faré un resum estructurat amb:\n• Conceptes clau explicats simplement\n• Mapa conceptual\n• Trucs per memoritzar\n• Resum ultra-curt per repassar ràpid',
        practica: 'Mode Pràctica activat! 🧪\n\nPer practicar necessito la teoria. Pots:\n• **Adjuntar el PDF** de la teoria\n• **Enganxar el text** aquí\n• O dir-me **quin tema** vols practicar (si ja hem fet el resum)\n\nQuin tipus de pràctica prefereixes?\n1️⃣ Preguntes obertes\n2️⃣ Test tipus examen (A/B/C/D)\n3️⃣ Flashcards\n4️⃣ Tècnica Feynman\n5️⃣ Examen complet amb nota'
      };
      typingEl.remove();
      document.getElementById('ai-chat-send').disabled = false;
      chat.messages.push({ role: 'assistant', text: welcomes[estudiSubmode] || 'Mode estudi activat!' });
      localStorage.setItem('julians_chats_v2', JSON.stringify(aiChats));
      renderAIMessages();
      return;
    }

    const msgs = [
      { role: 'system', content: systemPrompt },
      ...historyMsgs
    ];
    // Assegurar que l'últim missatge és de l'usuari
    if(msgs[msgs.length-1].role !== 'user') {
      msgs.push({ role: 'user', content: userContent });
    } else {
      msgs[msgs.length-1].content = userContent;
    }

    const resp = await fetch('https://api.groq.com/openai/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + getAPIKey()
      },
      body: JSON.stringify({
        model: 'llama-3.3-70b-versatile',
        max_tokens: 3500,
        temperature: 0.55,
        messages: msgs
      })
    });

    const data = await resp.json();
    typingEl.remove();
    document.getElementById('ai-chat-send').disabled = false;

    if(!resp.ok) {
      const errMsg = data?.error?.message || JSON.stringify(data?.error);
      chat.messages.push({ role: 'assistant', text: '⚠️ Error Groq (' + resp.status + '): ' + errMsg.substring(0, 200) });
    } else {
      const answer = data.choices?.[0]?.message?.content || '⚠️ Sense resposta.';
      chat.messages.push({ role: 'assistant', text: answer });

      // Afegir botons d'acció contextuals segons el submode
      const actionMsg = getEstudiActionButtons(estudiSubmode, answer);
      if(actionMsg) {
        setTimeout(() => {
          chat.messages.push({ role: 'assistant', text: actionMsg });
          localStorage.setItem('julians_chats_v2', JSON.stringify(aiChats));
          renderAIMessages();
        }, 400);
      }
    }

    localStorage.setItem('julians_chats_v2', JSON.stringify(aiChats));
    renderAISidebar();
    renderAIMessages();

  } catch(err) {
    typingEl.remove();
    document.getElementById('ai-chat-send').disabled = false;
    chat.messages.push({ role: 'assistant', text: '⚠️ Error de connexió: ' + err.message });
    localStorage.setItem('julians_chats_v2', JSON.stringify(aiChats));
    renderAIMessages();
  }
}

function getEstudiActionButtons(submode, answer) {
  // Si la resposta ja conté una oferta de transició, no afegim botó extra
  if(answer.includes('Vols que') || answer.includes('prefereixes')) return null;
  if(submode === 'pla') {
    return '🔗 **Accions ràpides:**\n[Vols un **Resum** de la teoria? → escriu "fes el resum"] · [Vols **Pràctica** directa? → escriu "pràctica"]';
  }
  if(submode === 'resum') {
    return '🔗 **Accions ràpides:**\n[Vols el **Pla d\'estudi** complet? → escriu "fes el pla"] · [Vols **Practicar** ara? → escriu "pràctica"]';
  }
  return null;
}

// ── MAIN SEND FUNCTION ────────────────────────────────
async function sendAIBase() {
  const input = document.getElementById('ai-chat-input');
  const text = input.value.trim(); if(!text) return;

  // Check API key
  if(!getAPIKey()) {
    const chatLog = document.getElementById('ai-messages');
    const warn = document.createElement('div');
    warn.className = 'ai-msg assistant';
    warn.innerHTML = '<span style="color:#fcd34d;">⚠️ <strong>Sense API Key configurada.</strong><br>Ves a <strong>⚙️ Configuració → 🔑 IA</strong> per afegir la teva clau de Groq.</span>';
    chatLog?.appendChild(warn);
    scrollToBottom();
    return;
  }

  if(!aiChats[aiCurrentChatId]) createNewChat(false);
  const chat = aiChats[aiCurrentChatId];

  // Add user message to display history
  chat.messages.push({role:'user', text});
  if(chat.messages.length===1) chat.title = text.substring(0,32)+(text.length>32?'…':'');
  input.value='';
  localStorage.setItem('julians_chats_v2', JSON.stringify(aiChats));
  renderAISidebar(); renderAIMessages();

  // Show typing indicator
  const box = document.getElementById('ai-messages');
  const typingEl = document.createElement('div');
  typingEl.className='ai-msg thinking';
  const modeHints = {extens:'<span style="font-size:10px;opacity:0.5;display:block;margin-top:4px;">📝 Redactant resposta extensa...</span>',profund:'<span style="font-size:10px;opacity:0.5;display:block;margin-top:4px;">🔬 Analitzant en profunditat...</span>'};
  typingEl.innerHTML = `<div class="ai-typing"><span></span><span></span><span></span></div>${modeHints[aiMode]||''}`;
  box.appendChild(typingEl); scrollToBottom();
  document.getElementById('ai-chat-send').disabled = true;

  try {
    const mode = AI_MODES[aiMode]||AI_MODES.rapid;

    const systemPrompt = `Ets Julians, l'assistent personal de l'Julià Domingo a JOmaxPath. Parles SEMPRE en català.

REGLA CRÍTICA: Quan l'usuari demani afegir, crear, editar o eliminar qualsevol cosa (tasca, event, examen, entrenament...), HAS D'USAR OBLIGATÒRIAMENT l'eina corresponent. MAI responguis dient que ho has fet sense haver cridat l'eina realment.

EINES I QUAN USAR-LES:
- add_task → afegir tasca, examen, entrega, deures, treball a la llista de Tasques
- add_calendar_event → ÉS EL BOTÓ "+ Afegir al dia". Per events/notes puntuals d'un dia: recordatoris, cites, dentista, notes, examen al calendari, etc. Apareix a la targeta del dia. Types: '📌 Recordatori','📚 Escolar','🏒 Esport','💻 Programació','📝 Examen','📦 Entrega','🎯 Altres'
- add_schedule_block → Per afegir blocs permanents a l'horari setmanal (rutines fixes: gym de 18-19h, classe de piano 17-18h). Apareix com a bloc de color a la graella. NO usar add_timed_event per a rutines setmanals.
- add_timed_event → Per events puntuals amb hora en un dia concret (NO per rutines setmanals).
- add_match → afegir UN O MOLTS partits a la taula de partits de la temporada (usa quan parlin de partits, jornades, rivals)
- clear_matches → esborrar tots els partits de la temporada
- delete_task / delete_calendar_event / delete_timed_event → eliminar/esborrar
- edit_task / edit_schedule_block → editar/canviar
- clear_week_schedule → esborrar tot l'horari setmanal
- set_week_schedule → crear/substituir tot l'horari setmanal d'un cop

REGLES CRÍTIQUES — SEGUEIX-LES SEMPRE:

1. QUAN L'USUARI DIU "afegeix al dia", "afegeix a [dia]", "afegeix nota a", "recorda'm", "posa un recordatori":
   → USA SEMPRE: add_calendar_event (mai add_timed_event)

2. QUAN L'USUARI DIU "afegeix bloc de", "posa de X a Y hores", "crea rutina de":
   → USA: add_timed_event (blocs horaris a la graella setmanal)

3. QUAN DIUS "afegeix un (examen|tasca|deures|entrega) a [data]":
   → USA: add_task I add_calendar_event

4. PARTITS: sempre add_match, mai add_calendar_event

EXEMPLES CONCRETS:
- "afegeix dentista dijous a les 16h" → add_calendar_event (type: '📌 Recordatori', time: '16:00')
- "afegeix gym dilluns de 18 a 19:30h" → add_schedule_block (day:0, time:'18:00-19:30', label:'Gym', type:'esport')
- "recorda'm trucar el metge dimarts" → add_calendar_event
- "afegeix al dilluns: preparar presentació" → add_calendar_event
- "posa bloc de deep work dijous de 9 a 11" → add_schedule_block (day:3, time:'09:00-11:00', label:'Deep Work', type:'prog')

- get_all_data → consultar/veure les dades actuals

COLORS per add_timed_event: tec-purple=deepwork/estudi, tec-blue=classes/reunions, tec-green=esport, tec-orange=menjar, tec-red=examen/urgent, tec-pink=personal, tec-teal=salut

${buildCalendarContext()}
${mode.suffix}`;

    // ── Missatges d'historial — filtrant buits/nulls i documents llargs ──
    const historyMsgs = chat.messages.slice(-12)
      .filter(m => m.text && String(m.text).trim().length > 0)
      .map(m => {
        let cnt = String(m.text);
        if(cnt.length > 1500) cnt = cnt.substring(0, 1500) + '...[retallat]';
        return { role: m.role === 'user' ? 'user' : 'assistant', content: cnt };
      });

    // Conversa casual: prompt curt + sense eines (estalvia ~4000 tokens)
    const isCasual = !/(afegeix|afegir|crea|crear|esborra|elimina|edita|canvia|posa al|afegeix al|fes|executa|processa|anota|apunta|recorda|tasca|event|examen|entrenament|horari|calendari|bloc|partit)/i.test(text);
    const tools = isCasual ? [] : getAITools();
    const activePrompt = isCasual
      ? "Ets Julians, l'assistent personal de l'Julià Domingo a JOmaxPath. Parles SEMPRE en català. Ets proper i directe."
      : systemPrompt;

    // ── PRIMERA CRIDA GROQ ──
    const groqMsgs1 = [
      {role:'system', content: activePrompt},
      ...historyMsgs
    ];

    const reqBody1 = {
      model: isCasual ? 'llama-3.1-8b-instant' : 'llama-3.3-70b-versatile',
      max_tokens: mode.max_tokens,
      temperature: mode.temperature||0.3,
      messages: groqMsgs1
    };
    if(tools.length > 0) { reqBody1.tools = tools; reqBody1.tool_choice = 'auto'; }

    const resp1 = await fetch('https://api.groq.com/openai/v1/chat/completions', {
      method:'POST',
      headers:{
        'Content-Type':'application/json',
        'Authorization': 'Bearer ' + getAPIKey()
      },
      body: JSON.stringify(reqBody1)
    });
    const data1 = await resp1.json();
    console.log('[Julians] Resp 1:', JSON.stringify(data1).substring(0,400));

    if(!resp1.ok) {
      typingEl.remove();
      document.getElementById('ai-chat-send').disabled = false;
      const _ec = data1?.error?.code || '';
      const _em = String(data1?.error?.message || '');
      let err;
      if(_ec === 'rate_limit_exceeded' || _em.includes('rate_limit')) {
        err = "⏳ Límit d'ús assolit. Torna a provar en uns minuts.";
      } else {
        err = '⚠️ Error Groq (' + resp1.status + '): ' + (_em || JSON.stringify(data1?.error)).substring(0, 200);
      }
      chat.messages.push({role:'assistant', text:err});
      localStorage.setItem('julians_chats_v2', JSON.stringify(aiChats));
      renderAIMessages(); return;
    }

    if(!data1.choices || !data1.choices[0]) {
      typingEl.remove();
      document.getElementById('ai-chat-send').disabled = false;
      const raw = JSON.stringify(data1).substring(0,200);
      chat.messages.push({role:'assistant', text:`⚠️ Resposta inesperada: ${raw}`});
      localStorage.setItem('julians_chats_v2', JSON.stringify(aiChats));
      renderAIMessages(); return;
    }

    // ── PROCESSAR TOOL CALLS ──
    const assistantMsg = data1.choices[0].message;
    const toolCalls = assistantMsg.tool_calls || [];
    let toolResults = [];
    let textFromFirst = assistantMsg.content || '';

    console.log('[Julians] Tool calls:', toolCalls.length, toolCalls.map(tc=>tc.function?.name));

    for(const tc of toolCalls) {
      let input = {};
      try { input = JSON.parse(tc.function.arguments); } catch(e) {
        console.warn('[Julians] Error args:', tc.function.arguments);
      }
      console.log('[Julians] Executant:', tc.function.name, input);
      const result = executeAITool(tc.function.name, input);
      console.log('[Julians] Resultat:', result);
      toolResults.push({role:'tool', tool_call_id: tc.id, content: String(result)});
    }

    let finalText = textFromFirst;

    // ── SEGONA CRIDA (si hi havia eines) ──
    if(toolResults.length > 0) {
      const msgs2 = [
        {role:'system', content: systemPrompt},
        ...historyMsgs,
        {role:'assistant', content: assistantMsg.content || '', tool_calls: toolCalls},
        ...toolResults
      ];
      console.log('[Julians] Crida 2 →', msgs2.length, 'msgs');
      const resp2 = await fetch('https://api.groq.com/openai/v1/chat/completions', {
        method:'POST',
        headers:{
          'Content-Type':'application/json',
          'Authorization': 'Bearer ' + getAPIKey()
        },
        body: JSON.stringify({
          model:'llama-3.3-70b-versatile',
          max_tokens: mode.max_tokens,
          temperature: mode.temperature||0.3,
          messages: msgs2
        })
      });
      const data2 = await resp2.json();
      console.log('[Julians] Resp 2:', JSON.stringify(data2).substring(0,300));
      finalText = data2.choices?.[0]?.message?.content || '';
      if(!finalText) finalText = toolResults.map(r=>r.content).join('\n');
    }

    typingEl.remove();
    document.getElementById('ai-chat-send').disabled = false;

    const answer = finalText.trim() || '✅ Fet!';
    chat.messages.push({role:'assistant', text:answer});
    localStorage.setItem('julians_chats_v2', JSON.stringify(aiChats));
    renderAISidebar(); renderAIMessages();

  } catch(err) {
    typingEl.remove();
    document.getElementById('ai-chat-send').disabled = false;
    const errMsg = '⚠️ Error: ' + (err && err.message ? err.message : String(err)).substring(0, 200);
    chat.messages.push({role:'assistant', text: errMsg});
    console.error('[Julians] catch error:', err);
    localStorage.setItem('julians_chats_v2', JSON.stringify(aiChats));
    renderAIMessages();
  }
}


