// Backward compat
const DAILY_QUOTES = DAILY_QUOTES_I18N.ca;


// ── DAILY QUOTE ─────────────────────────────────────
function renderDailyQuote() {
  const today = new Date().toDateString();
  const savedDate = localStorage.getItem('quote_date');
  if(savedDate !== today) {
    quoteIndex = Math.floor(Math.random() * DAILY_QUOTES.length);
    localStorage.setItem('quote_idx', quoteIndex);
    localStorage.setItem('quote_date', today);
  }
  const qList = DAILY_QUOTES_I18N[currentLang] || DAILY_QUOTES_I18N.ca;
  const q = qList[quoteIndex % qList.length];
  document.getElementById('dq-text').textContent = '"' + q.t + '"';
  document.getElementById('dq-author').textContent = '— ' + q.a;
}
function refreshQuote() {
  const el = document.querySelector('.dq-refresh');
  if(el) { el.style.transform='rotate(360deg)'; setTimeout(()=>el.style.transform='',400); }
  quoteIndex = (quoteIndex + 1) % DAILY_QUOTES.length;
  localStorage.setItem('quote_idx', quoteIndex);
  renderDailyQuote();
}

// ── TODAY DASHBOARD ─────────────────────────────────
function renderTodayDashboard() {
  const now = new Date();
  const today = toLocalDateKey(now);
  const todayDow = now.getDay(); const dayIdx = todayDow===0?6:todayDow-1;
  const sched = daySchedule[dayIdx]||{blocks:[]};
  const evCount = (monthEvents[today]||[]).length;
  const pending = examList.filter(e=>!e.done).length;
  const pomoToday = pomoData.today || 0;
  const streakNum = parseInt(document.getElementById('streak-num')?.textContent||'0');

  const grid = document.getElementById('today-grid'); if(!grid) return;
  grid.innerHTML = `
    <div class="today-card">
      <div class="tc-icon">📋</div>
      <div class="tc-val" style="color:var(--yellow)">${pending}</div>
      <div class="tc-lbl">Tasques pendents</div>
    </div>
    <div class="today-card">
      <div class="tc-icon">📅</div>
      <div class="tc-val" style="color:var(--accent2)">${evCount}</div>
      <div class="tc-lbl">Events avui</div>
    </div>
    <div class="today-card">
      <div class="tc-icon">🍅</div>
      <div class="tc-val" style="color:var(--red)">${pomoToday}</div>
      <div class="tc-lbl">Pomodoros avui</div>
    </div>
  `;
  // Now indicator
  const nowMins = now.getHours()*60+now.getMinutes();
  const currentBlock = sched.blocks.find(b=>b.time&&isCurrentBlock(b.time,nowMins));
  const nowEl = document.getElementById('today-now');
  const nowTxt = document.getElementById('today-now-txt');
  if(currentBlock && nowEl && nowTxt) {
    nowTxt.textContent = `Ara: ${currentBlock.label}  ·  ${currentBlock.time}`;
    nowEl.style.display='flex';
  } else if(nowEl) nowEl.style.display='none';
}

// ── POMODORO ─────────────────────────────────────────
function setPomoPreset(focus, brk, sessions) {
  pomoReset();
  pomoFocusMins=focus; pomoBreakMins=brk; pomoSessions=sessions;
  pomoCurrent=focus*60;
  document.querySelectorAll('.pomo-preset-btn').forEach(b=>b.classList.remove('active'));
  const presetEl = document.getElementById(`preset-${focus}`);
  if(presetEl) presetEl.classList.add('active');
  const custEl = document.getElementById('preset-cust');
  if(custEl) custEl.style.display='none';
  // sync custom inputs
  const cf = document.getElementById('pomo-cust-focus');
  const cb = document.getElementById('pomo-cust-break');
  if(cf) cf.textContent = focus;
  if(cb) cb.textContent = brk;
  updatePomoRatioLabel(focus, brk);
  updatePomoDisplay();
}

// Custom pomodoro timer
let pomoCustFocus = 25;
function adjustPomoCust(type, delta) {
  pomoCustFocus = Math.min(180, Math.max(5, pomoCustFocus + delta));
  const brk = Math.max(1, Math.round(pomoCustFocus / 5));
  const cf = document.getElementById('pomo-cust-focus');
  const cb = document.getElementById('pomo-cust-break');
  if(cf) cf.textContent = pomoCustFocus;
  if(cb) cb.textContent = brk;
  updatePomoRatioLabel(pomoCustFocus, brk);
}
function applyPomoCustom() {
  const brk = Math.max(1, Math.round(pomoCustFocus / 5));
  pomoReset();
  pomoFocusMins = pomoCustFocus; pomoBreakMins = brk; pomoSessions = 4;
  pomoCurrent = pomoCustFocus * 60;
  document.querySelectorAll('.pomo-preset-btn').forEach(b=>b.classList.remove('active'));
  const custEl = document.getElementById('preset-cust');
  if(custEl) { custEl.style.display='inline-block'; custEl.classList.add('active'); }
  updatePomoRatioLabel(pomoCustFocus, brk);
  updatePomoDisplay();
}
function updatePomoRatioLabel(focus, brk) {
  const lbl = document.getElementById('pomo-ratio-lbl');
  if(!lbl) return;
  const ratio = (focus/brk).toFixed(1);
  lbl.textContent = `${currentLang==='en'?'Ratio':'Ràtio'} 1:${(brk/focus).toFixed(2).replace(/\.?0+$/,'')} · ${brk} min ${currentLang==='en'?'break per':currentLang==='es'?'de descanso por':'de descans per'} ${focus} ${currentLang==='en'?'work':'de treball'}`;
}
function pomoAction() {
  if(pomoRunning) {
    clearInterval(pomoInterval); pomoRunning=false;
    document.getElementById('pomo-start').textContent=t('pomo_resume');
    document.getElementById('pomo-start').className='pomo-btn start';
  } else {
    if(pomoCurrent===0) pomoCurrent=(pomoPhase==='focus'?pomoFocusMins:pomoBreakMins)*60;
    pomoRunning=true;
    document.getElementById('pomo-start').textContent=t('pomo_pause');
    document.getElementById('pomo-start').className='pomo-btn pause';
    clearInterval(pomoInterval);
    pomoInterval=setInterval(function(){ pomoTick(); },1000);
  }
}
function pomoTick() {
  pomoCurrent--;
  if(pomoCurrent<=0) {
    clearInterval(pomoInterval); pomoRunning=false;
    if(pomoPhase==='focus') {
      // Confetti i notificació
      const btn = document.getElementById('pomo-start');
      const rect = btn?.getBoundingClientRect();
      if(rect) burstConfetti(rect.left+rect.width/2, rect.top);
      pomoSessionsDone++;
      const today = toLocalDateKey(new Date());
      if(pomoData.lastDate!==today){pomoData.today=0;pomoData.week=0;pomoData.lastDate=today;}
      pomoData.today++; pomoData.total++;
      localStorage.setItem('pomo_v1',JSON.stringify(pomoData));
      const notifBody = {ca:`Sessió de ${pomoFocusMins}min completada! Descans automàtic iniciat. 🍵`,es:`¡Sesión de ${pomoFocusMins}min completada! Descanso automático iniciado. 🍵`,en:`${pomoFocusMins}min session done! Break starting automatically. 🍵`}[currentLang||'ca'];
      if(Notification.permission==='granted') new Notification('JOmaxPath 🍅',{body:notifBody});
      // Mostrar toast de transició
      const phaseMsg = {ca:'🍵 Descans! Temps de desconnectar.',es:'🍵 ¡Descanso! Tiempo de desconectar.',en:'🍵 Break time! Time to rest.'}[currentLang||'ca'];
      showSyncToast(phaseMsg);
      pomoPhase = (pomoSessionsDone%pomoSessions===0)?'long-break':'break';
      pomoCurrent = (pomoPhase==='long-break'?pomoFocusMins*2:pomoBreakMins)*60;
    } else {
      // Descans acabat → tornar a focus
      pomoPhase='focus'; pomoCurrent=pomoFocusMins*60;
      const focusMsg = {ca:'⚡ Descans acabat! Focus iniciat.',es:'⚡ ¡Descanso acabado! Focus iniciado.',en:'⚡ Break over! Focus started.'}[currentLang||'ca'];
      showSyncToast(focusMsg);
      if(Notification.permission==='granted') {
        const nb = {ca:'Tornada al focus! Concentra-te.',es:'¡Vuelve al foco! Concéntrate.',en:'Back to focus! Concentrate.'}[currentLang||'ca'];
        new Notification('JOmaxPath ⚡',{body:nb});
      }
    }
    updatePomoDisplay(); renderTodayDashboard(); checkPomoRewards();
    // ── AUTO-START: arrancar automàticament la fase següent ──
    const startBtn = document.getElementById('pomo-start');
    if(startBtn) { startBtn.textContent=t('pomo_pause'); startBtn.className='pomo-btn pause'; }
    pomoRunning=true;
    clearInterval(pomoInterval);
    pomoInterval=setInterval(function(){ pomoTick(); },1000);
    return;
  }
  updatePomoDisplay();
}
function pomoReset() {
  clearInterval(pomoInterval); pomoRunning=false;
  pomoPhase='focus'; pomoSessionsDone=0; pomoCurrent=pomoFocusMins*60;
  document.getElementById('pomo-start').textContent=t('pomo_start');
  document.getElementById('pomo-start').className='pomo-btn start';
  updatePomoDisplay();
}
// ── POMODORO GAMIFICATION ────────────────────────────
const POMO_LEVELS = [
  {min:0,   max:50,  name:'APRENENT',   emoji:'🌱', color:'#6ee7b7'},
  {min:50,  max:150, name:'ESTUDIANT',  emoji:'📚', color:'#93c5fd'},
  {min:150, max:350, name:'CONCENTRAT', emoji:'🎯', color:'#c4b5fd'},
  {min:350, max:700, name:'ENFOCADOR',  emoji:'🔥', color:'#fcd34d'},
  {min:700, max:1400,name:'FLOW STATE', emoji:'⚡', color:'#fb923c'},
  {min:1400,max:3000,name:'DEEP WORKER',emoji:'💎', color:'#f472b6'},
  {min:3000,max:Infinity, name:'MESTRE DEL FOCUS', emoji:'🏆', color:'#fbbf24'}
];
const POMO_REWARDS = [
  {id:'first',   need:10,   emoji:'🍅', label:'Primer Pomo',      desc:'El primer sempre costa més! +10 XP'},
  {id:'five',    need:50,   emoji:'🔥', label:'En Ratxa',         desc:'50 XP acumulats (5 pomodoros de 5min)'},
  {id:'ten',     need:150,  emoji:'⚡', label:'Enfocador',        desc:'150 XP — Vas per bon camí!'},
  {id:'goal',    need:'goal',emoji:'🎯', label:'Objectiu Avui',   desc:'Meta diària assolida!'},
  {id:'twenty',  need:350,  emoji:'💎', label:'Focus Profund',    desc:'350 XP — Treball profund activat'},
  {id:'fifty',   need:700,  emoji:'🏆', label:'Mestre',           desc:'700 XP — Nivell Flow State'},
  {id:'hundred', need:1400, emoji:'👑', label:'Llegenda',         desc:'1400 XP — Deep Worker llegenda'},
];
let pomoGameData = JSON.parse(localStorage.getItem('pomo_game_v1') || '{"xp":0,"dailyGoal":4,"earnedRewards":[]}');
let pomoDailyGoal = pomoGameData.dailyGoal || 4;

function getPomoLevel(xp) {
  return POMO_LEVELS.find(l => xp >= l.min && xp < l.max) || POMO_LEVELS[POMO_LEVELS.length-1];
}
function changeDailyGoal(delta) {
  pomoDailyGoal = Math.max(1, Math.min(16, pomoDailyGoal + delta));
  pomoGameData.dailyGoal = pomoDailyGoal;
  localStorage.setItem('pomo_game_v1', JSON.stringify(pomoGameData));
  renderPomoGame();
}
function renderPomoGame() {
  const xp = pomoGameData.xp || 0;
  const todayCount = pomoData.today || 0;
  const level = getPomoLevel(xp);
  const nextLevel = POMO_LEVELS.find(l => l.min > xp);
  
  // Level badge
  const badge = document.getElementById('pomo-level-badge');
  if(badge) badge.style.background = `linear-gradient(135deg,${level.color},var(--accent))`;
  const ln = document.getElementById('pomo-level-num');
  if(ln) ln.textContent = level.emoji;
  const lname = document.getElementById('pomo-level-name');
  if(lname) { lname.textContent = level.name; lname.style.color = level.color; }

  // XP bar
  const xpInLevel = xp - level.min;
  const xpNeeded = nextLevel ? (nextLevel.min - level.min) : 1;
  const pct = Math.min(100, (xpInLevel / xpNeeded) * 100);
  const xpTxt = document.getElementById('pomo-xp-txt');
  if(xpTxt) xpTxt.textContent = nextLevel ? `${xp} XP (${xpInLevel}/${xpNeeded})` : `${xp} XP — MAX`;
  const xpBar = document.getElementById('pomo-xp-bar');
  if(xpBar) { xpBar.style.width = pct + '%'; xpBar.style.background = `linear-gradient(90deg,${level.color},var(--accent))`; }
  const xpSub = document.getElementById('pomo-xp-sub');
  if(xpSub) xpSub.textContent = nextLevel ? `${xpNeeded - xpInLevel} XP per a "${nextLevel.name}" ${nextLevel.emoji} · Cada 5min = 10 XP` : '🏆 Nivell màxim assolit!';

  // Daily goal dots
  const goalEl = document.getElementById('pomo-goal-num');
  if(goalEl) goalEl.textContent = pomoDailyGoal;
  const dotsEl = document.getElementById('pomo-goal-dots');
  if(dotsEl) {
    dotsEl.innerHTML = '';
    for(let i = 0; i < pomoDailyGoal; i++) {
      const done = i < todayCount;
      const d = document.createElement('div');
      d.style.cssText = `width:28px;height:28px;border-radius:8px;border:2px solid ${done?'rgba(239,68,68,0.5)':'rgba(255,255,255,0.1)'};background:${done?'rgba(239,68,68,0.2)':'rgba(255,255,255,0.03)'};display:flex;align-items:center;justify-content:center;font-size:14px;transition:all 0.3s;`;
      d.textContent = done ? '🍅' : '';
      dotsEl.appendChild(d);
    }
  }
  const goalStatus = document.getElementById('pomo-goal-status');
  if(goalStatus) {
    if(todayCount >= pomoDailyGoal) goalStatus.innerHTML = `<span style="color:#6ee7b7;font-weight:700;">✅ ${{ca:'Objectiu assolit!',es:'¡Objetivo logrado!',en:'Goal reached!'}[currentLang]} +${pomoDailyGoal*10} XP bonus</span>`;
    else goalStatus.textContent = todayCount === 0 
      ? {ca:'Comença el primer pomodoro!',es:'¡Empieza el primer pomodoro!',en:'Start your first pomodoro!'}[currentLang]
      : `${todayCount}/${pomoDailyGoal} ${{ca:'completats',es:'completados',en:'done'}[currentLang]} · ${{ca:'Falten',es:'Faltan',en:'Left'}[currentLang]} ${pomoDailyGoal-todayCount} 🍅`;
  }

  // Rewards
  const rewardsEl = document.getElementById('pomo-rewards-row');
  if(rewardsEl) {
    rewardsEl.innerHTML = POMO_REWARDS.map(r => {
      const earned = r.id === 'goal'
        ? todayCount >= pomoDailyGoal
        : (pomoGameData.earnedRewards || []).includes(r.id);
      return `<div title="${r.desc}" style="display:flex;flex-direction:column;align-items:center;gap:3px;padding:8px 10px;border-radius:12px;border:1px solid ${earned?'rgba(255,255,255,0.2)':'rgba(255,255,255,0.06)'};background:${earned?'rgba(255,255,255,0.08)':'rgba(255,255,255,0.02)'};opacity:${earned?'1':'0.35'};transition:all 0.3s;min-width:52px;cursor:default;">
        <span style="font-size:22px;">${r.emoji}</span>
        <span style="font-family:'Space Mono',monospace;font-size:8px;color:${earned?'var(--text)':'var(--muted)'};text-align:center;letter-spacing:0.5px;">${r.label}</span>
      </div>`;
    }).join('');
  }
}
function checkPomoRewards() {
  const xpGain = pomoFocusMins * 2;
  pomoGameData.xp = (pomoGameData.xp || 0) + xpGain;
  const xp = pomoGameData.xp;
  const todayCount = pomoData.today || 0;
  const earned = pomoGameData.earnedRewards || [];
  let newReward = null;
  POMO_REWARDS.forEach(r => {
    if(r.id === 'goal') return;
    if(typeof r.need === 'number' && xp >= r.need && !earned.includes(r.id)) {
      earned.push(r.id);
      newReward = r;
    }
  });
  if(todayCount >= pomoDailyGoal && !earned.includes('goal_today_'+new Date().toDateString())) {
    earned.push('goal_today_'+new Date().toDateString());
    pomoGameData.xp += pomoDailyGoal * 10; // bonus XP
    newReward = POMO_REWARDS.find(r=>r.id==='goal');
  }
  pomoGameData.earnedRewards = earned;
  localStorage.setItem('pomo_game_v1', JSON.stringify(pomoGameData));
  if(newReward) showRewardToast(newReward);
  renderPomoGame();
}
// ── SPOTIFY EMBED ─────────────────────────────────────
function loadSpotify() {
  const raw = document.getElementById('spotify-url-input').value.trim();
  if(!raw) return;
  // Extract Spotify URI from URL: open.spotify.com/TYPE/ID
  const match = raw.match(/open\.spotify\.com\/(playlist|album|track|artist)\/([a-zA-Z0-9]+)/);
  if(!match) { alert('URL de Spotify no vàlida.\nEx: https://open.spotify.com/playlist/abc123'); return; }
  const type = match[1], id = match[2];
  const embedUrl = `https://open.spotify.com/embed/${type}/${id}?utm_source=generator&theme=0`;
  const iframe = document.getElementById('spotify-iframe');
  iframe.src = embedUrl;
  document.getElementById('spotify-frame-wrap').style.display = 'block';
  document.getElementById('spotify-placeholder').style.display = 'none';
  localStorage.setItem('spotify_url', raw);
}
// Restore saved Spotify URL on load
document.addEventListener('DOMContentLoaded', () => {
  const saved = localStorage.getItem('spotify_url');
  if(saved) {
    const inp = document.getElementById('spotify-url-input');
    if(inp) { inp.value = saved; loadSpotify(); }
  }
});

function showRewardToast(r) {
  const toast = document.createElement('div');
  toast.style.cssText = `position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:var(--card);border:1px solid rgba(255,215,0,0.4);border-radius:16px;padding:14px 22px;z-index:9999;display:flex;align-items:center;gap:12px;box-shadow:0 8px 32px rgba(0,0,0,0.5);animation:slideUp 0.4s ease,fadeOut 0.4s 2.6s forwards;font-family:'Sora',sans-serif;`;
  toast.innerHTML = `<span style="font-size:28px;">${r.emoji}</span><div><div style="font-weight:700;color:#fbbf24;font-size:13px;">Recompensa desblocada!</div><div style="font-size:12px;color:var(--muted);">${r.label} — ${r.desc}</div></div>`;
  document.body.appendChild(toast);
  setTimeout(() => toast.remove(), 3200);
}

function updatePomoDisplay() {
  const total = (pomoPhase==='focus'?pomoFocusMins:pomoPhase==='break'?pomoBreakMins:pomoFocusMins*2)*60;
  const pct = pomoCurrent/total;
  const offset = POMO_CIRCLE*(1-pct);
  const arc = document.getElementById('pomo-arc');
  if(arc) { arc.style.strokeDashoffset=offset; arc.className='pomo-arc'+(pomoPhase==='break'?' break-mode':pomoPhase==='long-break'?' long-break':''); }
  const m=Math.floor(pomoCurrent/60), s=pomoCurrent%60;
  const dEl=document.getElementById('pomo-digits');
  if(dEl) dEl.textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
  const lEl=document.getElementById('pomo-lbl');
  if(lEl) lEl.textContent=pomoPhase==='focus'?t('pomo_focus'):pomoPhase==='break'?t('pomo_break'):t('pomo_long');
  // Sessions dots
  const sEl=document.getElementById('pomo-sessions');
  if(sEl){ sEl.innerHTML=''; for(let i=0;i<pomoSessions;i++){const d=document.createElement('div');d.className='pomo-dot'+(i<pomoSessionsDone%pomoSessions||i<pomoSessionsDone&&pomoSessionsDone%pomoSessions===0?' done':'');sEl.appendChild(d);} }
  // Stats
  const td=document.getElementById('pomo-today');if(td)td.textContent=pomoData.today||0;
  const tw=document.getElementById('pomo-week');if(tw)tw.textContent=pomoData.week||0;
  const tt=document.getElementById('pomo-total');if(tt)tt.textContent=pomoData.total||0;
}

// ── MULTI-HABIT TRACKER ──────────────────────────────
function toggleHabitForm() {
  const f=document.getElementById('habit-add-form');
  f.classList.toggle('open');
  if(f.classList.contains('open')) setTimeout(()=>document.getElementById('habit-name-inp').focus(),50);
}
function addHabit() {
  const name=document.getElementById('habit-name-inp').value.trim();
  const icon=document.getElementById('habit-icon-inp').value.trim()||'⭐';
  if(!name) return;
  habitsData.push({id:'h'+Date.now(),name,icon,days:{}});
  localStorage.setItem('habits_v1',JSON.stringify(habitsData));
  document.getElementById('habit-name-inp').value='';
  document.getElementById('habit-add-form').classList.remove('open');
  renderHabits();
}
function deleteHabit(id) {
  if(!confirm('Eliminar hàbit?')) return;
  habitsData=habitsData.filter(h=>h.id!==id);
  localStorage.setItem('habits_v1',JSON.stringify(habitsData));
  renderHabits();
}
function toggleHabitDay(habitId, dateKey) {
  const h=habitsData.find(h=>h.id===habitId); if(!h) return;
  h.days[dateKey]=!h.days[dateKey];
  if(!h.days[dateKey]) delete h.days[dateKey];
  localStorage.setItem('habits_v1',JSON.stringify(habitsData));
  renderHabits();
}
function renderHabits() {
  const list=document.getElementById('habits-list'); if(!list) return;
  if(!habitsData.length){
    const emptyMsg={ca:'Cap hàbit. Afegeix el primer! 🌱',es:'No hay hábitos. ¡Añade el primero! 🌱',en:'No habits yet. Add your first! 🌱'}[currentLang];
    list.innerHTML=`<div style="color:var(--muted);font-size:13px;text-align:center;padding:20px;">${emptyMsg}</div>`;
    return;
  }
  const today=toLocalDateKey(new Date());
  list.innerHTML=habitsData.map(h=>{
    // Last 14 days
    const dots=[];
    for(let i=13;i>=0;i--){
      const d=new Date();d.setDate(d.getDate()-i);d.setHours(12,0,0,0);
      const k=toLocalDateKey(d);
      const isToday=k===today;
      const done=!!h.days[k];
      dots.push(`<div class="habit-dot${done?' done':''}${isToday?' today-h':''}" onclick="toggleHabitDay('${h.id}','${k}')" title="${k}">${isToday?'●':''}${!isToday?d.getDate():''}</div>`);
    }
    // Streak calc
    let streak=0;const dd=new Date();dd.setHours(12,0,0,0);
    while(h.days[toLocalDateKey(dd)]){streak++;dd.setDate(dd.getDate()-1);}
    // Week pct
    let weekDone=0;
    for(let i=0;i<7;i++){const dd2=new Date();dd2.setDate(dd2.getDate()-i);dd2.setHours(12,0,0,0);if(h.days[toLocalDateKey(dd2)])weekDone++;}
    const pct=Math.round(weekDone/7*100);
    return `<div class="habit-row">
      <span class="habit-icon-btn">${h.icon}</span>
      <div class="habit-info">
        <div class="habit-name">${h.name}</div>
        <div class="habit-streak-txt">🔥 ${{ca:'Ratxa',es:'Racha',en:'Streak'}[currentLang]}: ${streak} ${{ca:'dies',es:'días',en:'days'}[currentLang]} · 7 ${{ca:'dies',es:'días',en:'days'}[currentLang]}: ${pct}%</div>
      </div>
      <div class="habit-dots">${dots.join('')}</div>
      <span class="habit-week-pct" style="color:${pct>=80?'var(--green)':pct>=50?'var(--yellow)':'var(--muted)'};">${pct}%</span>
      <span class="habit-del" onclick="deleteHabit('${h.id}')">×</span>
    </div>`;
  }).join('');
}

// ── PRIORITY IN TASKS ────────────────────────────────
function addExam() {
  const name=document.getElementById('exam-name').value.trim();
  const date=document.getElementById('exam-date').value;
  const type=document.getElementById('exam-type').value;
  const prio=document.getElementById('exam-prio')?.value||'3';
  if(!name) return;
  const exam={id:Date.now()+'',name,date,type,prio:parseInt(prio),done:false};
  examList.push(exam);
  localStorage.setItem('exams_v3',JSON.stringify(examList));
  document.getElementById('exam-name').value='';
  document.getElementById('exam-form').classList.remove('open');
  renderExams(); renderNextUp(); renderCalendar();
  if(date) {
    const icon={deures:'📚',treball:'📄',tasca:'🗂️',personal:'🙋'}[type]||'📝';
    const ev={id:'exam_'+exam.id,text:icon+' '+name,time:'',type:type};
    if(!monthEvents[date]) monthEvents[date]=[];
    monthEvents[date].push(ev);
    localStorage.setItem('month_events_v2',JSON.stringify(monthEvents));
    refreshAllDayCards();
  }
}

function renderExams() {
  const list=document.getElementById('exam-list');
  const today=new Date(); today.setHours(0,0,0,0);
  // Sort by priority then date
  const sorted=[...examList].sort((a,b)=>{
    if(a.done!==b.done) return a.done?1:-1;
    const pa=a.prio||3, pb=b.prio||3;
    if(pa!==pb) return pa-pb;
    return (a.date||'9999').localeCompare(b.date||'9999');
  });
  if(!sorted.length){
    const emptyMsg={ca:'Cap tasca pendent. Afegeix-ne una! 🎯',es:'No hay tareas pendientes. ¡Añade una! 🎯',en:'No pending tasks. Add one! 🎯'}[currentLang];
    list.innerHTML=`<div class="exam-empty">${emptyMsg}</div>`;return;
  }
  const prioLabels={1:'P1',2:'P2',3:'P3',4:'P4'};
  const prioColors={1:'prio-1',2:'prio-2',3:'prio-3',4:'prio-4'};
  const typeLabels = {
    ca:{deures:'📚 Deures',treball:'📄 Treball',tasca:'🗂️ Tasca',personal:'🙋 Personal'},
    es:{deures:'📚 Deberes',treball:'📄 Trabajo',tasca:'🗂️ Tarea',personal:'🙋 Personal'},
    en:{deures:'📚 Homework',treball:'📄 Project',tasca:'🗂️ Task',personal:'🙋 Personal'}
  }[currentLang]||{deures:'📚',treball:'📄',tasca:'🗂️',personal:'🙋'};
  const badgeL = {
    ca:{past:'Passat',today:'AVUI',tomorrow:'DEMÀ'},
    es:{past:'Pasado',today:'HOY',tomorrow:'MAÑANA'},
    en:{past:'Past',today:'TODAY',tomorrow:'TOMORROW'}
  }[currentLang]||{past:'Past',today:'TODAY',tomorrow:'TOMORROW'};
  const saveBtn = {ca:'Guardar',es:'Guardar',en:'Save'}[currentLang];
  const typeOptsHTML = {
    ca:`<option value="deures">📚 Deures</option><option value="treball">📄 Treball</option><option value="tasca">🗂️ Tasca</option><option value="personal">🙋 Personal</option>`,
    es:`<option value="deures">📚 Deberes</option><option value="treball">📄 Trabajo</option><option value="tasca">🗂️ Tarea</option><option value="personal">🙋 Personal</option>`,
    en:`<option value="deures">📚 Homework</option><option value="treball">📄 Project</option><option value="tasca">🗂️ Task</option><option value="personal">🙋 Personal</option>`
  }[currentLang];
  list.innerHTML=sorted.map(ex=>{
    const typeLabel=typeLabels[ex.type]||'📌';
    let badge='', urgClass='';
    if(ex.date){
      const d=new Date(ex.date+'T00:00:00');const diff=Math.ceil((d-today)/(86400000));
      if(diff<0){badge=badgeL.past;urgClass='urgent';}
      else if(diff===0){badge=badgeL.today;urgClass='urgent';}
      else if(diff===1){badge=badgeL.tomorrow;urgClass='soon';}
      else if(diff<=5){badge=`${currentLang==='en'?'In':'En'} ${diff}d`;urgClass='soon';}
      else{badge=`${currentLang==='en'?'In':'En'} ${diff}d`;urgClass='ok';}
    }
    const pc=prioColors[ex.prio||3]||'prio-3';
    const pl=prioLabels[ex.prio||3]||'P3';
    return `<div class="exam-item ${urgClass} ${ex.done?'done-item':''}" id="exam-${ex.id}">
      <div class="exam-check ${ex.done?'checked':''}" onclick="toggleExamDone('${ex.id}')"></div>
      <div class="exam-info">
        <div class="exam-name"><span class="prio-badge ${pc}">${pl}</span>${ex.name}</div>
        <div class="exam-meta">${typeLabel}${ex.date?' · '+ex.date:''}</div>
        <div class="exam-edit-form" id="ef-${ex.id}">
          <input type="text" id="ei-name-${ex.id}" value="${ex.name.replace(/"/g,'&quot;')}" />
          <input type="date" id="ei-date-${ex.id}" value="${ex.date||''}" />
          <select id="ei-type-${ex.id}">${typeOptsHTML.replace(`value="${ex.type}"`,`value="${ex.type}" selected`)}</select>
          <select id="ei-prio-${ex.id}"><option value="1" ${ex.prio===1?'selected':''}>🔴 P1</option><option value="2" ${ex.prio===2?'selected':''}>🟡 P2</option><option value="3" ${(ex.prio||3)===3?'selected':''}>🔵 P3</option><option value="4" ${ex.prio===4?'selected':''}>⚪ P4</option></select>
          <button class="exam-edit-save" onclick="saveExamEdit('${ex.id}')">${saveBtn}</button>
        </div>
      </div>
      ${badge?`<span class="exam-badge ${urgClass}">${badge}</span>`:''}
      <span class="exam-edit" onclick="document.getElementById('ef-${ex.id}').classList.toggle('open')">✏️</span>
      <span class="exam-delete" onclick="deleteExam('${ex.id}')">×</span>
    </div>`;
  }).join('');
}

function saveExamEdit(id) {
  const ex=examList.find(e=>e.id===id);if(!ex) return;
  const oldDate=ex.date;
  ex.name=document.getElementById('ei-name-'+id).value.trim()||ex.name;
  ex.date=document.getElementById('ei-date-'+id).value;
  ex.type=document.getElementById('ei-type-'+id).value;
  ex.prio=parseInt(document.getElementById('ei-prio-'+id).value)||3;
  localStorage.setItem('exams_v3',JSON.stringify(examList));
  const evId='exam_'+id;
  if(oldDate&&monthEvents[oldDate]){monthEvents[oldDate]=monthEvents[oldDate].filter(ev=>ev.id!==evId);if(!monthEvents[oldDate].length)delete monthEvents[oldDate];}
  if(ex.date){
    if(!monthEvents[ex.date])monthEvents[ex.date]=[];
    if(!monthEvents[ex.date].find(ev=>ev.id===evId)){
      const icon={deures:'📚',treball:'📄',tasca:'🗂️',personal:'🙋'}[ex.type]||'📝';
      monthEvents[ex.date].push({id:evId,text:icon+' '+ex.name,time:'',type:ex.type||'tasca'});
    }
  }
  localStorage.setItem('month_events_v2',JSON.stringify(monthEvents));
  renderExams();renderNextUp();renderCalendar();refreshAllDayCards();
}

// ── QUICK CAPTURE ────────────────────────────────────
function openQuickCapture() {
  document.getElementById('quick-capture-overlay').classList.add('open');
  setTimeout(()=>document.getElementById('qc-input').focus(),80);
}
function closeQuickCapture() {
  document.getElementById('quick-capture-overlay').classList.remove('open');
  document.getElementById('qc-input').value='';
}
function setQCType(type) {
  qcType=type;
  document.querySelectorAll('.qc-type-btn').forEach(b=>b.classList.remove('active'));
  document.getElementById('qct-'+type).classList.add('active');
  const row=document.getElementById('qc-extra-row');
  if(type==='nota') row.style.display='none'; else row.style.display='flex';
}
function saveQuickCapture() {
  const text=document.getElementById('qc-input').value.trim();if(!text) return;
  if(qcType==='tasca') {
    const date=document.getElementById('qc-date').value;
    const type=document.getElementById('qc-subtype').value;
    const ex={id:'t'+Date.now(),name:text,date,type,prio:3,done:false};
    examList.push(ex);
    localStorage.setItem('exams_v3',JSON.stringify(examList));
    if(date){
      const icon={deures:'📚',treball:'📄',tasca:'🗂️',personal:'🙋'}[type]||'📝';
      if(!monthEvents[date])monthEvents[date]=[];
      monthEvents[date].push({id:'exam_'+ex.id,text:icon+' '+text,time:'',type:type||'tasca'});
      localStorage.setItem('month_events_v2',JSON.stringify(monthEvents));
    }
    renderExams();renderNextUp();renderCalendar();refreshAllDayCards();
  } else if(qcType==='event') {
    const date=document.getElementById('qc-date').value||toLocalDateKey(new Date());
    const ev={id:'qc'+Date.now(),text:text,time:'',type:'other'};
    if(!monthEvents[date])monthEvents[date]=[];
    monthEvents[date].push(ev);
    localStorage.setItem('month_events_v2',JSON.stringify(monthEvents));
    renderCalendar();refreshAllDayCards();navigateToDate(date);
  } else {
    // Nota → create sticky
    createNote('yellow');
    // Set text in last note
    setTimeout(()=>{
      const notes=document.querySelectorAll('.sticky-textarea');
      if(notes.length){const last=notes[notes.length-1];last.value=text;saveNoteText(stickyNotes[stickyNotes.length-1]?.id,text);}
    },200);
  }
  closeQuickCapture();
}

