// ══════════════════════════════════════════════════════
function openSearch() {
  document.getElementById('global-search-bar').classList.add('open');
  setTimeout(()=>document.getElementById('search-input').focus(), 80);
}
function closeSearch() {
  document.getElementById('global-search-bar').classList.remove('open');
  document.getElementById('search-input').value='';
  document.getElementById('search-results').innerHTML='';
}
function runSearch(q) {
  const res = document.getElementById('search-results');
  if(!q.trim()) { res.innerHTML=''; return; }
  const ql = q.toLowerCase();
  const results = [];

  // Search tasks
  examList.forEach(ex => {
    if(ex.name.toLowerCase().includes(ql)) {
      results.push({
        icon: {deures:'📚',treball:'📄',tasca:'🗂️',personal:'🙋'}[ex.type]||'📋',
        text: ex.name, meta: ex.date||'Sense data', cat:'TASCA',
        action: ()=>{ closeSearch(); navTo('tasques'); }
      });
    }
  });

  // Search calendar events
  Object.entries(monthEvents).forEach(([date, evs]) => {
    evs.forEach(ev => {
      if((ev.text||'').toLowerCase().includes(ql)) {
        results.push({
          icon: '📅', text: ev.text, meta: date+(ev.time?' · '+ev.time:''), cat:'EVENT',
          action: ()=>{ closeSearch(); calYear=parseInt(date.split('-')[0]); calMonth=parseInt(date.split('-')[1])-1; renderCalendar(); navTo('calendari'); }
        });
      }
    });
  });

  // Search schedule blocks
  Object.entries(daySchedule).forEach(([di, day]) => {
    (day.blocks||[]).forEach(b => {
      if(b.label.toLowerCase().includes(ql)) {
        const dayNames=['Dilluns','Dimarts','Dimecres','Dijous','Divendres','Dissabte','Diumenge'];
        results.push({
          icon:'📅', text:b.label, meta:`${dayNames[di]} · ${b.time||''}`, cat:'HORARI',
          action:()=>{ closeSearch(); navTo('horari'); }
        });
      }
    });
  });

  // Search habits
  habitsData.forEach(h => {
    if(h.name.toLowerCase().includes(ql)) {
      results.push({ icon:h.icon, text:h.name, meta:'Hàbit diari', cat:'HÀBIT', action:()=>{ closeSearch(); navTo('home'); } });
    }
  });

  if(!results.length) {
    res.innerHTML=`<div class="search-empty">${{ca:'Cap resultat per',es:'Sin resultados para',en:'No results for'}[currentLang]} "${q}"</div>`; return;
  }
  res.innerHTML = results.slice(0,10).map((r,i)=>`
    <div class="search-result" onclick="searchResults[${i}].action()">
      <span class="search-result-icon">${r.icon}</span>
      <div style="flex:1;min-width:0">
        <div class="search-result-text">${r.text}</div>
        <div class="search-result-meta">${r.meta}</div>
      </div>
      <span class="search-result-cat">${r.cat}</span>
    </div>`).join('');
  window.searchResults = results;
}

