//  ENHANCED KEYBOARD HANDLER (replaces/extends old one)
// ══════════════════════════════════════════════════════
document.addEventListener('keydown', e => {
  const tag = document.activeElement.tagName;
  const isTyping = tag==='INPUT'||tag==='TEXTAREA'||tag==='SELECT'||document.activeElement.isContentEditable;
  
  if(e.key==='Escape') {
    closeSearch(); closeShortcuts(); closeQuickCapture();
    closeMonthModal(); closeDayModal(); closeConfig();
    return;
  }
  if(isTyping) return;
  
  switch(e.key) {
    case '/': e.preventDefault(); openSearch(); break;
    case 'q': case 'Q': openQuickCapture(); break;
    case 'p': case 'P': pomoAction(); break;
    case '?': openShortcuts(); break;
    case '1': navTo('home'); break;
    case '2': navTo('tasques'); break;
    case '3': navTo('julians'); break;
    case '4': navTo('calendari'); break;
  }
});

// ══════════════════════════════════════════════════════
//  CONFETTI BURST (for pomodoro completion)
// ══════════════════════════════════════════════════════
function burstConfetti(x, y) {
  const colors = ['#7c3aed','#3b82f6','#10b981','#f59e0b','#ef4444','#ec4899'];
  for(let i=0;i<18;i++){
    const el=document.createElement('div');
    el.className='confetti-particle';
    el.style.cssText=`left:${x}px;top:${y}px;background:${colors[i%colors.length]};transform:translate(-50%,-50%);`;
    const angle=Math.random()*360, dist=60+Math.random()*80, dur=0.8+Math.random()*0.6;
    el.animate([
      {transform:`translate(-50%,-50%) rotate(0deg)`,opacity:1},
      {transform:`translate(calc(-50% + ${Math.cos(angle)*dist}px), calc(-50% + ${Math.sin(angle)*dist}px)) rotate(${Math.random()*720}deg)`,opacity:0}
    ],{duration:dur*1000,easing:'ease-out',fill:'forwards'}).onfinish=()=>el.remove();
    document.body.appendChild(el);
  }
}

// ══════════════════════════════════════════════════════
//  ENHANCED TASK COMPLETION (with animation)
// ══════════════════════════════════════════════════════
function toggleExamDone(id) {
  const ex = examList.find(e=>e.id===id); if(!ex) return;
  const wasUndone = !ex.done;
  ex.done = !ex.done;
  localStorage.setItem('exams_v3', JSON.stringify(examList));
  // Animate
  const checkEl = document.querySelector(`#exam-${id} .exam-check`);
  const itemEl = document.getElementById('exam-'+id);
  if(checkEl) {
    checkEl.classList.add('just-checked');
    setTimeout(()=>checkEl.classList.remove('just-checked'), 400);
  }
  if(wasUndone && itemEl) {
    // Tiny confetti burst from the checkbox position
    const rect = checkEl?.getBoundingClientRect();
    if(rect) setTimeout(()=>burstConfetti(rect.left+rect.width/2, rect.top+rect.height/2), 100);
    itemEl.classList.add('animating-done');
    setTimeout(()=>{ itemEl.classList.remove('animating-done'); renderExams(); renderNextUp(); }, 550);
  } else {
    renderExams(); renderNextUp();
  }
}

