// ── Live clock, fullscreen mode & seconds toggle ──
let clockShowSeconds = localStorage.getItem('clock_show_seconds') !== 'false';
let clockFullscreenOpen = false;

function updateClock() {
  var now = new Date();
  var h = String(now.getHours()).padStart(2,'0');
  var m = String(now.getMinutes()).padStart(2,'0');
  var s = String(now.getSeconds()).padStart(2,'0');
  
  // Small nav clock
  var el = document.getElementById('nav-clock');
  if(el) el.textContent = clockShowSeconds ? (h+':'+m+':'+s) : (h+':'+m);
  
  // Fullscreen clock
  var fsH = document.getElementById('fs-clock-time');
  var fsS = document.getElementById('fs-clock-seconds');
  if(fsH) {
    fsH.textContent = h + ':' + m;
    if(fsS) {
      fsS.textContent = ':' + s;
      fsS.style.opacity = clockShowSeconds ? '1' : '0';
    }
  }
  // Date on fullscreen
  var fsD = document.getElementById('fs-clock-date');
  if(fsD) {
    var days = ['Diumenge','Dilluns','Dimarts','Dimecres','Dijous','Divendres','Dissabte'];
    var months = ['gener','febrer','març','abril','maig','juny','juliol','agost','setembre','octubre','novembre','desembre'];
    fsD.textContent = days[now.getDay()] + ', ' + now.getDate() + ' de ' + months[now.getMonth()] + ' de ' + now.getFullYear();
  }
}

function openClockFullscreen() {
  var overlay = document.getElementById('clock-fullscreen');
  if(!overlay) return;
  clockFullscreenOpen = true;
  overlay.style.display = 'flex';
  requestAnimationFrame(() => { requestAnimationFrame(() => { overlay.style.opacity = '1'; }); });
  var btn = document.getElementById('fs-toggle-seconds');
  if(btn) btn.textContent = clockShowSeconds ? '\u23f1 Amagar segons' : '\u23f1 Mostrar segons';

  // ── Left: upcoming tasks ──
  var tasksPanel = document.getElementById('fs-tasks-panel');
  if(tasksPanel && typeof examList !== 'undefined') {
    var today = new Date(); today.setHours(0,0,0,0);
    var pending = examList.filter(function(e){ return !e.done && e.date; })
      .sort(function(a,b){ return a.date.localeCompare(b.date); }).slice(0,4);
    if(!pending.length) {
      tasksPanel.innerHTML = '<div class="fs-empty">cap tasca pendent \uD83C\uDF89</div>';
    } else {
      tasksPanel.innerHTML = pending.map(function(e){
        var d = new Date(e.date+'T00:00:00');
        var diff = Math.ceil((d - today) / 86400000);
        var bc = diff < 0 ? 'urgent' : diff === 0 ? 'today' : diff <= 2 ? 'urgent' : diff <= 5 ? 'soon' : 'ok';
        var bt = diff < 0 ? 'PASSAT' : diff === 0 ? 'AVUI' : diff === 1 ? 'DEM\u00C0' : diff+'d';
        return '<div class="fs-task-item"><span class="fs-task-badge '+bc+'">'+bt+'</span><span>'+e.name+'</span></div>';
      }).join('');
    }
  }

  // ── Left: today calendar events ──
  var todayPanel = document.getElementById('fs-today-panel');
  if(todayPanel && typeof monthEvents !== 'undefined') {
    var todayKey = toLocalDateKey(new Date());
    var evs = (monthEvents[todayKey] || []).slice(0, 3);
    if(!evs.length) {
      todayPanel.innerHTML = '<div class="fs-empty">res avui</div>';
    } else {
      todayPanel.innerHTML = evs.map(function(ev){
        var icon = ev.type==='exam'?'\uD83D\uDCDD':ev.type==='deures'?'\uD83D\uDCDA':ev.type==='partit'?'\uD83C\uDFF2':'\uD83D\uDCCC';
        return '<div class="fs-task-item">'+icon+' <span>'+ev.text+'</span></div>';
      }).join('');
    }
  }

  // ── Right: streak ──
  var streakEl = document.getElementById('fs-streak-num');
  var streakDots = document.getElementById('fs-streak-dots');
  if(streakEl) { var n = document.getElementById('streak-num'); streakEl.textContent = n ? n.textContent : '0'; }
  if(streakDots && typeof streakData !== 'undefined') {
    var html = '';
    for(var i=13; i>=0; i--) {
      var dd = new Date(); dd.setDate(dd.getDate()-i); dd.setHours(12,0,0,0);
      var k = toLocalDateKey(dd);
      var cls = 'fs-streak-dot'+(streakData.days[k]?' done':'')+(i===0?' today-dot':'');
      html += '<div class="'+cls+'"></div>';
    }
    streakDots.innerHTML = html;
  }

  // ── Right: goal ──
  var gp = document.getElementById('fs-goal-panel');
  if(gp && typeof goalData !== 'undefined') {
    gp.innerHTML = (goalData.icon||'\uD83D\uDE80')+' <strong style="color:rgba(255,255,255,0.75);font-size:14px;">'+(goalData.title||'')+'</strong>'
      +(goalData.desc?'<div style="margin-top:6px;font-size:11px;color:rgba(255,255,255,0.3);">'+goalData.desc+'</div>':'');
  }

  updateClock();
}

function closeClockFullscreen() {
  var overlay = document.getElementById('clock-fullscreen');
  if(!overlay) return;
  clockFullscreenOpen = false;
  overlay.style.opacity = '0';
  setTimeout(() => { overlay.style.display = 'none'; }, 350);
}

function toggleClockSeconds() {
  clockShowSeconds = !clockShowSeconds;
  localStorage.setItem('clock_show_seconds', clockShowSeconds);
  var btn = document.getElementById('fs-toggle-seconds');
  if(btn) btn.textContent = clockShowSeconds ? '⏱ Amagar segons' : '⏱ Mostrar segons';
  updateClock();
}

document.addEventListener('DOMContentLoaded', () => {
  updateClock();
  setInterval(updateClock, 1000);

  // Keyboard ESC closes fullscreen clock
  document.addEventListener('keydown', (e) => {
    if(e.key === 'Escape' && clockFullscreenOpen) {
      closeClockFullscreen();
      e.stopPropagation();
    }
  }, true);

  if(!localStorage.getItem('groq_api_key')) {
    console.warn('[Julians] Sense API Key de Groq. Ves a Configuració > IA per afegir la teva clau.');
  }
});

