// ══════════════════════════════════════════════════════
//  DOCUMENT PROCESSING — PDF & WORD
// ══════════════════════════════════════════════════════
let attachedDoc = null; // { name, type, base64, mediaType, size }

function handleFileAttach(input) {
  const file = input.files[0];
  if(!file) return;
  
  // Validate type
  const isPDF  = file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf');
  const isDocx = file.type.includes('wordprocessingml') || file.name.toLowerCase().endsWith('.docx') || file.name.toLowerCase().endsWith('.doc');
  
  if(!isPDF && !isDocx) {
    showDocError('Només accepta PDF o Word (.docx). Intenta de nou.');
    input.value = '';
    return;
  }
  
  const maxMB = 10;
  if(file.size > maxMB * 1024 * 1024) {
    showDocError(`El document és massa gran (màx ${maxMB}MB).`);
    input.value = '';
    return;
  }
  
  const reader = new FileReader();
  reader.onload = (e) => {
    const dataUrl = e.target.result;
    const base64  = dataUrl.split(',')[1];
    attachedDoc = {
      name: file.name,
      base64,
      mediaType: isPDF ? 'application/pdf' : 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      isPDF,
      isDocx,
      size: (file.size / 1024).toFixed(0) + 'KB'
    };
    showDocPreview(file.name, isPDF ? '📄' : '📝');
  };
  reader.onerror = () => showDocError('Error llegint el document.');
  reader.readAsDataURL(file);
}

function showDocPreview(name, icon) {
  const preview = document.getElementById('ai-doc-preview');
  document.getElementById('ai-doc-icon').textContent = icon;
  document.getElementById('ai-doc-name').textContent = name + ' (' + attachedDoc.size + ')';
  preview.classList.add('active');
  document.querySelector('.ai-attach-btn')?.classList.add('has-file');
  // Focus input
  document.getElementById('ai-chat-input')?.focus();
}

function removeAttachment() {
  attachedDoc = null;
  document.getElementById('ai-doc-preview').classList.remove('active');
  document.querySelector('.ai-attach-btn')?.classList.remove('has-file');
  document.getElementById('ai-file-input').value = '';
}

function showDocError(msg) {
  const box = document.getElementById('ai-messages');
  const el  = document.createElement('div');
  el.className = 'ai-msg assistant';
  el.innerHTML = `<span style="color:#fca5a5;">⚠️ ${msg}</span>`;
  box.appendChild(el); scrollToBottom();
}

// ── Override sendAI to support document attachments + mode estudi ──
async function sendAI() {
  // MODE ESTUDI: ruta especial
  if(aiMode === 'estudi') {
    const input = document.getElementById('ai-chat-input');
    const userMsg = input.value.trim();
    const hasDoc = !!attachedDoc;

    // Necessitem almenys text o document
    if(!userMsg && !hasDoc) return;
    input.value = '';

    if(!getAPIKey()) {
      const chatLog = document.getElementById('ai-messages');
      const warn = document.createElement('div');
      warn.className = 'ai-msg assistant';
      warn.innerHTML = '<span style="color:#fca5a5;">⚠️ Configura la clau Groq a ⚙️ Configuració → 🔑 IA</span>';
      chatLog?.appendChild(warn);
      return;
    }

    if(!aiChats[aiCurrentChatId]) createNewChat(false);
    const chat = aiChats[aiCurrentChatId];

    // Afegir missatge de l\'usuari a l\'historial
    const displayMsg = (userMsg ? userMsg : '📎 Analitza aquest document') +
      (hasDoc ? '\n\n📄 *' + attachedDoc.name + '* (' + attachedDoc.size + ')' : '');
    chat.messages.push({ role: 'user', text: displayMsg });
    if(chat.messages.length === 1) chat.title = (hasDoc ? 'Estudi: ' + attachedDoc.name : userMsg).substring(0, 32);
    localStorage.setItem('julians_chats_v2', JSON.stringify(aiChats));
    renderAISidebar(); renderAIMessages();

    // Desactivar botó i mostrar indicador d\'extracció
    document.getElementById('ai-chat-send').disabled = true;
    let docContent = null;
    if(hasDoc) {
      const box = document.getElementById('ai-messages');
      const extractEl = document.createElement('div');
      extractEl.className = 'ai-msg thinking';
      extractEl.id = 'estudi-extract-indicator';
      extractEl.innerHTML = '<div class="ai-typing"><span></span><span></span><span></span></div><span style="font-size:10px;opacity:0.5;display:block;margin-top:4px;">📄 Llegint document...</span>';
      box.appendChild(extractEl); scrollToBottom();

      const docRef = attachedDoc;
      clearAttachment();
      if(docRef.isPDF) {
        try { docContent = await extractPDFText(docRef.base64); } catch(e) { docContent = '[No s\'ha pogut llegir el PDF]'; }
      } else {
        try { docContent = await extractDocxText(docRef.base64); } catch(e) { docContent = '[No s\'ha pogut llegir el document]'; }
      }
      document.getElementById('estudi-extract-indicator')?.remove();
    }

    document.getElementById('ai-chat-send').disabled = false;
    return sendAIEstudi(userMsg, docContent);
  }

  // If no document attached, use base sendAI
  if(!attachedDoc) { return sendAIBase(); }
  
  const input   = document.getElementById('ai-chat-input');
  const userMsg = input.value.trim();
  const doc     = attachedDoc;
  
  if(!doc.base64) { showDocError('Document no carregat correctament.'); return; }
  
  if(!aiChats[aiCurrentChatId]) createNewChat(false);
  const chat = aiChats[aiCurrentChatId];
  
  const displayMsg = (userMsg || '📎 Processa aquest document') + `\n\n📄 *${doc.name}* (${doc.size})`;
  chat.messages.push({role:'user', text: displayMsg});
  if(chat.messages.length === 1) chat.title = (userMsg || 'Doc: ' + doc.name).substring(0, 32);
  
  input.value = '';
  removeAttachment();
  localStorage.setItem('julians_chats_v2', JSON.stringify(aiChats));
  renderAISidebar(); renderAIMessages();
  
  // Show typing
  const box = document.getElementById('ai-messages');
  const typingEl = document.createElement('div');
  typingEl.className = 'ai-msg thinking';
  typingEl.innerHTML = `<div class="ai-typing"><span></span><span></span><span></span></div><span style="font-size:10px;opacity:0.5;display:block;margin-top:4px;">📄 Processant ${doc.isPDF ? 'PDF' : 'document Word'}...</span>`;
  box.appendChild(typingEl); scrollToBottom();
  document.getElementById('ai-chat-send').disabled = true;
  
  try {
    const mode = AI_MODES[aiMode] || AI_MODES.rapid;
    
    const systemPrompt = `Ets Julians, l'assistent personal intel·ligent de l'Julià Domingo a JOmaxPath. Parles sempre en català.
${buildCalendarContext()}

L'usuari t'ha adjuntat un document. La teva feina és:
1. Llegir i comprendre el document complet.
2. Si l'usuari fa una pregunta concreta, respon-la basant-te en el document.
3. Si l'usuari diu "fes el que s'indica" o similar, extreu les instruccions del document i executa-les (afegir tasques, events, canviar l'objectiu, etc.) usant les eines disponibles.
4. Si no hi ha cap instrucció específica, fes un resum clar i estructurat del contingut.
5. Sempre explica el que has trobat i/o executat.
${mode.suffix}`;
    
    const instruction = userMsg || `Llegeix aquest document i executa qualsevol instrucció que hi trobis. Si no hi ha instruccions específiques, fes un resum detallat del contingut.`;
    
    // Build user message with document
    let userContent;
    if(doc.isPDF) {
      // PDFs: use document type
      userContent = [
        {
          type: 'document',
          source: {
            type: 'base64',
            media_type: 'application/pdf',
            data: doc.base64
          }
        },
        { type: 'text', text: instruction }
      ];
    } else {
      // DOCX: Extract text from ZIP XML structure
      typingEl.innerHTML = `<div class="ai-typing"><span></span><span></span><span></span></div><span style="font-size:10px;opacity:0.5;display:block;margin-top:4px;">📝 Extraient text del Word...</span>`;
      let extractedText = '';
      try { extractedText = await extractDocxText(doc.base64); } catch(e) {}
      if(!extractedText || extractedText.length < 20) {
        typingEl.remove();
        document.getElementById('ai-chat-send').disabled = false;
        chat.messages.push({role:'assistant', text: '⚠️ No he pogut llegir el Word.\n\n**Solució:** Converteix a **PDF** (Fitxer → Exportar → PDF) i adjunta\'l de nou.'});
        localStorage.setItem('julians_chats_v2', JSON.stringify(aiChats));
        renderAIMessages(); return;
      }
      userContent = [
        { type:'document', source:{ type:'text', media_type:'text/plain', data: extractedText.substring(0,80000) } },
        { type:'text', text: instruction + '\n\n[Document Word: ' + doc.name + ']' }
      ];
    }
    
    const tools = getAITools();
    
    // Extreiem el text del document per enviar-lo a Groq com a text
    let docTextContent = '';
    if(doc.isPDF) {
      typingEl.innerHTML = `<div class="ai-typing"><span></span><span></span><span></span></div><span style="font-size:10px;opacity:0.5;display:block;margin-top:4px;">📄 Extraient text del PDF...</span>`;
      try {
        docTextContent = await extractPDFText(doc.base64);
      } catch(e) { docTextContent = '[No s\'ha pogut llegir el PDF]'; }
    } else {
      docTextContent = userContent.find(b => b.type === 'document')?.source?.data || '';
    }
    // Limitar tokens enviats a Groq
    if(docTextContent.length > 12000) {
      docTextContent = docTextContent.substring(0, 12000) + '\n[... document retallat per limit de tokens ...]';
    }
    
    const groqDocMsgs = [
      {role:'system', content: systemPrompt},
      {role:'user', content: instruction + '\n\n--- CONTINGUT DEL DOCUMENT: ' + doc.name + ' ---\n' + docTextContent}
    ];
    
    const resp1 = await fetch('https://api.groq.com/openai/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + getAPIKey()
      },
      body: JSON.stringify({
        model: 'llama-3.3-70b-versatile',
        max_tokens: Math.max(mode.max_tokens, 2000),
        tools,
        tool_choice: 'auto',
        messages: groqDocMsgs
      })
    });
    const data1 = await resp1.json();
    
    if(!resp1.ok) {
      typingEl.remove();
      document.getElementById('ai-chat-send').disabled = false;
      const errCode = data1?.error?.code || '';
      const errMsg = String(data1?.error?.message || '');
      let err;
      if(errCode === 'rate_limit_exceeded' || errMsg.includes('rate_limit')) {
        err = "⏳ Límit d'ús assolit. Torna a provar en uns minuts.";
      } else if(errCode === 'context_length_exceeded' || errMsg.includes('context') || errMsg.includes('token')) {
        err = '⚠️ El document és massa llarg. Prova amb un PDF més curt.';
      } else {
        err = '⚠️ Error Groq: ' + (errMsg || JSON.stringify(data1?.error)).substring(0, 200);
      }
      chat.messages.push({role:'assistant', text: err});
      localStorage.setItem('julians_chats_v2', JSON.stringify(aiChats));
      renderAIMessages(); return;
    }
    
    // Process tool calls (OpenAI format)
    const assistantMsg = data1.choices[0].message;
    const toolCalls = assistantMsg.tool_calls || [];
    let toolResults = [];
    let textFromFirst = assistantMsg.content || '';
    
    for(const tc of toolCalls) {
      let input = {};
      try { input = JSON.parse(tc.function.arguments); } catch(e) {}
      const result = executeAITool(tc.function.name, input);
      toolResults.push({role:'tool', tool_call_id: tc.id, content: String(result)});
    }
    
    let finalText = textFromFirst;
    
    // Second call if tools used
    if(toolResults.length > 0) {
      const msgs2 = [
        {role:'system', content: systemPrompt},
        {role:'user', content: groqDocMsgs[1].content},
        {role:'assistant', content: assistantMsg.content||null, tool_calls: toolCalls},
        ...toolResults
      ];
      const resp2 = await fetch('https://api.groq.com/openai/v1/chat/completions', {
        method:'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer ' + getAPIKey()
        },
        body: JSON.stringify({
          model: 'llama-3.3-70b-versatile',
          max_tokens: Math.max(mode.max_tokens, 2000),
          tools,
          tool_choice: 'auto',
          messages: msgs2
        })
      });
      const data2 = await resp2.json();
      finalText = data2.choices?.[0]?.message?.content || '';
      if(!finalText) finalText = toolResults.map(r=>r.content).join('\n');
    }
    
    typingEl.remove();
    document.getElementById('ai-chat-send').disabled = false;
    
    const answer = finalText.trim() || '✅ Document processat!';
    chat.messages.push({role:'assistant', text: answer});
    localStorage.setItem('julians_chats_v2', JSON.stringify(aiChats));
    renderAISidebar(); renderAIMessages();
    
  } catch(err) {
    typingEl.remove();
    document.getElementById('ai-chat-send').disabled = false;
    chat.messages.push({role:'assistant', text: '⚠️ Error de connexió processant el document.'});
    localStorage.setItem('julians_chats_v2', JSON.stringify(aiChats));
    renderAIMessages();
  }
}

