// ══════════════════════════════════════════════════════
//  DOCX TEXT EXTRACTOR
//  DOCX is a ZIP file. word/document.xml has the text.
//  We decode base64 → Uint8Array, find document.xml,
//  strip XML tags → plain text.
// ══════════════════════════════════════════════════════

// ══════════════════════════════════════════════════════
//  PDF TEXT EXTRACTOR (via pdf.js CDN)
// ══════════════════════════════════════════════════════
async function extractPDFText(base64) {
  if(!window.pdfjsLib) {
    await new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';
      script.onload = resolve;
      script.onerror = reject;
      document.head.appendChild(script);
    });
    window.pdfjsLib.GlobalWorkerOptions.workerSrc =
      'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
  }
  const binaryStr = atob(base64);
  const bytes = new Uint8Array(binaryStr.length);
  for(let i = 0; i < binaryStr.length; i++) bytes[i] = binaryStr.charCodeAt(i);
  const pdf = await window.pdfjsLib.getDocument({ data: bytes }).promise;
  let fullText = '';
  for(let i = 1; i <= pdf.numPages; i++) {
    const page = await pdf.getPage(i);
    const content = await page.getTextContent();
    fullText += '[Pagina ' + i + ']\n' + content.items.map(item => item.str).join(' ') + '\n\n';
    if(fullText.length > 15000) { fullText += '[... mes pagines no incloses ...]'; break; }
  }
  return fullText.trim() || '[PDF sense text extret]';
}

async function extractDocxText(base64) {
  // Decode base64 to bytes
  const bin = atob(base64);
  const bytes = new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++) bytes[i] = bin.charCodeAt(i);
  
  // Parse ZIP manually (DOCX is ZIP)
  const xmlContent = findZipEntry(bytes, 'word/document.xml');
  if(!xmlContent) return null;
  
  // Decode UTF-8
  const decoder = new TextDecoder('utf-8');
  const xml = decoder.decode(xmlContent);
  
  // Extract text from XML (remove all tags, keep text content)
  let text = xml
    .replace(/<w:p[ >]/g, '\n<w:p ')  // paragraphs → newlines
    .replace(/<w:br[^>]*>/g, '\n')      // line breaks
    .replace(/<w:tab[^>]*>/g, '\t')     // tabs
    .replace(/<[^>]+>/g, '')            // remove all tags
    .replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'")
    .replace(/\n{3,}/g,'\n\n')          // collapse multiple newlines
    .trim();
  
  return text.length > 10 ? text : null;
}

// Minimal ZIP parser - find a file entry by name
function findZipEntry(bytes, targetName) {
  const view = new DataView(bytes.buffer);
  let offset = 0;
  
  while(offset < bytes.length - 30) {
    const sig = view.getUint32(offset, true);
    if(sig !== 0x04034b50) break; // local file header signature
    
    const compMethod  = view.getUint16(offset + 8,  true);
    const compSize    = view.getUint32(offset + 18, true);
    const uncompSize  = view.getUint32(offset + 22, true);
    const nameLen     = view.getUint16(offset + 26, true);
    const extraLen    = view.getUint16(offset + 28, true);
    
    const nameBytes   = bytes.slice(offset + 30, offset + 30 + nameLen);
    const name        = new TextDecoder().decode(nameBytes);
    const dataOffset  = offset + 30 + nameLen + extraLen;
    
    if(name === targetName) {
      const compData = bytes.slice(dataOffset, dataOffset + compSize);
      if(compMethod === 0) {
        // Stored (uncompressed)
        return compData;
      } else if(compMethod === 8) {
        // Deflate — use DecompressionStream if available
        try {
          return decompressDeflate(compData, uncompSize);
        } catch(e) { return null; }
      }
    }
    offset = dataOffset + compSize;
  }
  return null;
}

async function decompressDeflate(data, expectedSize) {
  if(typeof DecompressionStream === 'undefined') return null;
  // Deflate (raw) — wrap with DecompressionStream
  const ds = new DecompressionStream('raw');  // not supported everywhere
  // Fallback: try 'deflate-raw' 
  try {
    const stream = new DecompressionStream('deflate-raw');
    const writer = stream.writable.getWriter();
    const reader = stream.readable.getReader();
    writer.write(data);
    writer.close();
    const chunks = [];
    while(true) {
      const {done, value} = await reader.read();
      if(done) break;
      chunks.push(value);
    }
    const result = new Uint8Array(chunks.reduce((a,b)=>a+b.length,0));
    let pos = 0;
    for(const chunk of chunks) { result.set(chunk, pos); pos += chunk.length; }
    return result;
  } catch(e) {
    // Try with 'deflate' (zlib)
    try {
      const stream2 = new DecompressionStream('deflate');
      // Add zlib header
      const zlib = new Uint8Array(data.length + 2);
      zlib[0] = 0x78; zlib[1] = 0x9C;
      zlib.set(data, 2);
      const writer2 = stream2.writable.getWriter();
      const reader2 = stream2.readable.getReader();
      writer2.write(zlib); writer2.close();
      const chunks2 = [];
      while(true) { const {done,value} = await reader2.read(); if(done) break; chunks2.push(value); }
      const result2 = new Uint8Array(chunks2.reduce((a,b)=>a+b.length,0));
      let p = 0; for(const c of chunks2) { result2.set(c, p); p += c.length; }
      return result2;
    } catch(e2) { return null; }
  }
}

