function showInfo(key) {
  const data = INFO_CONTENT[key];
  if(!data) return;
  document.getElementById('info-icon').textContent  = data.icon;
  document.getElementById('info-title').textContent = data.title;
  document.getElementById('info-body').innerHTML    = data.body;
  document.getElementById('info-tooltip-overlay').classList.add('open');
}
function closeInfo() {
  document.getElementById('info-tooltip-overlay').classList.remove('open');
}
// Close on Escape  
document.addEventListener('keydown', e => {
  if(e.key === 'Escape') closeInfo();
});

