//  CHAT DELETE — CUSTOM MODAL SYSTEM
// ══════════════════════════════════════════════════════
let pendingDeleteIds = [];

function closeChatDeleteModal() {
  document.getElementById('chat-delete-modal').classList.remove('open');
  pendingDeleteIds = [];
}

function executeChatDelete() {
  for(const id of pendingDeleteIds) {
    delete aiChats[id];
  }
  // If current chat was deleted, switch to another
  if(!aiChats[aiCurrentChatId]) {
    const keys = Object.keys(aiChats);
    if(keys.length) aiCurrentChatId = keys[0];
    else { createNewChat(false); closeChatDeleteModal(); return; }
  }
  aiSelectedIds.clear();
  aiSelectMode = false;
  localStorage.setItem('julians_chats_v2', JSON.stringify(aiChats));
  closeChatDeleteModal();
  renderAISidebar();
  renderAIMessages();
}

// Close on Escape
document.addEventListener('keydown', e => {
  if(e.key === 'Escape') closeChatDeleteModal();
});

