//  EDITABLE MATCHES TITLE
// ══════════════════════════════════════════════════════
let matchesTitle = localStorage.getItem('matches_title') || '🏒 partits de la temporada';
function applyMatchesTitle() {
  const el = document.getElementById('matches-title-display');
  if(el) el.textContent = matchesTitle;
}
function editMatchesTitle() {
  const el = document.getElementById('matches-title-display');
  if(!el) return;
  const inp = document.createElement('input');
  inp.type = 'text';
  inp.value = matchesTitle;
  inp.style.cssText = 'background:var(--card2);border:1px solid rgba(239,68,68,0.4);color:var(--text);font-family:"Space Mono",monospace;font-size:11px;letter-spacing:2px;padding:4px 10px;border-radius:8px;outline:none;width:260px;text-transform:uppercase;';
  el.replaceWith(inp);
  inp.focus(); inp.select();
  const save = () => {
    matchesTitle = inp.value.trim() || '🏒 partits de la temporada';
    localStorage.setItem('matches_title', matchesTitle);
    inp.replaceWith(el);
    applyMatchesTitle();
  };
  inp.addEventListener('blur', save);
  inp.addEventListener('keydown', e => { if(e.key==='Enter') inp.blur(); if(e.key==='Escape'){ inp.value=matchesTitle; inp.blur(); } });
}
document.addEventListener('DOMContentLoaded', () => { applyMatchesTitle(); });

