// ── Pàgina de login ──────────────────────────────────
function showAuthOverlay() {
  const o = document.getElementById('auth-overlay');
  o.style.display = 'flex';
  requestAnimationFrame(()=>requestAnimationFrame(()=>o.classList.add('visible')));
  setTimeout(()=>document.getElementById('auth-email')?.focus(), 350);
}
function hideAuthOverlay() {
  const o = document.getElementById('auth-overlay');
  o.classList.remove('visible');
  o.style.pointerEvents = 'none';
  setTimeout(()=>{ o.style.display='none'; o.style.opacity=''; }, 300);
}
function switchAuthTab(tab) {
  document.getElementById('auth-login-form').style.display = tab==='login'?'block':'none';
  document.getElementById('auth-register-form').style.display = tab==='register'?'block':'none';
  document.getElementById('tab-login').classList.toggle('active', tab==='login');
  document.getElementById('tab-register').classList.toggle('active', tab==='register');
  authMsg('','');
}
function authMsg(txt, type) {
  const el = document.getElementById('auth-msg');
  el.textContent = txt;
  el.className = type;
}
function setAuthBtnLoading(loading) {
  const btns = document.querySelectorAll('.auth-btn');
  btns.forEach(b=>b.disabled=loading);
}

async function authLogin() {
  const email = document.getElementById('auth-email').value.trim();
  const pass  = document.getElementById('auth-password').value;
  if(!email||!pass) { authMsg('Omple tots els camps','error'); return; }
  setAuthBtnLoading(true);
  authMsg('Entrant...','');
  if(!supa){authMsg('Error de connexió. Torna-ho a intentar.','error');setAuthBtnLoading(false);return;}
  const { data, error } = await supa.auth.signInWithPassword({ email, password:pass });
  setAuthBtnLoading(false);
  if(error) { authMsg(error.message,'error'); return; }
  supaUser = data.user;
  await loadFromSupabase();
  checkPremiumStatus(supaUser.id);
  hideAuthOverlay();
  updateAuthIndicator();
  showSyncToast('✅ Sessió iniciada');
}

async function authRegister() {
  const email = document.getElementById('auth-reg-email').value.trim();
  const pass  = document.getElementById('auth-reg-password').value;
  if(!email||!pass) { authMsg('Omple tots els camps','error'); return; }
  if(pass.length < 6) { authMsg('La contrasenya ha de tenir mínim 6 caràcters','error'); return; }
  setAuthBtnLoading(true);
  authMsg('Creant compte...','');
  if(!supa){authMsg('Error de connexió. Torna-ho a intentar.','error');setAuthBtnLoading(false);return;}
  const { data, error } = await supa.auth.signUp({ email, password:pass });
  setAuthBtnLoading(false);
  if(error) { authMsg(error.message,'error'); return; }
  if(data.user && !data.session) {
    authMsg('✅ Comprova el teu correu per confirmar el compte!','ok');
  } else {
    supaUser = data.user;
    await saveToSupabase();
    hideAuthOverlay();
    updateAuthIndicator();
    showSyncToast('✅ Compte creat!');
  }
}

function authSkip() {
  // Continuar sense compte — guardem el flag per no tornar a demanar
  localStorage.setItem('auth_skipped', '1');
  hideAuthOverlay();
}

// ── Indicador d'usuari ───────────────────────────────
function updateAuthIndicator() {
  const ind = document.getElementById('auth-indicator');
  const emailEl = document.getElementById('auth-user-email');
  const dot = document.getElementById('auth-dot');
  const drawerUserSection = document.getElementById('drawer-user-section');

  if(supaUser) {
    // Mostra indicador al drawer
    if(ind) ind.style.display = 'flex';
    if(emailEl) {
      const email = supaUser.email || '';
      emailEl.textContent = email;
      emailEl.title = email;
    }
    if(dot) dot.className = 'auth-dot';
    // Amaga el botó "Iniciar sessió" si existeix
    const loginBtn = document.getElementById('drawer-login-btn');
    if(loginBtn) loginBtn.style.display = 'none';
  } else {
    // Amaga indicador
    if(ind) ind.style.display = 'none';
    // Mostra botó "Iniciar sessió"
    const loginBtn = document.getElementById('drawer-login-btn');
    if(loginBtn) loginBtn.style.display = 'flex';
  }
}

function authShowMenu() {
  if(!supaUser) {
    showAuthOverlay();
    return;
  }
  if(confirm('Compte: ' + supaUser.email + '\n\nVols tancar sessió?')) {
    authLogout();
  }
}


