// ── Sync Toast ───────────────────────────────────────
let toastTimer = null;
function showSyncToast(msg) {
  const t = document.getElementById('sync-toast');
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(()=>t.classList.remove('show'), 2500);
}

function setSyncDot(state) {
  const dot = document.getElementById('auth-dot');
  if(dot) dot.className = 'auth-dot' + (state==='syncing'?' syncing':state==='offline'?' offline':'');
}

// ── Guardar a Supabase ───────────────────────────────
async function saveToSupabase() {
  if(!supa || !supaUser) return;
  setSyncDot('syncing');
  const data = {};
  ALL_KEYS.forEach(k => {
    const v = localStorage.getItem(k);
    if(v) try { data[k] = JSON.parse(v); } catch(e) { data[k] = v; }
  });
  // Protecció: no guardar si localStorage és completament buit
  // (evita sobreescriure dades del servidor quan s'obre en un dispositiu nou)
  const hasRealData = Object.keys(data).length > 0 &&
    Object.values(data).some(v => {
      if(Array.isArray(v)) return v.length > 0;
      if(typeof v === 'object' && v !== null) return Object.keys(v).length > 0;
      return !!v;
    });
  if(!hasRealData) {
    console.warn('[Supabase] Save ignorat: sense dades locals. Carregant del servidor...');
    setSyncDot('');
    await loadFromSupabase();
    return;
  }
  const { error } = await supa.from('user_data').upsert({
    user_id: supaUser.id,
    data: data,
    updated_at: new Date().toISOString()
  }, { onConflict: 'user_id' });
  setSyncDot(error ? 'offline' : '');
  if(!error) showSyncToast('⚡ Sincronitzat');
  else console.warn('[Supabase] Error guardant:', error.message);
}

// ── Carregar de Supabase ─────────────────────────────
async function loadFromSupabase() {
  if(!supa || !supaUser) return;
  setSyncDot('syncing');
  const { data, error } = await supa.from('user_data').select('data').eq('user_id', supaUser.id).single();
  setSyncDot(error ? 'offline' : '');
  if(error) {
    if(error.code === 'PGRST116') {
      // Fila no trobada = compte nou → guardar dades locals actuals
      console.log('[Supabase] Compte nou, guardant dades inicials...');
      await saveToSupabase();
    } else {
      // Error de connexió/auth → NO sobreescriure les dades del servidor amb localStorage buit
      console.warn('[Supabase] Error carregant:', error.message);
      showSyncToast('⚠️ Error de connexió. Les dades locals estan mantingudes.');
    }
    return;
  }
  if(!data?.data) return;
  // Escriure al localStorage i recarregar variables
  const d = data.data;
  ALL_KEYS.forEach(k => {
    if(d[k] !== undefined) localStorage.setItem(k, JSON.stringify(d[k]));
  });
  // Recarregar totes les variables globals
  try {
    if(d['exams_v3'])       { examList = d['exams_v3']; }
    if(d['month_events_v2']){ monthEvents = d['month_events_v2']; }
    if(d['day_events_v2'])  { dayEvents = d['day_events_v2']; }
    if(d['timed_events_v1']){ timedEvents = d['timed_events_v1']; }
    if(d['streak_v2'])      { streakData = d['streak_v2']; }
    if(d['prog_v2'])        { progData = d['prog_v2']; }
    if(d['goal_v2'])        { goalData = d['goal_v2']; }
    if(d['moto_v2'])        { motoData = d['moto_v2']; }
    if(d['victories_v2'])   { victoriesData = d['victories_v2']; }
    if(d['schedule_v2'])    { daySchedule = d['schedule_v2']; }
    if(d['profile_v2'])     { profileData = d['profile_v2']; }
    if(d['day_badges_v2'])  { dayBadges = d['day_badges_v2']; }
    if(d['julians_chats_v2']){ aiChats = d['julians_chats_v2']; }
    if(d['theme_v1'])       { applyTheme(d['theme_v1']); }
    // ── Migració: esborrar partits antics de versions anteriors ──
    const OLD_TEAMS = ['MOLLERUSSA','CALAFELL','MANLLEU','OLOT','CERDANYOLA','MARTINELIA','SANT CUGAT','CADÍ'];
    const rawM = d['matches_v1'];
    if(rawM && Array.isArray(rawM)) {
      const hasOld = rawM.some(m =>
        /^m[1-8]$/.test(m.id) ||
        OLD_TEAMS.some(t => (m.home||'').toUpperCase().includes(t) || (m.away||'').toUpperCase().includes(t))
      );
      if(hasOld) {
        customMatches = [];
        localStorage.removeItem('matches_v1');
        setTimeout(() => saveToSupabase(), 800);
        console.log('[JOmaxPath] Partits antics eliminats automàticament');
      } else {
        customMatches = rawM;
      }
    } else {
      customMatches = [];
    }
  } catch(e) { console.warn('[Supabase] Error recàrrega vars:', e); }
  // Re-render tot
  renderProfile(); renderGoal(); renderMoto(); renderProgress();
  renderStreak(); renderWeekDates(); renderWeekGrid();
  renderExams(); renderNextUp(); renderCalendar();
  renderMatches(); renderVictories(); renderAllDayEvents(); renderAISidebar();
  showSyncToast('📥 Dades carregades');
  // Carregar taulers compartits en segon pla
  setTimeout(async()=>{ await loadBoardsFromSupabase(); }, 500);
}

// ── Auto-sync: debounce quan canvia localStorage ─────
const _origSetItem = localStorage.setItem.bind(localStorage);
localStorage.setItem = function(key, value) {
  _origSetItem(key, value);
  if(supa && supaUser && ALL_KEYS.includes(key)) {
    clearTimeout(syncTimer);
    syncTimer = setTimeout(saveToSupabase, 2000);
  }
};

// ── Init: comprovar sessió existent ──────────────────
document.addEventListener('DOMContentLoaded', async () => {
  // Inicialitzar Supabase — esperar fins a 3s si el SDK no ha carregat encara
  let supaOk = initSupabase();
  if(!supaOk) {
    for(let i=0; i<30; i++) {
      await new Promise(r=>setTimeout(r,100));
      supaOk = initSupabase();
      if(supaOk) break;
    }
  }
  if(!supaOk) {
    console.warn('[Auth] Continuant sense Supabase');
    return;
  }

  try {
    const { data: { session } } = await supa.auth.getSession();
    if(session?.user) {
      // Sessió activa — entrar directament sense login
      supaUser = session.user;
      updateAuthIndicator();
      await loadFromSupabase();
      checkPremiumStatus(supaUser.id);
    } else {
      // Sense sessió — mostrar login NOMÉS si no ha dit "Continuar sense compte"
      if(!localStorage.getItem('auth_skipped')) {
        showAuthOverlay();
      }
    }
  } catch(e) {
    console.warn('[Auth] Error getSession:', e);
    if(!localStorage.getItem('auth_skipped')) showAuthOverlay();
  }

  // Escolta canvis d'autenticació
  supa.auth.onAuthStateChange(async (event, session) => {
    if(event === 'SIGNED_IN' && session?.user) {
      supaUser = session.user;
      updateAuthIndicator();
      // Carregar taulers compartits en iniciar sessió
      setTimeout(async()=>{ await loadBoardsFromSupabase(); }, 1000);
    } else if(event === 'SIGNED_OUT') {
      supaUser = null;
      updateAuthIndicator();
    }
  });
});

