//  POMODORO FULLSCREEN
// ═══════════════════════════════════════════════════════
const POMO_FS_CIRC = 2 * Math.PI * 88; // ~553

let pomoFsOpen = false;

function openPomoFullscreen() {
  const overlay = document.getElementById('pomo-fullscreen');
  if(!overlay) return;
  pomoFsOpen = true;
  overlay.style.display = 'flex';
  requestAnimationFrame(()=>requestAnimationFrame(()=>overlay.style.opacity='1'));
  updatePomoFsDisplay();
  updatePomoFsMusic();
}

function closePomoFullscreen() {
  const overlay = document.getElementById('pomo-fullscreen');
  if(!overlay) return;
  pomoFsOpen = false;
  overlay.style.opacity = '0';
  setTimeout(()=>overlay.style.display='none', 350);
}

function handlePomoFsClick(e) {
  // Close if clicking background (not controls)
  closePomoFullscreen();
}

// ── Sincronitzar controls del FS amb el timer real ──
function pomoFsAction() {
  pomoAction(); // executa el timer real
  updatePomoFsDisplay();
  const btn = document.getElementById('pomo-fs-start');
  if(btn) btn.textContent = pomoRunning ? '⏸ PAUSA' : '▶ REPRENDRE';
}

function pomoFsReset() {
  pomoReset();
  updatePomoFsDisplay();
  const btn = document.getElementById('pomo-fs-start');
  if(btn) { btn.textContent = '▶ INICIAR'; btn.className='pomo-fs-btn primary'; }
}

// ── Actualitzar el display del fullscreen ──
function updatePomoFsDisplay() {
  if(!pomoFsOpen) return;
  const total = (pomoPhase==='focus'?pomoFocusMins:pomoPhase==='break'?pomoBreakMins:pomoFocusMins*2)*60;
  const pct = pomoCurrent / total;
  const offset = POMO_FS_CIRC * (1 - pct);

  const arc = document.getElementById('pomo-fs-arc');
  if(arc) {
    arc.style.strokeDasharray = POMO_FS_CIRC;
    arc.style.strokeDashoffset = offset;
    arc.className = 'pomo-fs-arc' + (pomoPhase==='break'?' break-mode':pomoPhase==='long-break'?' long-break':'');
  }

  const m = Math.floor(pomoCurrent/60), s = pomoCurrent%60;
  const digits = document.getElementById('pomo-fs-digits');
  if(digits) {
    digits.textContent = String(m).padStart(2,'0') + ':' + String(s).padStart(2,'0');
    digits.className = pomoPhase==='break'?'break-glow':pomoPhase==='long-break'?'long-glow':'';
  }

  const phase = document.getElementById('pomo-fs-phase');
  if(phase) {
    phase.textContent = pomoPhase==='focus'?'FOCUS':pomoPhase==='break'?'DESCANS':'DESCANS LLARG';
    phase.className = pomoPhase==='break'?'break-col':pomoPhase==='long-break'?'long-col':'';
  }

  // Background gradient
  const overlay = document.getElementById('pomo-fullscreen');
  if(overlay) {
    overlay.className = pomoPhase==='break'?'break-bg':pomoPhase==='long-break'?'long-break-bg':'';
    overlay.style.display = 'flex'; // keep visible
  }

  // Session dots
  const dotsEl = document.getElementById('pomo-fs-dots');
  if(dotsEl) {
    dotsEl.innerHTML = '';
    for(let i=0;i<pomoSessions;i++) {
      const d = document.createElement('div');
      const done = i < (pomoSessionsDone % pomoSessions) || (i < pomoSessionsDone && pomoSessionsDone % pomoSessions === 0);
      d.className = 'pomo-fs-dot' + (done?' done':'') + (pomoPhase!=='focus'?' break-col':'');
      dotsEl.appendChild(d);
    }
  }

  // Btn text
  const btn = document.getElementById('pomo-fs-start');
  if(btn) btn.textContent = pomoRunning ? '⏸ PAUSA' : (pomoCurrent < (pomoPhase==='focus'?pomoFocusMins:pomoBreakMins)*60 ? '▶ REPRENDRE' : '▶ INICIAR');
}

// ── Música: Media Session API ──────────────────────────
function updatePomoFsMusic() {
  if(!pomoFsOpen) return;
  const trackEl  = document.getElementById('pomo-fs-music-track');
  const artistEl = document.getElementById('pomo-fs-music-artist');
  const barEl    = document.getElementById('pomo-fs-bar');
  const labelEl  = document.getElementById('pomo-fs-music-label');

  let track = '—', artist = '', isPlaying = false;

  // Media Session API (Spotify, YouTube, etc.)
  if(navigator.mediaSession && navigator.mediaSession.metadata) {
    const meta = navigator.mediaSession.metadata;
    track  = meta.title  || '—';
    artist = meta.artist || (meta.album || '');
    const state = navigator.mediaSession.playbackState;
    isPlaying = (state === 'playing');
  }

  if(trackEl)  trackEl.textContent  = track;
  if(artistEl) artistEl.textContent = artist;
  if(barEl)    barEl.className = 'pomo-fs-music-bar' + (isPlaying ? '' : ' paused');
  if(labelEl)  labelEl.textContent  = isPlaying ? 'ara sonant' : 'cap música detectada';

  // Poll every 3s while open
  if(pomoFsOpen) setTimeout(updatePomoFsMusic, 3000);
}

// ── Patch pomoTick per actualitzar el FS ──────────────
const _origPomoTick = pomoTick;
// Override updatePomoDisplay to also update FS
const _origUpdatePomoDisplay = updatePomoDisplay;
updatePomoDisplay = function() {
  _origUpdatePomoDisplay();
  if(pomoFsOpen) updatePomoFsDisplay();
};

