// ══════════════════════════════════════════════════════
//  NOTIFICATIONS
// ══════════════════════════════════════════════════════
let notifEnabled = localStorage.getItem('notif_enabled') === '1';
let notifCheckInterval = null;

function updateNotifPill() {
  var dot = document.getElementById('notif-dot');
  var lbl = document.getElementById('notif-label');
  if(!dot || !lbl) return;
  if(Notification.permission === 'granted' && notifEnabled) {
    dot.className = 'ndot on';
    lbl.textContent = 'NOTIFICACIONS ACTIVES';
  } else if(Notification.permission === 'denied') {
    dot.className = 'ndot';
    lbl.textContent = 'NOTIFICACIONS BLOQUEJADES';
  } else {
    dot.className = 'ndot';
    lbl.textContent = notifEnabled ? 'NOTIFICACIONS ACTIVES' : 'ACTIVAR NOTIFICACIONS';
  }
}

function toggleNotifications() {
  if(Notification.permission === 'denied') {
    alert('Les notificacions estan bloquejades al navegador. Ves a Configuració del navegador > Lloc web > Notificacions per desbloquejar-les.');
    return;
  }
  if(Notification.permission === 'default') {
    Notification.requestPermission().then(function(perm) {
      if(perm === 'granted') {
        notifEnabled = true;
        localStorage.setItem('notif_enabled', '1');
        scheduleNotifications();
        showSyncToast('🔔 Notificacions activades!');
      }
      updateNotifPill();
    });
    return;
  }
  // Toggle on/off
  notifEnabled = !notifEnabled;
  localStorage.setItem('notif_enabled', notifEnabled ? '1' : '0');
  if(notifEnabled) {
    scheduleNotifications();
    showSyncToast('🔔 Notificacions activades!');
  } else {
    if(notifCheckInterval) { clearInterval(notifCheckInterval); notifCheckInterval = null; }
    showSyncToast('🔕 Notificacions desactivades');
  }
  updateNotifPill();
}

function scheduleNotifications() {
  if(notifCheckInterval) clearInterval(notifCheckInterval);
  // Check every minute
  notifCheckInterval = setInterval(checkAndFireNotifications, 60000);
  checkAndFireNotifications();
}

var firedNotifs = JSON.parse(localStorage.getItem('fired_notifs_v1') || '{}');

function checkAndFireNotifications() {
  if(!notifEnabled || Notification.permission !== 'granted') return;
  var now = new Date();
  var todayKey = toLocalDateKey(now);
  var hhmm = String(now.getHours()).padStart(2,'0') + ':' + String(now.getMinutes()).padStart(2,'0');

  // Check month events for today with a time
  var todayEvs = (monthEvents[todayKey] || []);
  todayEvs.forEach(function(ev) {
    if(!ev.time) return;
    var notifTime = ev.time.substring(0,5);
    var fireKey = todayKey + '_' + (ev.id || ev.text);
    if(notifTime === hhmm && !firedNotifs[fireKey]) {
      new Notification('JOmaxPath 📅', { body: ev.text || 'Event', icon: '' });
      firedNotifs[fireKey] = 1;
      // Clean old fired notifs (keep only today)
      Object.keys(firedNotifs).forEach(function(k){ if(!k.startsWith(todayKey)) delete firedNotifs[k]; });
      localStorage.setItem('fired_notifs_v1', JSON.stringify(firedNotifs));
    }
  });

  // Check timed events for today
  var todayTimed = timedEvents.filter(function(e){ return e.date === todayKey; });
  todayTimed.forEach(function(ev) {
    var notifTime = (ev.start||'').substring(0,5);
    var fireKey = todayKey + '_timed_' + ev.id;
    if(notifTime === hhmm && !firedNotifs[fireKey]) {
      new Notification('JOmaxPath ⏰', { body: (ev.title||'Event') + (ev.end ? ' — fins les ' + ev.end : '') });
      firedNotifs[fireKey] = 1;
      localStorage.setItem('fired_notifs_v1', JSON.stringify(firedNotifs));
    }
  });

  var userName = (typeof profileData !== 'undefined' && profileData.username) ? profileData.username : null;
  var notifDays = (typeof profileData !== 'undefined' && profileData.notifDays) ? parseInt(profileData.notifDays) : 2;
  var namePrefix = userName ? userName + ', ' : '';

  // ── Exams i tasques personals ──
  if(typeof examList !== 'undefined') {
    examList.filter(function(e){ return !e.done && e.date; }).forEach(function(ex) {
      var d = new Date(ex.date + 'T00:00:00');
      var diff = Math.round((d - now) / 86400000);
      // Notificar X dies abans a les 09:00 i el dia mateix a les 08:00
      var shouldFire = false;
      var fireKey = '';
      if(diff === notifDays && hhmm === '09:00') {
        fireKey = 'exam_' + notifDays + 'd_' + ex.id;
        shouldFire = true;
      } else if(diff === 1 && hhmm === '09:00') {
        fireKey = 'exam_1d_' + ex.id;
        shouldFire = true;
      } else if(diff === 0 && hhmm === '08:00') {
        fireKey = 'exam_0d_' + ex.id;
        shouldFire = true;
      }
      if(shouldFire && fireKey && !firedNotifs[fireKey]) {
        var msg = diff === 0
          ? namePrefix + 'Avui tens: ' + ex.name
          : diff === 1
            ? namePrefix + 'Demà: ' + ex.name
            : namePrefix + 'En ' + diff + ' dies: ' + ex.name;
        new Notification('JOmaxPath 📋', { body: msg });
        firedNotifs[fireKey] = 1;
        localStorage.setItem('fired_notifs_v1', JSON.stringify(firedNotifs));
      }
    });
  }

  // ── Tasques Kanban compartides ──
  if(typeof sharedBoards !== 'undefined') {
    Object.values(sharedBoards).forEach(function(board) {
      Object.values(board.tasks || {}).forEach(function(task) {
        if(task.status === 'done' || !task.due) return;
        var d = new Date(task.due + 'T00:00:00');
        var diff = Math.round((d - now) / 86400000);
        var shouldFire = false; var fireKey = '';
        if(diff === notifDays && hhmm === '09:00') { fireKey = 'kbt_' + notifDays + 'd_' + task.id; shouldFire = true; }
        else if(diff === 1 && hhmm === '09:00') { fireKey = 'kbt_1d_' + task.id; shouldFire = true; }
        else if(diff === 0 && hhmm === '08:00') { fireKey = 'kbt_0d_' + task.id; shouldFire = true; }
        if(shouldFire && fireKey && !firedNotifs[fireKey]) {
          var msg = diff === 0
            ? namePrefix + '[' + board.name + '] Avui acaba: ' + task.title
            : diff === 1
              ? namePrefix + '[' + board.name + '] Demà acaba: ' + task.title
              : namePrefix + '[' + board.name + '] En ' + diff + ' dies acaba: ' + task.title;
          new Notification('JOmaxPath 🤝', { body: msg });
          firedNotifs[fireKey] = 1;
          localStorage.setItem('fired_notifs_v1', JSON.stringify(firedNotifs));
        }
      });
    });
  }

  // ── Tasques Kanban personals ──
  if(typeof personalKanbanTasks !== 'undefined') {
    Object.values(personalKanbanTasks).forEach(function(task) {
      if(task.status === 'done' || !task.due) return;
      var d = new Date(task.due + 'T00:00:00');
      var diff = Math.round((d - now) / 86400000);
      var shouldFire = false; var fireKey = '';
      if(diff === notifDays && hhmm === '09:00') { fireKey = 'pkt_' + notifDays + 'd_' + task.id; shouldFire = true; }
      else if(diff === 1 && hhmm === '09:00') { fireKey = 'pkt_1d_' + task.id; shouldFire = true; }
      else if(diff === 0 && hhmm === '08:00') { fireKey = 'pkt_0d_' + task.id; shouldFire = true; }
      if(shouldFire && fireKey && !firedNotifs[fireKey]) {
        var msg = diff === 0
          ? namePrefix + 'Avui acaba: ' + task.title
          : diff === 1
            ? namePrefix + 'Demà acaba: ' + task.title
            : namePrefix + 'En ' + diff + ' dies acaba: ' + task.title;
        new Notification('JOmaxPath 📋', { body: msg });
        firedNotifs[fireKey] = 1;
        localStorage.setItem('fired_notifs_v1', JSON.stringify(firedNotifs));
      }
    });
  }
}

// Init notifications on page load
document.addEventListener('DOMContentLoaded', function() {
  updateNotifPill();
  if(notifEnabled && Notification.permission === 'granted') {
    scheduleNotifications();
  }
});

