// ── Persistència local (offline) ───────────────────────
function loadSharedBoards() {
  sharedBoards = JSON.parse(localStorage.getItem('shared_boards_v1') || '{}');
}
function saveSharedBoardsLocal() {
  localStorage.setItem('shared_boards_v1', JSON.stringify(sharedBoards));
}

// ── Supabase: guardar tauler (taula shared_boards) ─────
async function syncBoardToSupabase(boardId) {
  if(!supa || !supaUser) return;
  const board = sharedBoards[boardId];
  if(!board) return;
  try {
    await supa.from('shared_boards').upsert({
      id: boardId,
      data: board,
      updated_at: new Date().toISOString()
    }, { onConflict: 'id' });
  } catch(e) { console.warn('[Kanban] Error sync:', e); }
}

async function loadBoardsFromSupabase() {
  if(!supa || !supaUser) return;
  try {
    // Carregar taulers on l'usuari és membre o creador
    const email = supaUser.email;
    const { data, error } = await supa.from('shared_boards').select('id, data');
    if(error) { console.warn('[Kanban] Error carregant taulers:', error.message); return; }
    if(!data) return;
    data.forEach(row => {
      const b = row.data;
      if(!b) return;
      // Mostrar si és creador o membre
      const isMember = (b.createdBy === email) || (b.members||[]).includes(email);
      if(isMember) sharedBoards[row.id] = b;
    });
    saveSharedBoardsLocal();
  } catch(e) { console.warn('[Kanban] Error carregant:', e); }
}

// ── Renderitzar llista de taulers ─────────────────────
function renderSharedBoards() {
  const listView = document.getElementById('shared-boards-list-view');
  const detail = document.getElementById('shared-board-detail');
  if(activeBoardId) {
    if(listView) listView.style.display='none';
    if(detail) { detail.style.display=''; renderBoardDetail(activeBoardId); }
    return;
  }
  if(listView) listView.style.display='';
  if(detail) detail.style.display='none';

  // Actualitzar grid llista
  const grid = document.getElementById('shared-boards-grid');
  const ids = Object.keys(sharedBoards);
  const emptyHtml = `<div class="board-empty-state"><div class="board-empty-icon">🤝</div><p>Encara no tens cap llista compartida.<br>Crea'n una nova o espera ser convidat/da.</p></div>`;

  if(grid) {
    grid.innerHTML = !ids.length ? emptyHtml : `<div class="boards-grid">${ids.map(id=>{
      const b = sharedBoards[id];
      const taskCount = Object.keys(b.tasks||{}).length;
      const memberCount = (b.members||[]).length + 1;
      return `<div class="board-card" onclick="openBoardDetail('${id}')">
        <button class="board-card-del" onclick="event.stopPropagation();openEditBoardModal('${id}')" title="Editar membres">✏️</button>
        <button class="board-card-del" onclick="event.stopPropagation();deleteBoard('${id}')" title="Eliminar" style="right:44px;">🗑</button>
        <div class="board-card-name">${b.name}</div>
        <div class="board-card-desc">${b.desc||''}</div>
        <div class="board-card-meta">
          <span>📋 ${taskCount} tasca${taskCount!==1?'s':''}</span>
          <span>👥 ${memberCount} membre${memberCount!==1?'s':''}</span>
        </div>
      </div>`;
    }).join('')}</div>`;
  }

  // Si estem en vista kanban, actualitzar selector i board
  if(sharedView === 'kanban') renderSharedKanbanDirect();
}

function openBoardDetail(boardId) {
  activeBoardId = boardId;
  renderSharedBoards();
}
function closeBoardDetail() {
  activeBoardId = null;
  renderSharedBoards();
}

// ── Renderitzar detall (Kanban) ────────────────────────
function renderBoardDetail(boardId) {
  const board = sharedBoards[boardId];
  if(!board) return;
  const detail = document.getElementById('shared-board-detail');

  const cols = [
    { id:'todo',  label:{ca:'PER COMENÇAR',es:'POR HACER',   en:'TO DO'}[currentLang]||'PER COMENÇAR', cls:'kcol-todo' },
    { id:'doing', label:{ca:'EN CURS',      es:'EN PROGRESO', en:'IN PROGRESS'}[currentLang]||'EN CURS', cls:'kcol-doing' },
    { id:'done',  label:{ca:'FINALITZADES', es:'HECHO',       en:'DONE'}[currentLang]||'FINALITZADES', cls:'kcol-done' },
  ];

  const tasks = board.tasks || {};
  const memberList = [board.createdBy, ...(board.members||[])].filter(Boolean).join(' · ');

  detail.innerHTML = `
    <div class="board-detail-header">
      <button class="board-back-btn" onclick="closeBoardDetail()">← Tornar</button>
      <div>
        <div class="board-detail-name">${board.name}</div>
        <div class="board-members-row">👥 ${memberList}</div>
      </div>
      <button class="board-add-task-btn" onclick="openBoardTaskModal('todo')">+ Tasca</button>
    </div>
    <div class="kanban-board">
      ${cols.map(col => {
        const colTasks = Object.values(tasks).filter(t=>t.status===col.id);
        colTasks.sort((a,b)=>{ const ord={red:0,yellow:1,green:2}; return (ord[a.urgency]||1)-(ord[b.urgency]||1); });
        return `<div class="kanban-col ${col.cls}" id="kcol-${col.id}">
          <div class="kanban-col-header">
            <span class="kanban-col-title">${col.label}</span>
            <span class="kanban-col-count">${colTasks.length}</span>
          </div>
          ${colTasks.map(task=>renderKanbanCard(task, boardId, false)).join('')}
          <div class="kanban-add-area" onclick="openBoardTaskModal('${col.id}')">${{ca:'+ Afegir tasca',es:'+ Añadir tarea',en:'+ Add task'}[currentLang]||'+ Afegir tasca'}</div>
        </div>`;
      }).join('')}
    </div>`;
}

function renderKanbanCard(task, boardId, isPersonal) {
  const today = toLocalDateKey(new Date());
  const isOverdue = task.due && task.due < today && task.status !== 'done';
  const hasNotes = task.notes && task.notes.length > 0;
  const dueLabel = task.due ? `📅 ${task.due}` : '';
  const cols = ['todo','doing','done'];
  const idx = cols.indexOf(task.status);
  const canLeft  = idx > 0;
  const canRight = idx < cols.length - 1;
  const bid = boardId || activeBoardId || '';
  const onClickFn = isPersonal
    ? `openPersonalTaskDetail('${task.id}')`
    : `openTaskDetail('${bid}','${task.id}')`;
  const leftFn  = isPersonal
    ? `event.stopPropagation();movePersonalTask('${task.id}','${cols[idx-1]}')`
    : `event.stopPropagation();moveKanbanTask('${bid}','${task.id}','${cols[idx-1]}')`;
  const rightFn = isPersonal
    ? `event.stopPropagation();movePersonalTask('${task.id}','${cols[idx+1]}')`
    : `event.stopPropagation();moveKanbanTask('${bid}','${task.id}','${cols[idx+1]}')`;
  const delFn = isPersonal
    ? `event.stopPropagation();deletePersonalKanbanTask('${task.id}')`
    : `event.stopPropagation();deleteKanbanTask('${bid}','${task.id}')`;
  return `<div class="kanban-task-card urg-${task.urgency||'green'}"
      draggable="true"
      data-taskid="${task.id}"
      data-boardid="${bid}"
      data-ispersonal="${isPersonal?'1':'0'}"
      ondragstart="onKanbanDragStart(event)"
      onclick="${onClickFn}">
    <div class="kcard-title">${task.title}</div>
    <div class="kcard-meta">
      <span class="kcard-urgency-dot urg-${task.urgency||'green'}"></span>
      ${task.assignee ? `<span class="kcard-assignee">👤 ${task.assignee}</span>` : ''}
      ${dueLabel ? `<span class="kcard-due${isOverdue?' overdue':''}">${dueLabel}</span>` : ''}
      ${hasNotes ? `<span class="kcard-note-icon">💬 ${task.notes.length}</span>` : ''}
    </div>
    <div class="kcard-actions" onclick="event.stopPropagation()">
      <button class="kcard-arrow-btn" ${canLeft?`onclick="${leftFn}"`:'disabled style="opacity:0.2;cursor:default;"'}>←</button>
      <button class="kcard-del-btn" onclick="${delFn}">×</button>
      <button class="kcard-arrow-btn" ${canRight?`onclick="${rightFn}"`:'disabled style="opacity:0.2;cursor:default;"'}>→</button>
    </div>
  </div>`;
}


// ── Modals tauler ──────────────────────────────────────
function openCreateBoardModal() {
  document.getElementById('board-name-inp').value='';
  document.getElementById('board-desc-inp').value='';
  document.getElementById('board-members-inp').value='';
  document.getElementById('board-modal-title').textContent='Nova llista compartida';
  document.getElementById('board-modal-overlay').style.display='flex';
  setTimeout(()=>document.getElementById('board-name-inp').focus(), 80);
}
function closeBoardModal() {
  document.getElementById('board-modal-overlay').style.display='none';
}
function saveBoardModal() {
  const name = document.getElementById('board-name-inp').value.trim();
  if(!name) { document.getElementById('board-name-inp').focus(); return; }
  const desc = document.getElementById('board-desc-inp').value.trim();
  const rawMembers = document.getElementById('board-members-inp').value.trim();
  const members = rawMembers ? rawMembers.split('\n').map(s=>s.trim()).filter(Boolean) : [];

  const boardId = 'board_' + Date.now();
  sharedBoards[boardId] = {
    id: boardId,
    name, desc, members,
    tasks: {},
    createdBy: supaUser?.email || 'local',
    createdAt: new Date().toISOString()
  };
  saveSharedBoardsLocal();
  syncBoardToSupabase(boardId);
  closeBoardModal();
  renderSharedBoards();
}
function deleteBoard(boardId) {
  if(!confirm('Vols eliminar aquesta llista i totes les seves tasques?')) return;
  delete sharedBoards[boardId];
  saveSharedBoardsLocal();
  if(supa && supaUser) {
    supa.from('shared_boards').delete().eq('id', boardId).then(()=>{});
  }
  if(activeBoardId===boardId) activeBoardId=null;
  renderSharedBoards();
}

// ── Modal nova tasca ───────────────────────────────────
function openBoardTaskModal(colStatus) {
  btEditingColStatus = colStatus || 'todo';
  btUrgency = 'green';
  document.getElementById('bt-title-inp').value='';
  document.getElementById('bt-desc-inp').value='';
  document.getElementById('bt-assignee-inp').value='';
  document.getElementById('bt-due-inp').value='';
  document.querySelectorAll('.bt-urg-btn').forEach(b=>b.classList.remove('active'));
  document.querySelector('.bt-urg-btn[data-u="green"]').classList.add('active');
  document.getElementById('board-task-modal-overlay').style.display='flex';
  setTimeout(()=>document.getElementById('bt-title-inp').focus(), 80);
}
function closeBoardTaskModal() {
  document.getElementById('board-task-modal-overlay').style.display='none';
}
function selectBtUrgency(btn) {
  btUrgency = btn.dataset.u;
  document.querySelectorAll('.bt-urg-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
}
function saveBoardTask() {
  const title = document.getElementById('bt-title-inp').value.trim();
  if(!title) { document.getElementById('bt-title-inp').focus(); return; }
  if(!activeBoardId) return;
  const board = sharedBoards[activeBoardId];
  const taskId = 'task_' + Date.now();
  const btLinkUrl   = document.getElementById('bt-link-url-inp')?.value.trim();
  const btLinkLabel = document.getElementById('bt-link-label-inp')?.value.trim();
  const btAssignee  = document.getElementById('bt-assignee-inp').value.trim();
  board.tasks[taskId] = {
    id: taskId,
    title,
    desc: document.getElementById('bt-desc-inp').value.trim(),
    assignee: btAssignee,
    assignees: btAssignee ? [btAssignee] : [],
    due: document.getElementById('bt-due-inp').value,
    urgency: btUrgency,
    status: btEditingColStatus,
    notes: [],
    links: (btLinkUrl ? [{url: btLinkUrl, label: btLinkLabel || btLinkUrl}] : []),
    createdAt: new Date().toISOString(),
    createdBy: supaUser?.email || 'local'
  };
  saveSharedBoardsLocal();
  syncBoardToSupabase(activeBoardId);
  closeBoardTaskModal();
  renderBoardDetail(activeBoardId);
}

// ── Detall de tasca ────────────────────────────────────
let tdmDirty = false;
let tdmCurrentUrgency = 'green';

function tdmMarkDirty() {
  tdmDirty = true;
  const btn = document.getElementById('tdm-save-btn');
  if(btn) btn.style.display = 'block';
}

function tdmSetUrgency(u, btn) {
  tdmCurrentUrgency = u;
  const colors = {green:'#6ee7b7', yellow:'#fcd34d', red:'#f87171'};
  const bar = document.getElementById('tdm-urgency-bar');
  if(bar) bar.style.background = colors[u];
  document.querySelectorAll('.tdm-urg-pill, .tdm-urg-btn').forEach(b=>b.classList.remove('active'));
  if(btn) btn.classList.add('active');
  tdmMarkDirty();
}

function tdmSetStatus(s, btn) {
  // Actualitzar select hidden
  const sel = document.getElementById('tdm-status');
  if(sel) sel.value = s;
  // Pills visuals
  document.querySelectorAll('.tdm-status-pill').forEach(b=>b.classList.remove('active'));
  if(btn) btn.classList.add('active');
  // Aplicar canvi immediatament
  updateTaskStatusFromDetail(s);
}

function tdmAddAssignee() {
  const inp = document.getElementById('tdm-assignee-inp');
  const val = inp.value.trim();
  if(!val) return;
  const task = _tdmGetTask();
  if(!task) return;
  if(!task.assignees) task.assignees = task.assignee ? [task.assignee] : [];
  if(!task.assignees.includes(val)) task.assignees.push(val);
  task.assignee = task.assignees[0]; // compat
  inp.value = '';
  tdmRenderAssignees(task);
  tdmMarkDirty();
}

function tdmRemoveAssignee(idx) {
  const task = _tdmGetTask();
  if(!task?.assignees) return;
  task.assignees.splice(idx, 1);
  task.assignee = task.assignees[0] || '';
  tdmRenderAssignees(task);
  tdmMarkDirty();
}

function tdmRenderAssignees(task) {
  const el = document.getElementById('tdm-assignees-chips');
  if(!el) return;
  const list = task.assignees?.length ? task.assignees : (task.assignee ? [task.assignee] : []);
  el.innerHTML = list.length
    ? list.map((a,i)=>`<div class="tdm-chip"><span>${a}</span><button class="tdm-chip-del" onclick="tdmRemoveAssignee(${i})">×</button></div>`).join('')
    : '<span style="color:rgba(255,255,255,0.2);font-size:11px;">Sense responsables</span>';
}

function tdmAddLink() {
  const urlInp   = document.getElementById('tdm-link-url-inp');
  const lblInp   = document.getElementById('tdm-link-label-inp');
  const url   = urlInp.value.trim();
  const label = lblInp.value.trim() || url;
  if(!url) { urlInp.focus(); return; }
  const task = _tdmGetTask();
  if(!task) return;
  if(!task.links) task.links = [];
  task.links.push({ url, label });
  urlInp.value = ''; lblInp.value = '';
  tdmRenderLinks(task);
  tdmMarkDirty();
}

function tdmRemoveLink(idx) {
  const task = _tdmGetTask();
  if(!task?.links) return;
  task.links.splice(idx, 1);
  tdmRenderLinks(task);
  tdmMarkDirty();
}

function tdmRenderLinks(task) {
  const el = document.getElementById('tdm-links-list');
  if(!el) return;
  const links = task.links || [];
  el.innerHTML = links.length
    ? links.map((l,i)=>`<div class="tdm-link-item">
        <a href="${l.url}" target="_blank" rel="noopener">🔗 ${l.label||l.url}</a>
        <button class="tdm-link-del" onclick="tdmRemoveLink(${i})">×</button>
      </div>`).join('')
    : '<span style="color:rgba(255,255,255,0.2);font-size:11px;">Sense enllaços</span>';
}

function _tdmGetTask() {
  if(detailBoardId === '__personal__') return personalKanbanTasks[detailTaskId];
  return sharedBoards[detailBoardId]?.tasks[detailTaskId];
}

function tdmSaveChanges() {
  const task = _tdmGetTask();
  if(!task) return;
  task.title    = document.getElementById('tdm-title').value.trim() || task.title;
  task.desc     = document.getElementById('tdm-desc').value.trim();
  task.due      = document.getElementById('tdm-due').value;
  task.urgency  = tdmCurrentUrgency;
  // Assignees already updated live via tdmAddAssignee/tdmRemoveAssignee

  // Update urgency bar color
  const colors = {green:'#6ee7b7', yellow:'#fcd34d', red:'#f87171'};
  document.getElementById('tdm-urgency-bar').style.background = colors[tdmCurrentUrgency];

  if(detailBoardId === '__personal__') {
    savePersonalKanban();
    renderPersonalKanban();
  } else {
    saveSharedBoardsLocal();
    syncBoardToSupabase(detailBoardId);
    if(activeBoardId === detailBoardId) renderBoardDetail(detailBoardId);
    if(sharedKanbanActiveBoardId === detailBoardId) renderSharedKanbanDirect();
  }

  tdmDirty = false;
  const btn = document.getElementById('tdm-save-btn');
  if(btn) { btn.textContent = '✅ Guardat!'; setTimeout(()=>{ btn.textContent='💾 Guardar canvis'; btn.style.display='none'; }, 1500); }
}

function openTaskDetail(boardId, taskId) {
  detailBoardId = boardId;
  detailTaskId = taskId;
  const task = sharedBoards[boardId]?.tasks[taskId];
  if(!task) return;
  tdmPopulate(task);
}

function tdmPopulate(task) {
  tdmDirty = false;
  tdmCurrentUrgency = task.urgency || 'green';
  const colors = {green:'#6ee7b7', yellow:'#fcd34d', red:'#f87171'};

  // Strip urgència
  const bar = document.getElementById('tdm-urgency-bar');
  if(bar) bar.style.background = colors[tdmCurrentUrgency];

  // Títol, desc, data
  const titleEl = document.getElementById('tdm-title');
  if(titleEl) titleEl.value = task.title || '';
  const descEl = document.getElementById('tdm-desc');
  if(descEl) descEl.value = task.desc || '';
  const dueEl = document.getElementById('tdm-due');
  if(dueEl) dueEl.value = task.due || '';

  // Select hidden (compat)
  const statusSel = document.getElementById('tdm-status');
  if(statusSel) statusSel.value = task.status || 'todo';

  // Pills d'estat
  document.querySelectorAll('.tdm-status-pill').forEach(b=>{
    b.classList.toggle('active', b.dataset.s === (task.status||'todo'));
  });

  // Pills d'urgència
  document.querySelectorAll('.tdm-urg-pill').forEach(b=>{
    b.classList.toggle('active', b.dataset.u === tdmCurrentUrgency);
  });

  tdmRenderAssignees(task);
  tdmRenderLinks(task);
  renderTaskNotes(task);

  const saveBtn = document.getElementById('tdm-save-btn');
  if(saveBtn) saveBtn.style.display = 'none';

  document.getElementById('task-detail-overlay').style.display='flex';
}

function closeTaskDetail() {
  if(tdmDirty) {
    if(!confirm('Tens canvis sense guardar. Vols sortir igualment?')) return;
  }
  document.getElementById('task-detail-overlay').style.display='none';
  detailBoardId=null; detailTaskId=null; tdmDirty=false;
}
function renderTaskNotes(task) {
  const list = document.getElementById('tdm-notes-list');
  if(!list) return;
  const notes = task.notes || [];
  list.innerHTML = notes.length ? notes.map((n,i)=>`
    <div class="tdm-note-item">
      <div class="tdm-note-text">${n.text}</div>
      <div class="tdm-note-meta">${n.author||''} · ${(n.date||'').slice(0,10)}</div>
      <button class="tdm-note-del" onclick="deleteTaskNote(${i})">×</button>
    </div>`).join('') : '<div style="color:rgba(255,255,255,0.2);font-size:12px;">Sense notes.</div>';
}
function addNoteToTask() {
  const inp = document.getElementById('tdm-note-inp');
  const text = inp.value.trim();
  if(!text) return;
  const task = sharedBoards[detailBoardId]?.tasks[detailTaskId];
  if(!task) return;
  if(!task.notes) task.notes=[];
  task.notes.push({ text, author: supaUser?.email||'jo', date: new Date().toISOString() });
  saveSharedBoardsLocal();
  syncBoardToSupabase(detailBoardId);
  inp.value='';
  renderTaskNotes(task);
  renderBoardDetail(detailBoardId);
}
function deleteTaskNote(idx) {
  const task = sharedBoards[detailBoardId]?.tasks[detailTaskId];
  if(!task?.notes) return;
  task.notes.splice(idx,1);
  saveSharedBoardsLocal();
  syncBoardToSupabase(detailBoardId);
  renderTaskNotes(task);
  renderBoardDetail(detailBoardId);
}
function updateTaskStatusFromDetail(newStatus) {
  const task = sharedBoards[detailBoardId]?.tasks[detailTaskId];
  if(!task) return;
  task.status = newStatus;
  saveSharedBoardsLocal();
  syncBoardToSupabase(detailBoardId);
  renderBoardDetail(detailBoardId);
}

// ── Init Kanban ────────────────────────────────────────
loadSharedBoards();
// Si l'usuari ja ha iniciat sessió, carregar els taulers del servidor
document.addEventListener('DOMContentLoaded', () => {
  setTimeout(async () => {
    if(supa && supaUser) await loadBoardsFromSupabase();
  }, 2000);
});

// ══════════════════════════════════════════════════════
//  KANBAN PERSONAL (vista kanban de les tasques personals)
// ══════════════════════════════════════════════════════

let personalKanbanTasks = JSON.parse(localStorage.getItem('personal_kanban_v1') || '{}');

function savePersonalKanban() {
  localStorage.setItem('personal_kanban_v1', JSON.stringify(personalKanbanTasks));
}

function renderPersonalKanban() {
  const board = document.getElementById('personal-kanban-board');
  if(!board) return;
  const cols = [
    { id:'todo',  label:{ca:'PER COMENÇAR',es:'POR HACER',   en:'TO DO'}[currentLang]||'PER COMENÇAR', cls:'kcol-todo' },
    { id:'doing', label:{ca:'EN CURS',      es:'EN PROGRESO', en:'IN PROGRESS'}[currentLang]||'EN CURS', cls:'kcol-doing' },
    { id:'done',  label:{ca:'FINALITZADES', es:'HECHO',       en:'DONE'}[currentLang]||'FINALITZADES', cls:'kcol-done' },
  ];
  board.className = 'kanban-board';
  board.innerHTML = cols.map(col => {
    const tasks = Object.values(personalKanbanTasks).filter(t=>t.status===col.id);
    tasks.sort((a,b)=>{ const ord={red:0,yellow:1,green:2}; return (ord[a.urgency]||1)-(ord[b.urgency]||1); });
    return `<div class="kanban-col ${col.cls}" id="pkcol-${col.id}"
        ondragover="event.preventDefault();this.classList.add('drag-over')"
        ondragleave="this.classList.remove('drag-over')"
        ondrop="onKanbanDrop(event,'${col.id}',true)">
      <div class="kanban-col-header">
        <span class="kanban-col-title">${col.label}</span>
        <span class="kanban-col-count">${tasks.length}</span>
      </div>
      ${tasks.map(t=>renderKanbanCard(t,'',true)).join('')}
      <div class="kanban-add-area" onclick="openPersonalKanbanModal('${col.id}')">${{ca:'+ Afegir tasca',es:'+ Añadir tarea',en:'+ Add task'}[currentLang]||'+ Afegir tasca'}</div>
    </div>`;
  }).join('');
}

function openPersonalKanbanModal(colStatus) {
  btEditingColStatus = colStatus || 'todo';
  btUrgency = 'green';
  document.getElementById('bt-title-inp').value='';
  document.getElementById('bt-desc-inp').value='';
  document.getElementById('bt-assignee-inp').value='';
  document.getElementById('bt-due-inp').value='';
  document.querySelectorAll('.bt-urg-btn').forEach(b=>b.classList.remove('active'));
  document.querySelector('.bt-urg-btn[data-u="green"]').classList.add('active');
  // Reaprofitem el modal de board task però per personal
  const modal = document.getElementById('board-task-modal-overlay');
  modal.dataset.mode = 'personal';
  modal.style.display='flex';
  setTimeout(()=>document.getElementById('bt-title-inp').focus(), 80);
}

function savePersonalKanbanTask() {
  const title = document.getElementById('bt-title-inp').value.trim();
  if(!title) return;
  const taskId = 'pk_' + Date.now();
  const pkLinkUrl   = document.getElementById('bt-link-url-inp')?.value.trim();
  const pkLinkLabel = document.getElementById('bt-link-label-inp')?.value.trim();
  const pkAssignee  = document.getElementById('bt-assignee-inp').value.trim();
  personalKanbanTasks[taskId] = {
    id: taskId,
    title,
    desc: document.getElementById('bt-desc-inp').value.trim(),
    assignee: pkAssignee,
    assignees: pkAssignee ? [pkAssignee] : [],
    due: document.getElementById('bt-due-inp').value,
    urgency: btUrgency,
    status: btEditingColStatus,
    notes: [],
    links: (pkLinkUrl ? [{url: pkLinkUrl, label: pkLinkLabel || pkLinkUrl}] : []),
    createdAt: new Date().toISOString()
  };
  savePersonalKanban();
  closeBoardTaskModal();
  renderPersonalKanban();
}

function movePersonalTask(taskId, newStatus) {
  if(!personalKanbanTasks[taskId]) return;
  const oldStatus = personalKanbanTasks[taskId].status;
  personalKanbanTasks[taskId].status = newStatus;
  savePersonalKanban();
  _playMoveAnimation(oldStatus, newStatus, ()=>renderPersonalKanban());
}

function deletePersonalKanbanTask(taskId) {
  if(!confirm('Eliminar aquesta tasca?')) return;
  delete personalKanbanTasks[taskId];
  savePersonalKanban();
  renderPersonalKanban();
}

function openPersonalTaskDetail(taskId) {
  const task = personalKanbanTasks[taskId];
  if(!task) return;
  detailBoardId = '__personal__';
  detailTaskId  = taskId;
  tdmPopulate(task);
}

// Override updateTaskStatusFromDetail per suportar personal
const _origUpdateStatus = updateTaskStatusFromDetail;
updateTaskStatusFromDetail = function(newStatus) {
  if(detailBoardId === '__personal__') {
    if(personalKanbanTasks[detailTaskId]) {
      personalKanbanTasks[detailTaskId].status = newStatus;
      savePersonalKanban();
      renderPersonalKanban();
    }
    return;
  }
  _origUpdateStatus(newStatus);
};

// Override addNoteToTask per suportar personal
const _origAddNote = addNoteToTask;
addNoteToTask = function() {
  if(detailBoardId === '__personal__') {
    const inp = document.getElementById('tdm-note-inp');
    const text = inp.value.trim();
    if(!text) return;
    const task = personalKanbanTasks[detailTaskId];
    if(!task) return;
    if(!task.notes) task.notes=[];
    task.notes.push({ text, author: supaUser?.email||'jo', date: new Date().toISOString() });
    savePersonalKanban();
    inp.value='';
    renderTaskNotes(task);
    renderPersonalKanban();
    return;
  }
  _origAddNote();
};

// Override saveBoardTask per mode personal
const _origSaveBoardTask = saveBoardTask;
saveBoardTask = function() {
  const modal = document.getElementById('board-task-modal-overlay');
  if(modal?.dataset.mode === 'personal') {
    modal.dataset.mode = '';
    savePersonalKanbanTask();
    return;
  }
  _origSaveBoardTask();
};

// ══════════════════════════════════════════════════════
//  KANBAN COMPARTIT VISTA DIRECTA (sense entrar al detall)
// ══════════════════════════════════════════════════════

function renderSharedKanbanDirect() {
  const selector = document.getElementById('shared-board-selector');
  const container = document.getElementById('shared-kanban-board-container');
  if(!selector || !container) return;

  const ids = Object.keys(sharedBoards);
  if(!ids.length) {
    selector.innerHTML = '';
    container.innerHTML = `<div class="board-empty-state"><div class="board-empty-icon">🤝</div><p>Cap llista compartida.</p></div>`;
    return;
  }

  if(!sharedKanbanActiveBoardId || !sharedBoards[sharedKanbanActiveBoardId]) {
    sharedKanbanActiveBoardId = ids[0];
  }

  selector.innerHTML = `<div class="board-selector-row">${ids.map(id=>`
    <button class="board-selector-chip${id===sharedKanbanActiveBoardId?' active':''}"
      onclick="sharedKanbanActiveBoardId='${id}';renderSharedKanbanDirect()">
      ${sharedBoards[id].name}
    </button>`).join('')}</div>`;

  // Renderitzar kanban del board seleccionat
  const board = sharedBoards[sharedKanbanActiveBoardId];
  const cols = [
    { id:'todo',  label:{ca:'PER COMENÇAR',es:'POR HACER',   en:'TO DO'}[currentLang]||'PER COMENÇAR', cls:'kcol-todo' },
    { id:'doing', label:{ca:'EN CURS',      es:'EN PROGRESO', en:'IN PROGRESS'}[currentLang]||'EN CURS', cls:'kcol-doing' },
    { id:'done',  label:{ca:'FINALITZADES', es:'HECHO',       en:'DONE'}[currentLang]||'FINALITZADES', cls:'kcol-done' },
  ];
  const tasks = board.tasks || {};
  container.innerHTML = `
    <div style="display:flex;justify-content:flex-end;margin-bottom:12px;">
      <button class="board-add-task-btn" onclick="openBoardTaskModal('todo')">+ Tasca</button>
    </div>
    <div class="kanban-board">
      ${cols.map(col=>{
        const colTasks = Object.values(tasks).filter(t=>t.status===col.id);
        colTasks.sort((a,b)=>{ const ord={red:0,yellow:1,green:2}; return (ord[a.urgency]||1)-(ord[b.urgency]||1); });
        return `<div class="kanban-col ${col.cls}"
            ondragover="event.preventDefault();this.classList.add('drag-over')"
            ondragleave="this.classList.remove('drag-over')"
            ondrop="onKanbanDrop(event,'${col.id}',false)">
          <div class="kanban-col-header">
            <span class="kanban-col-title">${col.label}</span>
            <span class="kanban-col-count">${colTasks.length}</span>
          </div>
          ${colTasks.map(task=>renderKanbanCard(task, sharedKanbanActiveBoardId, false)).join('')}
          <div class="kanban-add-area" onclick="activeBoardId=sharedKanbanActiveBoardId;openBoardTaskModal('${col.id}')">${{ca:'+ Afegir',es:'+ Añadir',en:'+ Add'}[currentLang]||'+ Afegir'}</div>
        </div>`;
      }).join('')}
    </div>`;
}

// ══════════════════════════════════════════════════════
//  DRAG & DROP
// ══════════════════════════════════════════════════════

let dragTaskId = null;
let dragBoardId = null;
let dragIsPersonal = false;

function onKanbanDragStart(event) {
  const card = event.currentTarget;
  dragTaskId    = card.dataset.taskid;
  dragBoardId   = card.dataset.boardid;
  dragIsPersonal = card.dataset.ispersonal === '1';
  card.classList.add('dragging');
  event.dataTransfer.effectAllowed = 'move';
  setTimeout(()=>card.classList.remove('dragging'), 0);
}

function onKanbanDrop(event, newStatus, isPersonal) {
  event.preventDefault();
  document.querySelectorAll('.kanban-col').forEach(c=>c.classList.remove('drag-over'));
  if(!dragTaskId) return;
  if(isPersonal || dragIsPersonal) {
    movePersonalTask(dragTaskId, newStatus);
  } else {
    moveKanbanTask(dragBoardId, dragTaskId, newStatus);
  }
  dragTaskId = dragBoardId = null;
}

// ══════════════════════════════════════════════════════
//  MOURE TASCA (compartida)
// ══════════════════════════════════════════════════════

function moveKanbanTask(boardId, taskId, newStatus) {
  const board = sharedBoards[boardId];
  if(!board?.tasks[taskId]) return;
  const oldStatus = board.tasks[taskId].status;
  board.tasks[taskId].status = newStatus;
  saveSharedBoardsLocal();
  syncBoardToSupabase(boardId);
  _playMoveAnimation(oldStatus, newStatus, ()=>{
    if(activeBoardId === boardId) renderBoardDetail(boardId);
    if(sharedKanbanActiveBoardId === boardId) renderSharedKanbanDirect();
  });
}

function deleteKanbanTask(boardId, taskId) {
  if(!confirm('Eliminar aquesta tasca?')) return;
  const board = sharedBoards[boardId];
  if(!board?.tasks) return;
  delete board.tasks[taskId];
  saveSharedBoardsLocal();
  syncBoardToSupabase(boardId);
  if(activeBoardId === boardId) renderBoardDetail(boardId);
  if(sharedKanbanActiveBoardId === boardId) renderSharedKanbanDirect();
}

// ══════════════════════════════════════════════════════
//  GESTIÓ DE MEMBRES
// ══════════════════════════════════════════════════════

function openCreateBoardModal() {
  editingBoardId = null;
  boardTempMembers = [];
  document.getElementById('board-name-inp').value='';
  document.getElementById('board-desc-inp').value='';
  document.getElementById('board-member-add-inp').value='';
  document.getElementById('board-modal-title').textContent='Nova llista compartida';
  document.getElementById('bm-save-btn').textContent='Crear llista';
  renderBoardMembersChips();
  document.getElementById('board-modal-overlay').style.display='flex';
  setTimeout(()=>document.getElementById('board-name-inp').focus(), 80);
}

function openEditBoardModal(boardId) {
  editingBoardId = boardId;
  const board = sharedBoards[boardId];
  boardTempMembers = [...(board.members||[])];
  document.getElementById('board-name-inp').value = board.name;
  document.getElementById('board-desc-inp').value = board.desc||'';
  document.getElementById('board-member-add-inp').value='';
  document.getElementById('board-modal-title').textContent='Editar llista';
  document.getElementById('bm-save-btn').textContent='Guardar canvis';
  renderBoardMembersChips();
  document.getElementById('board-modal-overlay').style.display='flex';
  setTimeout(()=>document.getElementById('board-name-inp').focus(), 80);
}

function renderBoardMembersChips() {
  const el = document.getElementById('board-members-current');
  if(!el) return;
  el.innerHTML = boardTempMembers.length
    ? boardTempMembers.map((m,i)=>`
        <div class="member-chip">
          <span>${m}</span>
          <button class="member-chip-del" onclick="removeBoardMember(${i})">×</button>
        </div>`).join('')
    : '<span style="color:var(--muted);font-size:11px;">Cap membre afegit</span>';
}

function addBoardMember() {
  const inp = document.getElementById('board-member-add-inp');
  const email = inp.value.trim().toLowerCase();
  if(!email || !email.includes('@')) { inp.focus(); return; }
  if(boardTempMembers.includes(email)) { inp.value=''; return; }
  boardTempMembers.push(email);
  inp.value='';
  renderBoardMembersChips();
}

function removeBoardMember(idx) {
  boardTempMembers.splice(idx, 1);
  renderBoardMembersChips();
}

// Sobreescriure closeBoardModal per netejar
const _origCloseBoardModal = closeBoardModal;
closeBoardModal = function() {
  document.getElementById('board-modal-overlay').style.display='none';
  editingBoardId = null;
  boardTempMembers = [];
};

// Sobreescriure saveBoardModal per gestionar edició
const _origSaveBoardModal = saveBoardModal;
saveBoardModal = function() {
  const name = document.getElementById('board-name-inp').value.trim();
  if(!name) { document.getElementById('board-name-inp').focus(); return; }
  const desc = document.getElementById('board-desc-inp').value.trim();

  if(editingBoardId) {
    // Editar tauler existent
    const board = sharedBoards[editingBoardId];
    board.name = name;
    board.desc = desc;
    board.members = [...boardTempMembers];
    saveSharedBoardsLocal();
    syncBoardToSupabase(editingBoardId);
    closeBoardModal();
    renderSharedBoards();
  } else {
    // Crear tauler nou
    const boardId = 'board_' + Date.now();
    sharedBoards[boardId] = {
      id: boardId, name, desc,
      members: [...boardTempMembers],
      tasks: {},
      createdBy: supaUser?.email || 'local',
      createdAt: new Date().toISOString()
    };
    saveSharedBoardsLocal();
    syncBoardToSupabase(boardId);
    closeBoardModal();
    renderSharedBoards();
  }
};

// ── Drag & drop en el board detail (col·lumnes del board compartit) ──
// Afegir drag events als columnes del board detail
const _origRenderBoardDetail = renderBoardDetail;
renderBoardDetail = function(boardId) {
  _origRenderBoardDetail(boardId);
  // Afegir drag events a les columnes
  document.querySelectorAll('#shared-board-detail .kanban-col').forEach(col => {
    const colId = col.id.replace('kcol-','');
    col.addEventListener('dragover', e=>{ e.preventDefault(); col.classList.add('drag-over'); });
    col.addEventListener('dragleave', ()=>col.classList.remove('drag-over'));
    col.addEventListener('drop', e=>{ e.preventDefault(); col.classList.remove('drag-over'); onKanbanDrop(e, colId, false); });
  });
};

// ══════════════════════════════════════════════════════
//  ANIMACIONS DE MOVIMENT DE TASQUES
// ══════════════════════════════════════════════════════

function _playMoveAnimation(oldStatus, newStatus, callback) {
  const colOrder = ['todo', 'doing', 'done'];
  const oldIdx = colOrder.indexOf(oldStatus);
  const newIdx = colOrder.indexOf(newStatus);
  const forward = newIdx > oldIdx; // endavant = feliç, enrere = trist

  // Overlay d'animació
  const overlay = document.createElement('div');
  overlay.style.cssText = `
    position:fixed; inset:0; z-index:9999; pointer-events:none;
    display:flex; align-items:center; justify-content:center;
    font-size:80px; animation: taskMoveAnim 0.7s ease forwards;
  `;

  if(forward) {
    // 🎉 Animació feliç — confetti + emoji
    overlay.textContent = ['✅','🎯','🚀','⭐','💪'][Math.floor(Math.random()*5)];
    overlay.style.animation = 'taskMoveHappy 0.65s ease forwards';
    // Burst de confetti si existeix la funció
    if(typeof burstConfetti === 'function') {
      burstConfetti(window.innerWidth/2, window.innerHeight/2);
    }
  } else {
    // 😢 Animació trista — emoji trist
    overlay.textContent = ['😓','😬','↩️','🔄','⚠️'][Math.floor(Math.random()*5)];
    overlay.style.animation = 'taskMoveSad 0.65s ease forwards';
  }

  document.body.appendChild(overlay);
  setTimeout(()=>{ overlay.remove(); if(callback) callback(); }, 650);
}

// Injectar keyframes si no existeixen
(function injectTaskMoveStyles() {
  if(document.getElementById('task-move-styles')) return;
  const s = document.createElement('style');
  s.id = 'task-move-styles';
  s.textContent = `
    @keyframes taskMoveHappy {
      0%   { transform: scale(0.3) rotate(-20deg); opacity:0; }
      40%  { transform: scale(1.3) rotate(10deg);  opacity:1; }
      70%  { transform: scale(0.9) rotate(-5deg);  opacity:1; }
      100% { transform: scale(1.1) rotate(0deg);   opacity:0; }
    }
    @keyframes taskMoveSad {
      0%   { transform: scale(0.3) rotate(20deg);  opacity:0; }
      30%  { transform: scale(1.1) rotate(-8deg);  opacity:1; }
      60%  { transform: scale(0.95) rotate(3deg);  opacity:0.9; }
      100% { transform: scale(0.8) rotate(0deg) translateY(20px); opacity:0; }
    }
  `;
  document.head.appendChild(s);
})();

// ══════════════════════════════════════════════════════
//  KANBAN CARD — mostrar links a la targeta
// ══════════════════════════════════════════════════════
// Patch renderKanbanCard per mostrar 🔗 si hi ha links
const _origRenderKanbanCard = renderKanbanCard;
renderKanbanCard = function(task, boardId, isPersonal) {
  let html = _origRenderKanbanCard(task, boardId, isPersonal);
  // Afegir indicador de links si n'hi ha
  if(task.links && task.links.length > 0) {
    html = html.replace(
      '<div class="kcard-meta">',
      `<div class="kcard-links-preview">${task.links.slice(0,2).map(l=>`<a href="${l.url}" target="_blank" rel="noopener" onclick="event.stopPropagation()" class="kcard-link-chip">🔗 ${l.label||'Enllaç'}</a>`).join('')}</div><div class="kcard-meta">`
    );
  }
  return html;
};
